import { stringFormat } from "ultimus";
import { WebClientService } from "@/core";

function createReplaceTagAdapter(ctx: MultiItemsEditFieldController) {
  const [src, trg] = (ctx.expression ?? "").split(">").map((s) => String(s ?? "").trim());

  return (_, item) => {
    const tags = String(item[String(ctx.field)] ?? "").split(",");

    const result = src
      ? tags.map((s) => (s === src ? (trg ? stringFormat(trg, item) : null) : s))
      : trg
        ? tags.concat(stringFormat(trg, item))
        : tags;

    return (
      result
        .filter(Boolean)
        .map((s) => s?.trim())
        // .sort()s
        .join(",")
    );
  };
}

const OPERATIONS = [
  {
    id: "replaceTagForItems",
    name: "replace tag",
    hint: 'Replaces src with target value from expression "src>target" ',
    getValueAdapter: createReplaceTagAdapter,
  },
  {
    id: "resetValueForItems",
    name: "reset value",
    hint: 'Reset field with given value, use "{placeholders}" to refer other fields\' values ',
    getValueAdapter: () => stringFormat,
  },
];
export class MultiItemsEditFieldController extends WebClientService {
  itemsIds?: any[];
  field?: string;
  expression?: string;
  api?: any;
  store: any;
  operation: any;

  get operations() {
    return OPERATIONS;
  }

  get disabled(): boolean {
    return !this.store || !this.itemsIds || !this.operation || !this.field || !this.expression;
  }

  apply() {
    if (this.disabled) return;

    this.up({ isLoading: true, error: null });
    this.api.setFieldForItems({
      ids: this.itemsIds,
      field: this.field,
      value: this.expression,
      store: this.store,
      valueAdapter: this.operations.find((e) => e.id === this.operation)?.getValueAdapter(this),
      callback: ({ error = null, item, data = item }) => {
        if (error) {
          const message = `Error: ${(error as Error)?.message}`;
          this.up({ isLoading: false, error, data });
          this.toast({ id: message, level: "error", message });
        } else {
          const message = "❎ Updated successfully. ";
          this.up({ isLoading: false, data });
          this.toast({ message, timeout: 5000 });
        }
      },
    });
  }
}
