/**
 * String conversion utilities.
 */

/** Converts any value to a string; null/undefined become "". */
export function str(x: unknown): string {
  return x == null ? "" : String(x);
}

/** Converts a value to a JSON string with the given indentation (default 2 spaces). */
export function stringifyJson(x: unknown, indent = 2): string {
  return JSON.stringify(x, null, indent);
}
