import type { StringHash } from "../types";

import { arraySortBy } from "./arraySortBy";
import { arrayToObject } from "./arrayToObject";

/**
 * Builds a pivot table (rows x columns with counts) from a flat list of records.
 *
 * Field metadata comes from `form` entries (`{ id, name, type, typeSpec }`); `enum`/`multiEnum`
 * fields resolve display names via `enums[typeSpec]`, and `multi*` field values are split on commas
 * so one record may count in several cells.
 *
 * @param rowId - field id used for rows (required; without it a placeholder title is returned)
 * @param colId - field id used for columns (optional; empty produces a single-column pivot)
 * @returns `{ title, rows, columns, totalCount }`; each row carries `cells`, `columns` and `items`
 * @example
 * pivotData(records, "type", "tag", form, enums).rows[0].columns // per-column cell counts
 */
export const pivotData = (
  data: StringHash[],
  rowId: string,
  colId: string,
  form: StringHash[] = [],
  enums: Record<string, unknown[]> = {}
) => {
  if (!rowId)
    return {
      title: "Select row and column...",
    };
  const rowhash = new Map();
  const colhash = new Map();
  let totalCount = 0;
  let cellCount = 0;
  const rField = form.find((e) => e.id === rowId) ?? {};
  const cField = colId ? form.find((e) => e.id === colId) : null;
  const rEnum =
    rField.type === "enum" || (rField.type === "multiEnum" && rField.typeSpec)
      ? arrayToObject(enums[rField.typeSpec], "id", "name")
      : null;
  const cEnum =
    (cField?.type === "enum" || cField?.type === "multiEnum") && cField?.typeSpec
      ? arrayToObject(enums[cField.typeSpec], "id", "name")
      : null;

  const operator = (e: StringHash, rId: string, cId: string) => {
    cellCount++;

    let row = rowhash.get(rId);
    if (!row) {
      row = {
        id: rId,
        name: rEnum?.[rId] ?? rId,
        value: 1,
        cells: {},
        items: [e],
      };
      rowhash.set(rId, row);
    } else {
      row.items.push(e);
      row.value++;
    }

    let cell: any = row.cells[cId];
    if (!cell) {
      cell = {
        id: cId,
        name: `${rField.name ?? rowId}: ${rEnum?.[rId] || rId || "Ø"}${
          cField ? ` / ${cField.name ?? colId}: ${cEnum?.[cId] || cId || "Ø"}` : ""
        }`,
        value: 1,
        items: [e],
      };
      row.cells[cId] = cell;
    } else {
      cell.value++;
      cell.items.push(e);
    }

    if (colId) {
      let col = colhash.get(cId);
      if (!col) {
        col = {
          id: cId,
          name: cEnum?.[cId] ?? cId,
          value: 1,
        };
        colhash.set(cId, col);
      } else {
        col.value++;
      }
    }
  };

  const cApplicator = !cField?.type?.startsWith("multi")
    ? (e: StringHash, rId: string) => operator(e, rId, String(e[colId] || ""))
    : (e: StringHash, rId: string) =>
        String(e[colId] || "")
          .split(",")
          .forEach((cId) => operator(e, rId, cId.trim()));

  const rApplicator = !rField.type?.startsWith("multi")
    ? (e: StringHash) => cApplicator(e, String(e[rowId] || ""))
    : (e: StringHash) =>
        String(e[rowId] || "")
          .split(",")
          .forEach((rId) => cApplicator(e, rId.trim()));

  data?.forEach((e: StringHash) => {
    totalCount++;
    rApplicator(e);
  });

  const columnsKeys = arraySortBy([...colhash.keys()], (e) => e);

  const rows = arraySortBy([...rowhash.values()]).map((e: any) => ({
    ...e,
    columns: columnsKeys.map((cId) => e.cells?.[String(cId)] ?? { id: cId, value: 0 }),
  }));

  return {
    title: `${rField.name ?? rowId}${cField ? ` / ${cField?.name ?? colId}` : ""}`,
    rows,
    columns: columnsKeys.map((cId) => colhash.get(String(cId)) ?? { id: cId, value: "-" }),
    totalCount: cellCount === totalCount ? cellCount : `${cellCount} / ${totalCount}`,
  };
};
