/**
 * Component implementation for a leaf element that has no logic of its own — a plain `div`, an unknown
 * tag, or any type the platform renders directly.
 *
 * It is the one implementation that opts out of the default state handling: by defining
 * `__stateChanged` it diverts incoming state into {@link attrs} instead of letting it be written as
 * fields, keeping the element a passive attribute bag that a renderer can read.
 *
 * The headless base only records attributes; a DOM platform substitutes a subclass that paints them.
 */
export class NativeElement {
  /** Child elements, filled by the renderer. */
  nodes: any[] = [];
  /** Applied state, collected as attributes rather than instance fields. */
  attrs = {};
  /** Marks this implementation as platform-native for the renderer. */
  native = true;
  [key: string]: unknown;

  constructor(
    readonly tag,
    _platform
  ) {}

  /** State sink: redirects every change into {@link attrs} instead of assigning it onto the instance. */
  __stateChanged(changes: Map<string, unknown>) {
    Object.assign(this.attrs, Object.fromEntries([...changes.entries()]));
  }

  /** Element name, used in renderer output and error messages. */
  getName() {
    return this.tag;
  }

  /** Reads an attribute, returning `fallback` when absent or nullish. */
  getAttribute(name, fallback: any = null) {
    return this.attrs[name] ?? fallback;
  }

  /**
   * Reads an attribute that must be present.
   *
   * @throws When the value is missing or falsy — note that `0` and `""` are rejected too.
   */
  getRequiredAttribute(name) {
    const value = this.getAttribute(name);
    if (!value) {
      throw new Error(`Required attribute '${name}' missing for ${this.getName()}`);
    }
    return value;
  }

  /**
   * Reads an attribute as a boolean, accepting `true`, `1`, `yes` and `on` (any case) as true.
   *
   * Anything else — including an absent attribute once `defaultValue` is stringified — reads as false.
   */
  getBooleanAttribute(name, defaultValue = false) {
    const value = this.getAttribute(name, defaultValue);
    if (typeof value === "boolean") return value;
    return ["true", "1", "yes", "on"].includes(String(value).toLowerCase());
  }

  /**
   * Reads an attribute as a number, falling back on an unparseable value.
   *
   * The fallback also swallows a legitimate `0`, since it is applied on any falsy parse result.
   */
  getNumericAttribute(name, defaultValue = 0) {
    const value = this.getAttribute(name, defaultValue);
    return parseFloat(value) || defaultValue;
  }

  /** Reads an attribute constrained to a set of values, falling back when it is not one of them. */
  getEnumAttribute<T>(name, allowedValues: T[], defaultValue): T {
    const value = this.getAttribute(name, defaultValue);
    return allowedValues.includes(value) ? value : defaultValue;
  }

  /** Text body of the element, stored under the reserved `#text` attribute by the compiler. */
  getTextContent() {
    return this.attrs["#text"];
  }

  /** Child elements. */
  getChildren() {
    return this.nodes;
  }
}
