import type { Hash } from "ultimus";
import { defineObjectRef } from "ultimus";
import type { DomNode, IElement } from "../types";

import { isEltEnabled } from "../utils/isEltEnabled";
import { setEventListener } from "../utils/setEventListener";

function createValuedEvent(value: unknown, dataset: object | undefined, domEvent: Event) {
  const event = { value, ...dataset };
  defineObjectRef(event, "target", domEvent.target);
  defineObjectRef(event, "nativeEvent", domEvent);
  return event;
}

// DOM custom attribute setters
export const DomElementAttributes: Hash<($: IElement, e: DomNode, v: unknown) => void> = {
  // inner text
  "#text": (_, e, v) => {
    e.textContent = v as string;
  },
  // dataset
  data: (_, e, u) => {
    e.$dataset = typeof u === "string" ? u : { ...(u as object) };
    for (const k of Object.keys(e.dataset)) delete e.dataset[k];
    if (u && typeof u === "object") {
      for (const [k, v] of Object.entries(u as object)) {
        if (v != null) e.dataset[k] = String(v);
      }
    }
  },
  // inputs specific
  disabled: (_, e, v) => (e.disabled = v ? true : null),
  selected: (_, e, v) => (e.selected = v ? true : null),
  value: (_, e, v) => (e.value = v == null ? "" : v),
  checked: (_, e, v) => (e.checked = !!v),
  autofocus: (_, e, v) => {
    if (v) setTimeout(() => e.focus(), 10);
  },

  click: ($, e) =>
    setEventListener(
      $,
      "click",
      (domEvent: Event) => {
        setTimeout(
          () =>
            (async () => {
              if (isEltEnabled(e)) {
                const event = { ...e.$dataset };
                defineObjectRef(event, "target", domEvent.target);
                defineObjectRef(event, "nativeEvent", domEvent);
                await $.click?.(event, domEvent);
                $.afterClick?.(event, domEvent);
              }
            })(),
          10
        );
        if ($.click) {
          domEvent.preventDefault();
        }
        return false;
      },
      { capture: !!$.clickCaptureMode }
    ),
  toggleClass: ($, e) =>
    setEventListener(
      $,
      "toggleClass:click",
      () => {
        setTimeout(() => {
          if (isEltEnabled(e)) {
            $.toggleClass?.split(";").forEach((chunk = "") => {
              const [className, prep, toggleClassTarget = prep] = chunk.trim().split(" ");
              const target = toggleClassTarget ? document.getElementById(toggleClassTarget) : e;

              if (!target) {
                console.warn(`toggleClass: target element not found: ${toggleClassTarget}`);
              }

              target?.classList.toggle(className);
            });
          }
        }, 10);
        return false;
      },
      { capture: true }
    ),
  blur: ($, e) =>
    setEventListener($, "blur", (domEvent: Event) => {
      setTimeout(() => {
        $.blur?.(e.$dataset ?? {}, domEvent);
      }, 10);
      return false;
    }),
  error: ($, e) =>
    setEventListener($, "error", (domEvent: Event) => {
      setTimeout(() => {
        $.error?.(e.$dataset ?? {}, domEvent);
      }, 10);
      return false;
    }),
  focus: ($, e) =>
    setEventListener($, "focus", (domEvent: Event) => {
      $.focus?.(e.$dataset ?? {}, domEvent);
      return false;
    }),
  dblclick: ($, e) =>
    setEventListener($, "dblclick", (domEvent: Event) => {
      if (isEltEnabled(e)) {
        $.dblclick?.(e.$dataset ?? {}, domEvent);
      }
      return false;
    }),

  keypress: ($, e) =>
    setEventListener($, "keypress:keyup", (ev: KeyboardEvent) => {
      if (ev.key !== "Enter" && ev.key !== "Escape") {
        $.keypress?.(createValuedEvent(e.value, e.$dataset, ev), ev);
        setTimeout(() => e.focus(), 0);
      }
      return false;
    }),
  enter: ($, e) =>
    setEventListener($, "enter:keyup", async (ev: KeyboardEvent) => {
      if (ev.key === "Enter") {
        const event = createValuedEvent(e.value, e.$dataset, ev);
        await $.enter?.(event, ev);
      }
      if (ev.key === "Enter" || ev.key === "Escape") {
        e.blur();
      }
      return false;
    }),
  input: ($, e) =>
    setEventListener($, "input", (ev: Event) => {
      $.input?.(createValuedEvent(e.value, e.$dataset, ev), ev);
      return false;
    }),
  change: ($, e) =>
    setEventListener($, "change", (ev: Event) => {
      const input = e as unknown as HTMLInputElement;
      const value = input.type === "file" ? input.files : e.value;
      $.change?.(createValuedEvent(value, e.$dataset, ev), ev);
      return false;
    }),
  toggle: ($, e) =>
    setEventListener($, "toggle:change", (ev: Event) => {
      $.toggle?.({ value: e.checked, ...e.$dataset }, ev);
      return false;
    }),
  scroll: ($, e) =>
    setEventListener($, "scroll", (ev) => {
      $.scroll?.(Object.assign(ev, { value: e.scrollTop }));
    }),
  scrolledDown: ($, element) =>
    setEventListener($, "scrolledDown:scroll", (ev) => {
      const gap = $.scrolledDownGap || 10;
      const offset = element.clientHeight + element.scrollTop;
      const isDown = Math.abs(element.scrollHeight - offset) < gap;
      if (isDown && offset > ($._maxScrolledDownOffset || 0)) {
        $._maxScrolledDownOffset = offset;
        $.scrolledDown?.({ offset }, ev);
      }
    }),
};
