import { HASH_SYMBOL } from "./hashCodeOf";

/**
 * Universal deep equality for any value type, tuned for reactive change detection.
 *
 *  - Primitives are compared by value with `===`; `NaN` is never equal (matches `===`).
 *  - Objects carrying a memoized `HASH_SYMBOL` — frozen objects (content hash),
 *    Arrmatron instances and Promises (identity hash) — short-circuit to an O(1)
 *    hash read, no traversal.
 *  - Arrays, Maps, Sets and plain objects are compared **structurally and
 *    recursively**, short-circuiting on the first differing entry at any depth.
 *    Plain objects skip `$`-prefixed internal keys.
 *
 * Cyclic references are bounded by `deepLevel`: recursion stops at the depth cap
 * (treating values as equal beyond it) instead of being tracked in a visited
 * set, so there is no per-call allocation. This mirrors how `hashCodeOf` caps
 * depth. `deepLevel` is internal and should not be passed by callers.
 */
export function isEquals(a: any, b: any, deepLevel = 0): boolean {
  // NaN is never equal (matches === semantics)
  if (Number.isNaN(a)) return false;

  // primitives (and null/undefined): value comparison
  if (a === null || typeof a !== "object") return a === b;
  if (b === null || typeof b !== "object") return false;

  // memoized-hash fast path: frozen (content) / instance & promise (identity)
  if (HASH_SYMBOL in a && HASH_SYMBOL in b) return a[HASH_SYMBOL] === b[HASH_SYMBOL];

  // depth cap also bounds cyclic refs: beyond it, stop distinguishing
  if (deepLevel > 10) return true;
  const next = deepLevel + 1;

  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!isEquals(a[i], b[i], next)) return false;
    }
    return true;
  }
  if (a instanceof Map) {
    if (!(b instanceof Map) || a.size !== b.size) return false;
    for (const [key, v] of a) {
      const bv = b.get(key); // one lookup; only fall back to has() to tell a real undefined from a miss
      if ((bv === undefined && !b.has(key)) || !isEquals(v, bv, next)) return false;
    }
    return true;
  }
  if (a instanceof Set) {
    if (!(b instanceof Set) || a.size !== b.size) return false;
    for (const v of a) {
      if (!b.has(v)) return false;
    }
    return true;
  }
  // a is a plain object / Date — a container on the other side can't match
  if (Array.isArray(b) || b instanceof Map || b instanceof Set) return false;

  if (a instanceof Date || b instanceof Date) {
    return a instanceof Date && b instanceof Date && a.getTime() === b.getTime();
  }

  // plain objects: structural, short-circuit, ignore `$`-prefixed keys
  let count = 0;
  for (const key in a) {
    if (key[0] === "$" || !Object.hasOwn(a, key)) continue;
    count++;
    if (!Object.hasOwn(b, key) || !isEquals(a[key], b[key], next)) return false;
  }
  for (const key in b) {
    if (key[0] !== "$" && Object.hasOwn(b, key) && --count < 0) return false;
  }
  return count === 0;
}
