import { capitalize, type Delta, type Hash, objectFreeze, parseJson } from "ultimus";
import { WebClientService } from "@/core";
import { forcePersistMode, IDB } from "./idb";
import type { DbQueryParams } from "./idb/types";
import { initialDataFactory } from "./support/initialDataFactory";

/**
 * Local Indexed Database Service.
 */
export class IndexedDbService extends WebClientService {
  name = "items";
  version = 1;
  stores = {
    items: {
      keyPath: "id",
      indicies: [{ id: "kind" }, { id: "parent" }, { id: "links", multiEntry: true }],
    },
  };

  forcePersist = false;
  triggers: any = {};
  initialData?: any;
  initialUrl?: string;
  idb = new IDB();

  async __init() {
    if (this.forcePersist) {
      await forcePersistMode();
    }

    try {
      const stores = Object.fromEntries(
        Object.entries(this.stores ?? {}).map(([key, def]) => [key, typeof def === "string" ? parseJson(def) : def])
      );

      const { version, upgradedTo } = await this.idb.open({
        name: this.name,
        version: this.version,
        stores,
        initialDataFactory: (options, bundleApplicator) => {
          const { initialData, initialUrl } = this;
          return initialDataFactory({ ...options, initialData, initialUrl, stores }, bundleApplicator);
        },
      });

      this.log(`db is opened: ${this.name}(${version})`);

      if (upgradedTo) {
        const message = `Database "${this.name}" has been upgraded to version ${upgradedTo}).`;
        this.log(message);
        if (upgradedTo > 1) {
          this.toast({ id: `db_up${this.name}`, message });
        }
      }
    } catch (error: any) {
      const err = error.currentTarget?.error ?? error;
      this.logError(err);
      this.up({ error: err });
    }

    const triggers = {};

    const itemGetter = new Proxy(
      {},
      {
        get: (_target: any, store: string) => {
          return new Proxy(
            {},
            {
              get: (_target: any, id: string) => {
                return this.getObject({ id, store });
              },
            }
          );
        },
      }
    );
    Object.defineProperty(this, `item`, {
      get() {
        return itemGetter;
      },
    });

    const pathGetter = new Proxy(
      {},
      {
        get: (_target: any, store: string) => {
          return new Proxy(
            {},
            {
              get: (_target: any, id: string) => {
                return this.loadPath({ id, store });
              },
            }
          );
        },
      }
    );

    const childrenGetter = new Proxy(
      {},
      {
        get: (_target: any, store: string) => {
          return new Proxy(
            {},
            {
              get: (_target: any, valueType: string) => {
                const [value, index = "parent"] = valueType.split(":");
                return this.query({ store, index, value });
              },
            }
          );
        },
      }
    );

    Object.defineProperty(this, `itemPath`, {
      get() {
        return pathGetter;
      },
    });

    Object.defineProperty(this, `children`, {
      get() {
        return childrenGetter;
      },
    });

    Object.keys(this.stores).forEach((store) => {
      triggers[store] = 0;
      Object.defineProperty(this, `trigger${capitalize(store.toLowerCase())}`, {
        get(): string {
          return this.triggers[store];
        },
      });

      this.__defineCalculatedProperty(`all${capitalize(store.toLowerCase())}`, () => this.query({ store }), [
        `trigger${capitalize(store.toLowerCase())}`,
      ]);
    });

    this.up({ triggers, isReady: true });
  }

  async query(options: DbQueryParams) {
    const data = await this.idb.query(options);
    return objectFreeze(
      data?.filter((entry) => !entry.deleted).map((entry) => objectFreeze({ ...entry, store: options.store }))
    );
  }

  get entireData() {
    return (async () => {
      const result: Hash = {};
      await Promise.all(
        Object.keys(this.stores).map(async (key) => {
          result[key] = await this.query({ store: key });
        })
      );
      return result;
    })();
  }

  async getObject({ id, store = "items" }) {
    const data = await this.idb.getObject(String(id), store);
    return !data || data?.deleted ? null : objectFreeze({ ...data, store });
  }

  async loadPath({ id, store = "items" }) {
    let entry = await this.getObject({ store, id });
    if (!entry) return [];
    const results: any[] = [entry];
    while (entry?.parent && !results.some((e) => e.id === entry.parent)) {
      const parent = await this.getObject({ store, id: entry.parent });
      if (!parent) break;
      results.unshift(parent);
      entry = parent;
    }
    return results;
  }

  async putObject(data: Delta) {
    const now = Date.now();

    const { id = `${now}`, store = "items", ...delta } = data;

    void (await this.idb.putObject({ ...delta, id: String(id), ts: now }, store));

    this.upTriggers(store);
  }

  async upsertObject(data: Delta) {
    const now = Date.now();

    const { id = `${now}`, store = "items", ts = now, ...delta } = data;

    void (await this.idb.upsertObject({ ...delta, id: String(id), ts }, store));

    this.upTriggers(store);
  }

  async batchPut(batch: Hash<any[]>) {
    const result = await this.idb.batchPut(batch);

    this.upTriggers(...Object.keys(batch).filter((s) => batch[s]?.length));

    return result;
  }

  async batchUpsert(batch: Hash<any[]>) {
    if (!batch) return null;

    const result = await this.idb.batchUpsert(batch);

    this.upTriggers(...Object.keys(batch).filter((s) => batch[s]?.length));

    return result;
  }

  async setField({ id, field, value: valueExpr, store, valueAdapter }: Delta) {
    const isCorrect = id && field && store && valueExpr != null;
    if (!isCorrect) {
      return;
    }

    const item = await this.getObject({ id, store });
    if (!item) {
      return;
    }

    const value = valueAdapter ? valueAdapter(valueExpr, item) : valueExpr;

    if (item[field] === value) {
      return;
    }

    const delta = { id: String(id), [field]: value, store };

    await this.upsertObject(delta);
  }

  upTriggers(...keys: string[]) {
    const triggers = { ...this.triggers };

    keys.forEach((store) => {
      this.log(`trigger ${store}`);
      triggers[store] = (triggers[store] ?? 0) + 1;
    });

    this.up({ triggers });
  }

  async deleteAllObjects(store) {
    await this.idb.deleteAllObjects(store);

    this.upTriggers(store);
  }

  deleteDatabase() {
    return this.idb
      .deleteDatabase()
      .then(() => {
        window.location.reload();
      })
      .catch(() => {
        window.location.reload();
      });
  }
}
