type ComparatorDirection = 1 | -1;
type ComparatorResult = 0 | 1 | -1;
type Comparator<T> = (a: T, b: T) => ComparatorResult;

const createComparator = <T = any>(
  fn: string | ((e: T) => number | string),
  dir: ComparatorDirection = 1
): Comparator<T> => {
  let order: ComparatorDirection = dir === 1 ? 1 : -1;
  let negOrder: ComparatorDirection = dir === 1 ? -1 : 1;
  if (typeof fn === "string") {
    let key = fn;
    if (key[0] === "-") {
      order = -1;
      negOrder = 1;
      key = fn.slice(1);
    }
    return (a: T, b: T): ComparatorResult => {
      const aa = a?.[key];
      const bb = b?.[key];
      return aa < bb ? negOrder : aa > bb ? order : 0;
    };
  }

  return (a: T, b: T): ComparatorResult => {
    const aa = fn(a);
    const bb = fn(b);
    return aa < bb ? negOrder : aa > bb ? order : 0;
  };
};

/**
 * Returns a new array sorted by a property name (default "name", "-" prefix reverses) or by a key function.
 *
 * @param order - 1 for ascending (default), -1 for descending
 */
export const arraySortBy = <T = any>(
  arr?: T[] | null,
  property: string | ((e: T) => string | number) = "name",
  order: ComparatorDirection = 1
): T[] => {
  if (!property) return arr ?? [];
  return !arr?.toSorted ? [] : arr.toSorted(createComparator<T>(property, order));
};
