export type OnComplete<T> = (result: T | Promise<T>) => void;
export type OnFail = (reason: any) => void;

export type AsyncFunctor<T, R> = (ctx: NonNullable<T>, oncomplete: OnComplete<R>, onerror: OnFail) => void;

export type AsyncRecord<T, R> = {
  fn: AsyncFunctor<T, R>;
  oncomplete: OnComplete<R>;
  onerror: OnFail;
};

export class DeferedContextAsyncInvocations<T> {
  ctx?: NonNullable<T>;

  invocations: Array<AsyncRecord<T, any>> = [];

  invoke<R>(fn: AsyncFunctor<T, R>, prior = false) {
    return new Promise<R>((oncomplete, onerror) => {
      if (!this.ctx) {
        this.invocations[prior ? "unshift" : "push"]({ fn, oncomplete, onerror });
      } else {
        try {
          fn(this.ctx, oncomplete, onerror);
        } catch (error) {
          onerror(error);
        }
      }
    });
  }

  set context(ctx: T) {
    if (ctx) {
      this.ctx = ctx;

      for (const { fn, oncomplete, onerror } of this.invocations.values()) {
        try {
          fn(this.ctx, oncomplete, onerror);
        } catch (error) {
          onerror(error);
        }
      }

      this.invocations = [];
    }
  }
}
