import type { Hash } from "ultimus";
import { arraySortBy, arrayToObject } from "ultimus";

import { OPT_EMPTY, OPT_NAMES, OPT_NON_EMPTY } from "./consts";

export class FilterField {
  names: Hash<any>;
  selections: Hash<boolean> = {};
  isSelected = false;
  type: any;
  id: any;
  pattern?: string;
  patternRegExp?: RegExp;
  setPattern: (value: string) => void;
  toggleOption: (id: any) => void;
  settleOption: (id: any) => void;
  setIsSelected: (v: boolean) => void;
  $histo?: any[];
  isMultiType: any;
  isDateType: any;
  isPrefixType: any;
  typeSpec: any;

  constructor(
    readonly ctrl,
    initials: any
  ) {
    Object.assign(this, initials);
    const { type = "text", typeSpec } = initials;

    this.isMultiType = type.startsWith("multi");
    this.isDateType = type.startsWith("date");
    this.isPrefixType = type.startsWith("prefix");
    this.typeSpec = typeSpec;

    this.names =
      type === "enum" || (type === "multiEnum" && typeSpec)
        ? arrayToObject((ctrl.platform.getResource(`enums.${typeSpec}`) as Hash[]) || [], "id", "name")
        : {};

    this.toggleOption = (id) => {
      if (id in this.selections) {
        this.selections = Object.fromEntries(
          Object.keys(this.selections)
            .filter((key) => key !== id)
            .map((val) => [val, true])
        );
      } else {
        if (id === OPT_NON_EMPTY) {
          this.selections = { [OPT_NON_EMPTY]: true };
        } else {
          this.selections[id] = true;
          this.selections = Object.fromEntries(
            Object.keys(this.selections)
              .filter((key) => key !== OPT_NON_EMPTY)
              .map((val) => [val, true])
          );
        }
      }
    };

    this.settleOption = (id) => {
      if (!id) {
        this.selections = {};
      } else {
        if (typeof id === "object") {
          if (Array.isArray(id)) {
            this.selections = Object.fromEntries(id.map((val) => [val, true]));
          } else {
            this.selections = id;
          }
        } else {
          this.selections = { [String(id)]: true };
        }
      }
    };

    this.setIsSelected = (v: boolean) => {
      if (!v) {
        this.selections = {};
      }
      this.isSelected = v;
    };

    this.setPattern = (v: string) => {
      this.pattern = v;
      this.patternRegExp = v?.length > 1 ? new RegExp(v, "im") : undefined;
      if (v) {
        this.selections = {};
      }
    };
  }

  matched(item: Hash) {
    const { id, isMultiType, isDateType, isPrefixType, selections } = this;
    const value = String(item[id] ?? "");

    if (!value && selections[OPT_EMPTY]) return true;
    if (value && selections[OPT_NON_EMPTY]) return true;
    if (this.patternRegExp) return value ? !!this.patternRegExp.test(value) : false;

    const vals = Object.keys(selections);

    if (vals.length === 0) return true;

    for (const val of vals) {
      if (isMultiType) {
        if (
          value?.includes(val) &&
          value
            .split(",")
            .map((key) => key.trim())
            .includes(val)
        ) {
          return true;
        }
      } else if (isDateType) {
        if (value?.startsWith(val)) {
          return true;
        }
      } else if (isPrefixType) {
        if (value?.startsWith(val)) {
          return true;
        }
      } else {
        if (value === val) {
          return true;
        }
      }
    }
    return false;
  }

  get isEmpty() {
    return Object.keys(this.selections).length === 0;
  }

  get histogram() {
    const { isMultiType, isDateType, isPrefixType, typeSpec, names, selections } = this as any;
    const { data } = this.ctrl;
    const hash: Hash<number> = {};
    const incKey = (key, inc = 1) => {
      hash[key] = inc + Number(hash[key] ?? 0);
    };
    const fields = this.ctrl.fields.filter((field) => field !== this);
    const items = data.filter((item: Hash) => !fields.some((field) => !field.matched(item)));

    items.forEach((item: Hash) => {
      const val = String(item[this.id] ?? "");
      incKey(!val ? OPT_EMPTY : OPT_NON_EMPTY);
      if (!val) return;
      if (typeSpec == "pattern") return;
      if (isMultiType) {
        val.split(",").forEach((key) => incKey(key.trim()));
      } else if (isDateType) {
        incKey(val.slice(0, 4));
        incKey(val.slice(0, 7));
      } else if (isPrefixType) {
        incKey(val.slice(0, typeSpec ?? 3));
      } else {
        incKey(val);
      }
    });

    const histo: any[] = Object.entries(hash)
      .filter(([key, count]) => key !== OPT_EMPTY && key !== OPT_NON_EMPTY && count > 0)
      .map(([id, count]) => ({ id, name: names?.[id] ?? id, count, isSelected: !!selections[id] }));

    this.$histo = [
      { ...OPT_NAMES[OPT_EMPTY], count: hash[OPT_EMPTY] ?? 0, isSelected: !!selections[OPT_EMPTY] },
      {
        ...OPT_NAMES[OPT_NON_EMPTY],
        count: hash[OPT_NON_EMPTY] ?? 0,
        isSelected: !!selections[OPT_NON_EMPTY],
      },
      ...arraySortBy(histo, "name"),
    ];

    return this.$histo;
  }
}
