import { requestJson } from "./http";
import type { RestEndpoints } from "./types";

/** Firebase Storage object metadata, as the v0 API returns it. */
export interface StorageObject {
  /** Full path inside the bucket — the SDK calls this `fullPath`. */
  name: string;
  bucket: string;
  contentType?: string;
  size?: string;
  generation?: string;
  timeCreated?: string;
  updated?: string;
  /** Comma-separated; the first one is what a download URL carries. */
  downloadTokens?: string;
}

const bucketUrl = ({ storage, bucket }: RestEndpoints) => `${storage}/b/${encodeURIComponent(bucket)}/o`;

const authHeader = (idToken: string) => ({ Authorization: `Bearer ${idToken}` });

/**
 * Uploads a file and resolves with the stored object's metadata.
 *
 * Sent as `multipart/related` — a JSON metadata part followed by the bytes — which is what the
 * Firebase SDK does. A plain single-part POST works too, but the bucket then stores the object as
 * `application/octet-stream` regardless of the request's Content-Type, and every download of it
 * arrives as a file to save rather than something the browser can render.
 */
export function uploadObject(
  endpoints: RestEndpoints,
  { path, file, idToken }: { path: string; file: Blob; idToken: string }
): Promise<StorageObject> {
  const contentType = file.type || "application/octet-stream";
  const boundary = `firebasis-${Math.random().toString(36).slice(2)}`;
  const metadata = JSON.stringify({ name: path, contentType });

  const body = new Blob([
    `--${boundary}\r\nContent-Type: application/json; charset=utf-8\r\n\r\n${metadata}`,
    `\r\n--${boundary}\r\nContent-Type: ${contentType}\r\n\r\n`,
    file,
    `\r\n--${boundary}--`,
  ]);

  return requestJson<StorageObject>(`${bucketUrl(endpoints)}?name=${encodeURIComponent(path)}&uploadType=multipart`, {
    headers: {
      ...authHeader(idToken),
      "Content-Type": `multipart/related; boundary=${boundary}`,
      "X-Goog-Upload-Protocol": "multipart",
    },
    body,
  });
}

/** Reads an object's metadata — the only way to recover a download token for an existing file. */
export function objectMetadata(
  endpoints: RestEndpoints,
  { path, idToken }: { path: string; idToken: string }
): Promise<StorageObject> {
  return requestJson<StorageObject>(`${bucketUrl(endpoints)}/${encodeURIComponent(path)}`, {
    headers: authHeader(idToken),
  });
}

/**
 * Builds the public download URL for an object.
 *
 * The token is what makes the URL readable without an Authorization header, which is why it has to
 * come from the object's metadata rather than being derived.
 */
export function downloadUrlOf(endpoints: RestEndpoints, path: string, downloadTokens?: string): string {
  const [token] = (downloadTokens ?? "").split(",");
  const url = `${bucketUrl(endpoints)}/${encodeURIComponent(path)}?alt=media`;
  return token ? `${url}&token=${encodeURIComponent(token)}` : url;
}
