import { Component } from "arrmatura";
import { assert, capitalize } from "ultimus";

const REQUESTS_MAP = new Map();

/**
 * React Native async post messaging service within WebView.
 */
export class RNWebViewPostMessagingService extends Component {
  rnwvInstance = window?.["ReactNativeWebView" as keyof typeof window];

  isActivated = !!this.rnwvInstance;

  __init() {
    if (!this.isActivated) return;

    window.addEventListener("message", async (event: MessageEvent) => {
      const { action, payload, requestId, error } = event.data;

      if (action === "@RESPONSE") {
        try {
          const promise = REQUESTS_MAP.get(requestId);
          assert(promise, `Received response to ${requestId}, but no promise found`);
          REQUESTS_MAP.delete(requestId);

          console.info(`Received response to ${requestId}`);
          if (error) {
            promise.reject(error);
          } else {
            promise.resolve(payload);
          }
        } catch (error) {
          const { message } = error as Error;
          console.error(message);
        }
      } else {
        try {
          const handler = this[`do${capitalize(action)}`];
          assert(handler, `Received ${action}, but no handler found`);
          console.info(`Received ${requestId ? "request for" : "message"} ${action}`);
          const result = await handler(payload);
          if (requestId) {
            this.postMessage({ action: "@RESPONSE", payload: result, requestId });
          }
        } catch (error) {
          const { message } = error as Error;
          console.error(message);
          if (requestId) {
            this.postMessage({ action: "@RESPONSE", error: { message }, requestId });
          }
        }
      }
    });

    const timer = setInterval(() => {
      const now = Date.now();
      for (const [requestId, { reject, expires }] of REQUESTS_MAP.entries()) {
        if (expires && now > expires) {
          reject(new Error("Timeout"));
          REQUESTS_MAP.delete(requestId);
        }
      }
    }, 2000);

    this.defer(() => {
      clearInterval(timer);
    });

    this.postMessage({ action: "@READY" });
  }

  postMessage(message) {
    if (!this.isActivated) return Promise.resolve(null);

    this.rnwvInstance?.postMessage(JSON.stringify(message));
  }

  postAsyncMessage(message) {
    if (!this.isActivated) return Promise.resolve(null);

    return new Promise((resolve, reject) => {
      const action = message.action ?? "action";
      const requestId = message.requestId ?? action + Date.now();
      const timeout = message.timeout ?? 0;

      REQUESTS_MAP.set(requestId, {
        resolve,
        reject,
        expires: timeout ? Date.now() + timeout : 0,
      });

      this.rnwvInstance?.postMessage(JSON.stringify(message));
    });
  }
}
