import { escapeXml } from "./utils";

const stringifyAttr = ([k, v]: [string, unknown], i: number, sep: string): string =>
  `${i ? sep : " "}${k}="${escapeXml(typeof v === "object" ? JSON.stringify(v) : String(v))}"`;

/**
 * Serializes an attributes object into ` key="value"` pairs with XML-escaped values.
 * Keys starting with `#` and null/empty values are skipped; object values are JSON-encoded.
 *
 * @param sep separator between pairs (default single space)
 */
export function stringifyAttributes(attrs: object, sep = " ") {
  return Object.entries(attrs)
    .filter(([k, v]) => k[0] !== "#" && v != null && v !== "")
    .map((pair, index) => stringifyAttr(pair, index, sep))
    .join("");
}
