export function stopSpeaking() {
  const synth = window.speechSynthesis;
  console.log("stopSpeaking");
  synth?.cancel();
}

export function speak(text, options: any = {}) {
  return new Promise((resolve, _reject) => {
    if (!text) {
      resolve(false);
      return;
    }
    const synth = window.speechSynthesis;
    if (!synth) {
      console.error("speech Synthesis not provided");
      resolve(false);
      return;
    }

    if (synth.speaking) {
      console.error("speechSynthesis.speaking");
      synth.cancel();
      setTimeout(() => {
        speak(text, options);
      }, 500);
      return;
    }

    text = text.replaceAll(/[”]/g, " ");

    const utter = new SpeechSynthesisUtterance(text);

    Object.assign(utter, {
      lang: "en-US",
      pitch: 1,
      ...options,
      rate: Number(options.rate ?? 1),
      onend(_event) {
        console.log("SpeechSynthesisUtterance.onend");
        resolve(true);
      },
      onerror(event) {
        console.error("SpeechSynthesisUtterance.onerror", event);
        resolve(false);
      },
    });
    synth.speak(utter);
  });
}
