import type { DomNode } from "../types";

export function attachToParent(
  e: DomNode,
  p: ShadowRoot | HTMLElement,
  before?: ChildNode | HTMLElement | null
): DomNode {
  if (!e) return e;

  if (!before) {
    if (p !== e.parentElement) {
      p.appendChild(e);
    }
  } else if (e !== before) {
    p.insertBefore(e, before);
  }
  return e;
}
