import { Component } from "arrmatura";

export class DarkModeService extends Component {
  defaultMode = null;

  __init() {
    const isMediaDarkMode = window.matchMedia("(prefers-color-scheme: dark)").matches;
    const theme =
      localStorage.getItem("theme") ?? this.theme ?? this.defaultMode ?? (isMediaDarkMode ? "dark" : "light");

    this.up({ theme });
  }

  get isDarkMode() {
    return this.theme === "dark";
  }

  get theme() {
    return document.documentElement.getAttribute("data-theme");
  }

  set theme(theme) {
    localStorage.setItem("theme", theme ?? "light");
    document.documentElement.setAttribute("data-theme", theme ?? "light");
  }

  toggle() {
    const theme = this.isDarkMode ? "light" : "dark";
    this.up({ theme });
  }
}
