import { loadJson } from "ultimus";
import { WebClientService } from "@/core";

export class RemoteApiClient extends WebClientService {
  name = "remote";
  url = "/api";

  onUnauthorized?: (error: Error) => void;

  tokenInHeaders = false;
  tokenInBody = true;

  get isAuthorized() {
    return !!this.token;
  }

  get token() {
    const token = this.storage.get(`token`);
    return token === "--" ? null : token;
  }

  set token(s) {
    this.storage.set(`token`, s);
  }
  clearToken() {
    this.token = "--";
  }

  invokeApi(body: any = {}): Promise<any> {
    // workaround for `script.google.com`
    const contentType = this.url.startsWith("https://script.google.com/macros/s/") ? "text/plain" : "application/json";

    const headers = {
      "Content-Type": contentType,
    };

    if (this.token) {
      if (this.tokenInBody) {
        body.token = this.token;
      }
      if (this.tokenInHeaders) {
        headers.Authorization = `Bearer ${this.token}`;
      }
      if (body?.action === "signOut") {
        this.up({ token: null });
      }
    }

    return loadJson<any>({
      url: this.url,
      body,
      headers,
    })
      .then((result) => {
        if (result.token) {
          this.token = result.token;
        }
        return result;
      })
      .catch((error: any) => {
        if (error?.code === 401 && this.onUnauthorized) {
          this.onUnauthorized?.(error);
        } else {
          throw error;
        }
      });
  }
}
