import { assert } from "ultimus";

/** Google Identity Services — the only third-party script the client loads. */
const GIS_SRC = "https://accounts.google.com/gsi/client";

/** Identity only: enough for Identity Toolkit to resolve the account, nothing more. */
const GOOGLE_SCOPE = "openid email profile";

declare global {
  interface Window {
    google?: any;
  }
}

let loader: Promise<any> | null = null;

/**
 * Loads the GIS client once and resolves with the `google` global.
 *
 * Worth calling early (and ignoring the result): `requestAccessToken` must run inside the click
 * that triggered sign-in, and awaiting a script load first would break that user gesture.
 */
export function loadGoogleIdentity(): Promise<any> {
  if (window.google?.accounts?.oauth2) return Promise.resolve(window.google);

  loader ??= new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = GIS_SRC;
    script.async = true;
    script.defer = true;
    script.onload = () =>
      resolve(assert(window.google?.accounts?.oauth2 && window.google, "GIS loaded without oauth2"));
    script.onerror = () => {
      // Cleared so a later attempt can retry rather than resolving against a dead promise.
      loader = null;
      reject(new Error(`Failed to load ${GIS_SRC}`));
    };
    document.head.append(script);
  });

  return loader;
}

/**
 * Opens the Google account chooser and resolves with an OAuth access token.
 *
 * The popup is owned by GIS. The token is short-lived and used once, to be exchanged for a
 * Firebase session by {@link signInWithGoogleToken}.
 */
export async function requestGoogleAccessToken(clientId: string): Promise<string> {
  const google = await loadGoogleIdentity();

  return new Promise<string>((resolve, reject) => {
    const client = google.accounts.oauth2.initTokenClient({
      client_id: clientId,
      scope: GOOGLE_SCOPE,
      callback: (response: any) =>
        response?.access_token
          ? resolve(response.access_token)
          : reject(new Error(response?.error_description || response?.error || "Google sign-in returned no token")),
      error_callback: (error: any) => reject(new Error(error?.message || "Google sign-in was dismissed")),
    });

    client.requestAccessToken();
  });
}
