import type { Fn } from "../types";

/**
 * Compiles a key spec into a getter function.
 *
 * - function: returned as-is.
 * - `"a.b.c"`: dotted path lookup (undefined-safe).
 * - `"name,a.b"`: comma-separated paths resolved and joined with a space (missing values become `""`).
 * - `["a", "b"]`: path segments lookup.
 * - anything else (e.g. `null` passed loosely): falls back to a getter for `id`.
 */
export const gettusFn = <T extends object = object>(
  key: string | string[] | ((e: T) => unknown)
): ((e: T) => unknown) => {
  if (typeof key === "function") return key;

  if (typeof key === "string") {
    const skey = key;
    if (key.includes(",")) {
      const keys: string[][] = key.split(",").map((part) => part.split("."));
      return (o) =>
        keys
          .map<string>((path) => {
            const val = path.reduce<object | undefined>((rr, seg) => (rr ? (rr[seg] as object) : undefined), o);
            return String(val ?? "");
          })
          .join(" ");
    }

    if (!key.includes(".")) return (o) => o[skey];

    const keys = key.split(".");
    return (o) => keys.reduce<object | undefined>((r, seg) => (r ? (r[seg] as object) : undefined), o);
  }

  if (Array.isArray(key)) {
    const akey = key;
    return (o) => akey.reduce<object | undefined>((r, seg) => (r ? (r[seg] as object) : undefined), o);
  }

  key = "id";
  return (o) => o[key];
};

/**
 * Reads a value from an object by key spec: a getter function, a dotted path string, or path segments.
 *
 * Returns `undefined` when the object or key is missing, or when any path segment is absent.
 */
export const gettus = (o: object, key: Fn | string | string[] | ((e: object) => unknown)): unknown => {
  if (!o || !key || typeof o !== "object") return undefined;
  if (typeof key === "function") return key(o);
  if (typeof key === "string") {
    if (!key.includes(".")) return o[key];
    key = key.split(".");
  }
  return key.reduce<object | undefined>((r, seg) => (r ? (r[seg] as object) : undefined), o);
};
