import { launchWebApp, type WebAppOptions } from "./core";
import { modules } from "./modules";

export { Component } from "arrmatura";
export * from "./core";
export { SpeechListener, type SpeechListenerOptions } from "./modules/speech";

/**
 * Launches an app on the full platform bundle — the one-import entry point for an app.
 *
 * Use `launchWebApp` instead to launch on a bare platform and register components yourself.
 *
 * `components` carries only what the app itself adds — its CML index and services. The registry
 * flattens nested arrays, so passing them through unspread is fine.
 */
export function launchPlatformApp({
	components = [],
	resources = {},
	...options
}: WebAppOptions = {}) {
	const windowResources = (window as unknown as { R: object }).R;

	launchWebApp({
		components: [...modules, components],
		resources: { ...resources, ...windowResources },
		...options,
	});
}
