/**
 * Applies `fn` to a value that may or may not be a Promise.
 *
 * @returns `fn(val)` for a plain value, or a Promise of `fn(resolved)` when `val` is a Promise.
 */
export function asyncValueCall<T, R>(val: Promise<T> | T, fn: (a: T) => R): Promise<R> | R {
  if (val instanceof Promise) {
    return val.then(fn);
  }
  return fn(val);
}
