/**
 * Builds a new object by mapping each own enumerable entry through `keyFn` and `valueFn`.
 *
 * Defaults keep keys and values unchanged (shallow copy). Colliding mapped keys keep the last value.
 */
export function transformObject(
  obj: Record<string, unknown>,
  keyFn: (key: string, value: unknown, obj: Record<string, unknown>) => string = (k) => k,
  valueFn: (key: string, value: unknown, obj: Record<string, unknown>) => unknown = (_k, v) => v
): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const key in obj) {
    if (!Object.hasOwn(obj, key)) continue;
    result[keyFn(key, obj[key], obj)] = valueFn(key, obj[key], obj);
  }
  return result;
}
