import { Component } from "arrmatura";
import { capitalize } from "ultimus";

import type { IndexedDbService } from "./IndexedDbService";

export class IndexedDbObject extends Component {
  dbChange = 0;
  store = "";
  db?: IndexedDbService;

  constructor() {
    super();

    this.__defineCalculatedProperty(
      `data`,
      async (db: IndexedDbService, value, store) => {
        if (!db || !store || !value) return null;
        const result = (await db.getObject({ id: value, store })) ?? null;
        // this.log("IndexedDbObject", store, value, result, trigger, dbChange);
        return result;
      },
      ["db", `value`, "store", "trigger"]
    );
  }

  __init() {
    if (this.db?.refId) {
      this.subscribeTo(this.db.refId, () => {
        this.up({
          trigger: this.db?.[`trigger${capitalize(this.store.toLowerCase())}`],
        });
      });
    }
  }
}
