import { scalarParse } from "../scalar/scalarParse";
import type { Hash } from "../types";

/**
 * Decodes a URI component into a typed value: `{...}`/`[...]` payloads are JSON-parsed
 * (undefined when malformed), everything else is coerced via scalarParse.
 */
export const decodus = (val: string): any => {
  const value = decodeURIComponent(val);
  if ("{[".includes(value[0])) {
    try {
      return JSON.parse(value);
    } catch (_e) {
      return undefined;
    }
  }
  return scalarParse(value);
};

/**
 * Parses a query string into a hash, decoding keys and coercing values via decodus.
 * Pairs with an empty or missing value are skipped.
 *
 * @param r optional target object to merge into
 * @example parseQueryString("a=1&b=x%20y") // { a: 1, b: "x y" }
 */
export const parseQueryString = (s: string, r: Hash = {}): Hash => {
  s.split("&").forEach((param: string) => {
    const [key, value] = param.split("=");
    if (value) {
      r[decodeURIComponent(key)] = decodus(value);
    }
  });
  return r;
};
