import { delay, str, strTrim } from "ultimus";

/** Joined speech chunks, with the padding the recognizer leaves around them collapsed. */
const joinHeard = (...chunks: string[]): string => chunks.join(" ").replace(/\s+/g, " ").trim();

/** A breath before an empty result, so a caller listening in a loop can't spin. */
const RETRY_GAP_MS = 550;

/** A breath before picking the microphone back up, so a dying recognizer can't spin. */
const RESTART_GAP_MS = 250;

/**
 * How many times an open-ended attempt restarts without hearing anything before giving
 * up. Chrome's quiet cycle is a handful of seconds, so this is a long pause — long
 * enough to think, short enough that a microphone held by something else gives up.
 */
const MAX_QUIET_RESTARTS = 20;

/** Recognizer failures no restart can fix — the microphone is not coming back on its own. */
const FATAL_ERRORS = new Set([
  "not-allowed",
  "service-not-allowed",
  "audio-capture",
  "language-not-supported",
  "bad-grammar",
  "aborted",
]);

/** What the recognizer has so far. `text` is `confirmed` and `interim` joined — what to display. */
export type Heard = {
  text: string;
  /** Results the recognizer has committed to. Only these end an attempt. */
  confirmed: string;
  /** The tail it is still revising; always "" unless `interimResults` is on. */
  interim: string;
};

export type SpeechListenerOptions = {
  /** BCP47 tag, read per attempt, so a language switch takes effect on the next one. */
  lang: () => string;
  /**
   * Settle this long after the last confirmed result — the pause that ends an utterance.
   * `0` settles on the first confirmed result instead of waiting for a pause.
   */
  silenceMs?: number;
  /**
   * Keep the attempt open across pauses, however much is said: only `abort()`, a
   * recognizer error or the recognizer stopping ends it. For dictation, where restarting
   * between utterances would drop the words spoken in the gap. Overrides `silenceMs`.
   */
  untilStopped?: boolean;
  /**
   * Give up this long after the microphone goes live when nothing is said.
   * `0` waits indefinitely, until speech, an error or `abort()`. The window guards the
   * wait for speech only — it is dropped once the first confirmed result arrives.
   */
  timeoutMs?: number;
  /** Report the tail the recognizer is still revising, not just what it has committed to. */
  interimResults?: boolean;
  /** Fires on every result, with what has been heard so far. */
  onHeard?: (heard: Heard) => void;
  /**
   * Why listening failed: a `SpeechRecognitionErrorEvent.error` code (`no-speech`,
   * `not-allowed`, `aborted`, …), `unsupported` when the browser has no recognizer,
   * the `DOMException` name of a refused start — or `""` when a fresh attempt clears
   * the previous failure. Callers map these to their own copy.
   */
  onError?: (code: string) => void;
  logError?: (error: unknown, context: string) => void;
};

/**
 * One attempt at a time over the browser's `SpeechRecognition`.
 *
 * `listen()` resolves with what was said. What ends an attempt is the caller's choice:
 * the first confirmed result (the default), `silenceMs` of quiet after one, or nothing
 * but `abort()` (`untilStopped`) — and in every case a timeout, a recognizer error or
 * the recognizer stopping on its own. It never rejects: an unsupported browser or a
 * denied microphone reports through `onError` and resolves empty, so a caller can drive
 * a listen → answer loop without a single try/catch.
 *
 * Each attempt owns a fresh recognizer, so a loop of `listen()` calls never trips over
 * a recognizer that has already stopped. This is the one place in the kit that touches
 * `SpeechRecognition` — `SpeechService` wraps it as mounted, callback-driven
 * state for templates; drive it directly when you want the promise.
 */
export class SpeechListener {
  private recognition: any = null;
  /** Ends the attempt in flight with what was heard so far; null when idle. */
  private pending: (() => void) | null = null;
  private timer: any = null;

  constructor(private readonly options: SpeechListenerOptions) {}

  get isListening(): boolean {
    return !!this.pending;
  }

  listen(): Promise<string> {
    const {
      lang,
      silenceMs = 0,
      untilStopped,
      timeoutMs = 0,
      interimResults,
      onHeard,
      onError,
      logError,
    } = this.options;
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      onError?.("unsupported");
      return delay(RETRY_GAP_MS).then(() => "");
    }
    // A new attempt starts clean — the previous failure is no longer news.
    onError?.("");

    return new Promise<string>((resolve) => {
      let settled = false;
      let confirmed = "";
      let recognition: any = null;
      // Restarts since the last thing we heard, and why the recognizer stopped last.
      let quietRestarts = 0;
      let lastCode = "";

      const detach = (target: any) => {
        try {
          Object.assign(target, { onresult: null, onerror: null, onend: null, onaudiostart: null });
          target.stop();
        } catch {}
      };

      const finish = () => {
        if (settled) return;
        settled = true;
        this.clearTimer();
        this.pending = null;
        detach(recognition);
        if (this.recognition === recognition) this.recognition = null;
        resolve(strTrim(confirmed));
      };

      // The window guards the wait for the first words only; it is done once they land.
      const armWindow = () => {
        if (timeoutMs && !confirmed) this.arm(finish, timeoutMs);
      };

      /**
       * The recognizer stopped without being told to. Chrome does this on its own after a
       * stretch of quiet, even with `continuous` — for an open-ended attempt that is a
       * pause, not an ending, so pick the microphone back up and keep what was said.
       */
      const ended = () => {
        if (settled) return;
        if (!untilStopped) return finish();
        if (++quietRestarts > MAX_QUIET_RESTARTS) {
          const code = lastCode || "no-speech";
          logError?.(code, "SpeechListener.recognition");
          onError?.(code);
          finish();
          return;
        }
        detach(recognition);
        this.arm(start, RESTART_GAP_MS);
      };

      const start = () => {
        if (settled) return;
        recognition = new SpeechRecognition();
        recognition.lang = lang();
        recognition.continuous = true;
        recognition.interimResults = !!interimResults;

        recognition.onresult = (event: any) => {
          const results = Array.from<any>(event.results).slice(event.resultIndex);
          const textOf = (chunks: any[]) => joinHeard(...chunks.map((result) => str(result[0].transcript)));
          const final = textOf(results.filter((result) => result.isFinal));
          const interim = textOf(results.filter((result) => !result.isFinal));
          // Interim text is shown but not kept — only a confirmed result joins the answer.
          if (final) confirmed = joinHeard(confirmed, final);
          onHeard?.({ text: joinHeard(confirmed, interim), confirmed, interim });
          if (!final) return;
          quietRestarts = 0;
          // Speech has started, so the window that guarded the wait for it has done its job.
          if (untilStopped) {
            this.clearTimer();
            return;
          }
          // With no pause to wait out, the first confirmed result ends the attempt.
          if (silenceMs) this.arm(finish, silenceMs);
          else finish();
        };
        // A fresh recognizer needs a moment to bring the audio pipeline up — on the first
        // attempt that can swallow the opening words. Restart the window once the mic is
        // really live, so a slow start doesn't cut the speaker short.
        recognition.onaudiostart = armWindow;
        recognition.onerror = (event: any) => {
          const code = str(event?.error ?? event);
          lastCode = code;
          // A restartable failure is not news to an open-ended caller — `ended` picks the
          // microphone back up, and only giving up for good is worth logging. Restart from
          // here rather than waiting for `onend`, which not every browser sends after an
          // error; detaching first keeps the one we may still get from firing twice.
          if (untilStopped && !FATAL_ERRORS.has(code)) return ended();
          logError?.(code, "SpeechListener.recognition");
          onError?.(code);
          finish();
        };
        recognition.onend = ended;

        this.recognition = recognition;
        try {
          recognition.start();
        } catch (err: any) {
          logError?.(err, "SpeechListener.recognition.start");
          onError?.(str(err?.name));
          finish();
          return;
        }
        armWindow();
      };

      this.pending = finish;
      start();
    });
  }

  /** Stop recording early; the attempt in flight resolves with what was heard so far. */
  abort() {
    this.pending?.();
  }

  /** (Re)arm the pending deadline — one timer at a time, so arming again just extends it. */
  private arm(onElapsed: () => void, ms: number) {
    this.clearTimer();
    this.timer = setTimeout(onElapsed, ms);
  }

  private clearTimer() {
    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }
  }
}
