import type { Hash } from "../types";

/**
 * Keeps items whose `key` property is truthy, or loosely equals `val` when provided.
 * Unlike `filter`, a missing `key` passes the whole list through and nullish input yields [].
 */
export const arrayFilter = <T>(x: T[], key, val?: unknown) =>
  !x || !key ? (x ?? []) : x.filter?.(typeof val === "undefined" ? (e: T) => !!e?.[key] : (e: T) => e?.[key] == val);

/**
 * Exact-match filter by field, passing everything through for the "all" sentinel
 * ("**") or an empty value. Used to narrow the catalog table by the selected subtype.
 */
export function filterEquals<T extends Record<string, any>>(data: T[] | undefined, value: any, field: string): T[] {
  if (!data || value == null || value === "" || value === "**") return data ?? [];
  return data.filter((e) => e?.[field] === value);
}

/** Keeps items whose `key` property is truthy, or loosely equals `val` when provided. */
export const filter = <T extends Hash<any>>(x: T[], key = "isSelected", val?: unknown) =>
  x?.filter?.(typeof val === "undefined" ? (e: T) => !!e?.[key] : (e: T) => e?.[key] == val);

/** Inverse of `filter`: keeps items whose `key` property is falsy, or loosely differs from `val`. */
export const filterNot = <T extends Hash<any>>(x: T[], key = "isSelected", val?: unknown) =>
  x?.filter?.(typeof val === "undefined" ? (e: T) => !e?.[key] : (e: T) => e?.[key] != val);

/** Keeps items whose `key` property is greater than `val`. */
export const filterMoreThan = <T extends Hash<any>>(x: T[], key = "isSelected", val: number | string = 0) =>
  x?.filter?.((e: T) => e?.[key] > val);

/** Keeps items whose `key` property is less than `val`. */
export const filterLessThan = <T extends Hash<any>>(x: T[], key = "isSelected", val: number | string = 0) =>
  x?.filter?.((e: T) => e?.[key] < val);

/** Prepends an "All" option (default id "**") to a list of filter options. */
export const addFilterAllOption = (array: any[], name = "All", id = "**") => {
  return [{ id, name }].concat(array);
};

/**
 * Filters by keyword against `propName` (case-insensitive): prefix matches win, otherwise substring matches.
 * "**"/"(all)"/empty pass everything through; "--"/"(empty)" keep items with an empty property.
 */
export const filterByKeyword = <T extends Hash<any>>(array: T[], keyword: any, propName = "name") => {
  if (!keyword || keyword === "**" || keyword === "(all)" || !array) return array;
  if (keyword == "--" || keyword == "(empty)") return array.filter((e) => !e[propName]);

  const loKeyword = String(keyword.value ?? keyword).toLowerCase();
  const starters = array.filter((e) => String(e[propName]).toLowerCase().startsWith(loKeyword));
  if (starters.length) return starters;
  return array.filter((e) => String(e[propName]).toLowerCase().includes(loKeyword));
};

/**
 * Keeps or drops items by id set depending on `mode` ("selected" | "unselected").
 *
 * @param selectedIds - array or comma-separated string of ids; empty selection passes everything through
 */
export const filterBySelection = <T extends { id: unknown }>(
  items: T[] | undefined,
  mode: string | undefined,
  selectedIds: string | string[] | null | undefined
): T[] | undefined => {
  if (!items || !mode) return items;
  const list = Array.isArray(selectedIds) ? selectedIds : String(selectedIds).split(",");
  const ids = new Set(list.map((s) => String(s).trim()).filter(Boolean));
  if (!ids.size) return items;
  if (mode === "unselected") return items.filter((item) => !ids.has(String(item.id)));
  if (mode === "selected") return items.filter((item) => ids.has(String(item.id)));
  return items;
};

/**
 * Keeps items whose `prop` value starts with `prefix`.
 * "*"/empty pass everything through; "--" keeps empty values; "**" keeps non-empty values.
 */
export const filterByPrefix = <T extends Hash<any>>(array: T[], prefix: string, prop = "id") => {
  if (!prefix || prefix === "*" || !array) return array;
  if (prefix == "--") return array.filter((e) => !e[prop] || e[prop] == "--");
  if (prefix == "**") return array.filter((e) => !!e[prop]);

  return array.filter((e) => e[prop] && String(e[prop]).startsWith(prefix));
};
