import { WebClientService } from "@/core";
import { ancestorDirIds, docIdOf, type SiteTreeResponse, scopeSiteTree, type TreeNode } from "./siteTree";
import { classifyDocHref } from "./utils/resolveDocHref";

const SKELETON_DELAY_MS = 100;

/**
 * Loads a markdown docs corpus: a site-tree index (`indexUrl`, scoped by `scope`)
 * plus the currently selected document (`doc`, resolved through `resolvePattern`),
 * and keeps the per-reader reading state (progress / opened sections / expand-all).
 *
 * Apps subclass this to add their own state; the docs-site kit registers it as-is
 * (see `arrmatura-web/books`).
 */
export class DocsService extends WebClientService {
  text = "";
  loading = false;
  error = "";
  /** Id of the currently loaded document — the base relative links resolve against. */
  docId = "";
  resolvePattern = "/docs/{id}.md";
  /** Prefix of the site-tree paths this instance serves; stripped from the node ids. */
  scope = "docs/";
  declare progress: Record<string, boolean>;
  declare opened: Record<string, boolean>;
  declare expandedAll: boolean;
  declare index: any;

  #seq: Record<"index" | "doc", number> = { index: 0, doc: 0 };

  constructor() {
    super();

    this.__defineStoredProperty("progress", (v) => v ?? {});
    this.__defineStoredProperty("opened", (v) => v ?? {});
    this.__defineStoredProperty("expandedAll", (v) => v ?? false);
  }

  /**
   * Follows a link clicked inside a rendered document (see `MDLink`).
   *
   * Cross-document `.md` links are resolved against the current document and
   * matched against the site tree, then followed in-app via the `doc` nav param.
   * Anything genuinely outside the app opens in a new tab; a link that stays
   * inside it never does, since that would only ever open a dead tab.
   */
  gotoLocalLink(href: string) {
    const link = classifyDocHref(href, this.docId);
    switch (link.kind) {
      case "ignore":
        return;
      case "route":
        window.location.href = link.hash;
        return;
      case "external":
        window.open(href);
        return;
      case "doc": {
        // Exact resolution first; fall back to the file name for docs whose
        // relative depth does not match where the file actually sits.
        const node = this.findNodeById(link.id) ?? this.findNodeByFileName(link.fileName);
        const docId = node && docIdOf(node);
        if (docId) window.location.href = `#/?doc=${docId}`;
        else console.warn(`No such document: ${href} (from ${this.docId})`);
      }
    }
  }

  /**
   * Ids of the directories holding the current document, as `{ id: true }` — what a
   * tree consults to keep the path to the open document expanded, so that a document
   * reached from outside the tree (a deep link, a cross-document link, a reload) is
   * revealed rather than hidden inside collapsed folders. Recomputed on every `doc`
   * change, since `up()` clears the calculated-property cache.
   */
  getOpenPath(): Record<string, boolean> {
    return ancestorDirIds(this.docId);
  }

  /**
   * Finds the node that opens a document id (docs-root-relative path, extension
   * kept) — a file leaf, or the directory a hidden `index.md` was hoisted onto.
   */
  findNodeById(id: string, nodes = this.index?.nodes): any {
    return this.findNode((node) => docIdOf(node) === id, nodes);
  }

  /** Finds a node by file name alone — ambiguous across directories, so a last resort. */
  findNodeByFileName(fileName: string, nodes = this.index?.nodes): any {
    return this.findNode((node) => docIdOf(node)?.split("/").at(-1) === fileName, nodes);
  }

  findNode(match: (node: TreeNode) => boolean, nodes = this.index?.nodes): any {
    for (const node of nodes || []) {
      if (match(node)) return node;

      if (node.nodes) {
        const found = this.findNode(match, node.nodes);
        if (found) return found;
      }
    }
    return null;
  }

  toggleProgress(id: string) {
    const current = this.progress[id] ?? false;
    this.up({ progress: { ...this.progress, [id]: !current } });
  }

  toggleOpened(id: string) {
    const current = this.opened[id] ?? this.expandedAll ?? false;
    this.up({ opened: { ...this.opened, [id]: !current } });
    // On expand (not collapse), bring the section header to the top of the viewport.
    if (!current) {
      setTimeout(() => {
        document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 50);
    }
  }

  expandAll() {
    this.up({ expandedAll: true });
  }

  collapseAll() {
    this.up({ expandedAll: false, ...(!this.expandedAll ? { opened: {} } : {}) });
  }

  /**
   * Runs a request with the skeleton deferred: `loading` only flips once the
   * request is still in flight after SKELETON_DELAY_MS, so a cached response
   * swaps straight to the new content without a skeleton frame. A request
   * superseded on the same channel is dropped rather than applied late.
   */
  #load(channel: "index" | "doc", request: Promise<Record<string, any>>) {
    const seq = ++this.#seq[channel];
    const isCurrent = () => seq === this.#seq[channel];
    const timer = setTimeout(() => {
      if (isCurrent()) this.up({ loading: true });
    }, SKELETON_DELAY_MS);

    request
      .catch((err) => ({ error: String(err) }))
      .then((patch) => {
        clearTimeout(timer);
        if (isCurrent()) this.up({ ...patch, loading: false });
      });
  }

  set indexUrl(url: string) {
    if (!url) return;
    this.up({ error: "" });
    this.#load(
      "index",
      this.fetchJson<SiteTreeResponse>(url).then((data) => ({
        index: { id: this.scope, name: "Docs", type: "dir", path: this.scope, nodes: scopeSiteTree(data, this.scope) },
      }))
    );
  }

  set doc(id: string) {
    this.up({ error: "", docId: id ?? "" });
    this.#load(
      "doc",
      id
        ? this.fetch(this.resolvePattern.replace("{id}", id))
            .then((text) => ({ text }))
            .catch((err) => ({ error: String(err), text: "" }))
        : Promise.resolve({ text: "" })
    );
  }
}
