import { Component } from "arrmatura";
import { type Hash, objectToArray } from "ultimus";
import { OrderedListTransaction } from "./OrderedListTransaction";

export class OrderedListController extends Component {
  data?: Hash[] | null;
  change = (_delta: Hash) => {
    // no-op
  };

  /**
   * Reorder item with fromId to the position before toId
   */
  reorderItems(params: { fromId: string; toId: string }) {
    const changes = new OrderedListTransaction(this.data).reorderItems(params);
    if (changes) {
      const data = objectToArray(changes);
      this.change({ data });
    }
  }
}
