import type { Fn, Hash } from "../types";

/**
 * Indexes an array into a hash keyed by `idKey` (property name or extractor); later duplicates win.
 *
 * @param valKey - optional property name or mapper for the stored value; defaults to the item itself
 * @example
 * arrayToObject([{ id: "a", name: "A" }, { id: "b", name: "B" }])
 * // { a: { id: "a", name: "A" }, b: { id: "b", name: "B" } }
 * arrayToObject([{ id: "a", name: "A" }], "id", "name") // { a: "A" }
 */
export const arrayToObject = <T = any>(
  arr?: unknown[] | null,
  idKey: string | Fn = "id",
  valKey?: string | ((obj: any) => T)
) => {
  const r: Hash<T> = {};
  if (arr?.forEach) {
    const idFn = typeof idKey === "string" ? (e: any) => e[idKey] : idKey;
    const valFn = typeof valKey === "string" ? (e: any) => e[valKey] : valKey;
    arr.forEach((e) => {
      r[String(idFn(e))] = valFn ? valFn(e) : e;
    });
  }
  return r;
};
