import { getPredicat } from "ultimus";
import { DeferedContextAsyncInvocations } from "./deferables";
import { deleteDatabase } from "./deleteDatabase";
import { openDatabase } from "./openDatabase";
import { runTransaction } from "./transaction";
import type { DbQueryParams, Fn, Hash, OpenOptions } from "./types";

const DEBUG = false;

/**
 * Data storage on top of IndexedDb.
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/IndexedDB_API
 */
export class IDB {
  db?: IDBDatabase;
  invocations = new DeferedContextAsyncInvocations<IDBDatabase>();

  get name() {
    return this.db?.name;
  }

  async open({ initialDataFactory, ...options }: OpenOptions & { initialDataFactory?: Fn }) {
    const { db, upgradedTo } = await openDatabase(options);

    this.db = db;

    const output = { name: db.name, version: db.version, upgradedTo };

    // Enable transactions before seeding: the bundleApplicator below relies on
    // invocations running against a live context. Setting it after the factory
    // would queue the seed transactions and never resolve them.
    this.invocations.context = db;

    if (upgradedTo && initialDataFactory) {
      const bundleApplicator = async (bundle) => {
        if (!bundle || !Object.keys(bundle).length) return;

        const fn = (store: IDBObjectStore) => bundle[store.name]?.map((obj) => store.put(obj));
        const store = Object.keys(options.stores);
        const invokeFn = (db, oncomplete, onerror) => runTransaction({ db, store, oncomplete, onerror, fn });
        return this.invocations.invoke(invokeFn, true);
      };

      await initialDataFactory(output, bundleApplicator);
    }

    return output;
  }

  clearStore(store: string) {
    return this.invocations.invoke((db, oncomplete, onerror) =>
      runTransaction({ db, store, oncomplete, onerror, fn: (store) => store.clear() })
    );
  }

  putObject(obj: object, store: string) {
    return this.invocations.invoke((db, oncomplete, onerror) =>
      runTransaction({ db, store, oncomplete, onerror, fn: (store) => store.put(obj) })
    );
  }

  upsertObject<T = any>({ id, ...delta }, store: string) {
    return this.invocations.invoke<T | null>((db, oncomplete, onerror) => {
      const fn = (store) => {
        const rq = store.get(id);
        rq.onsuccess = (event: any) => {
          const obj = event.target.result ?? null;
          const obj2 = { ...obj, ...delta, id };
          const rq2 = store.put(obj2);
          rq2.onsuccess = () => oncomplete(obj2);
          rq2.onerror = onerror;
        };
        return rq;
      };
      runTransaction({ db, store, onerror, fn });
    });
  }

  batchPut(batch: Hash<any[]>) {
    const store = Object.keys(batch);
    if (store.length === 0) {
      return Promise.resolve();
    }
    const fn = (store: IDBObjectStore) => batch[store.name]?.map((obj) => store.put(obj));
    return this.invocations.invoke((db, oncomplete, onerror) => runTransaction({ db, store, oncomplete, onerror, fn }));
  }

  batchUpsert(batch: Hash<any[]>) {
    if (!batch) return null;

    const store = Object.keys(batch);
    if (store.length === 0) {
      return Promise.resolve();
    }
    const fn = (store: IDBObjectStore) =>
      batch[store.name]?.map(({ id, ...delta }) => {
        const rq = store.get(id);
        rq.onsuccess = ({ target }: any) => {
          store.put({ ...target.result, ...delta, id });
        };
        return rq;
      });

    return this.invocations.invoke((db, oncomplete, onerror) => {
      runTransaction({ db, store: Object.keys(batch), oncomplete, onerror, fn });
    });
  }

  deleteObject(key: string, store: string) {
    return this.invocations.invoke((db, oncomplete, onerror) =>
      runTransaction({ db, store, oncomplete, onerror, fn: (store) => store.delete(key) })
    );
  }

  deleteAllObjects(store: string) {
    return this.invocations.invoke((db, oncomplete, onerror) =>
      runTransaction({ db, store, oncomplete, onerror, fn: (store) => store.clear() })
    );
  }

  deleteDatabase() {
    this.db?.close();
    return deleteDatabase(this.db?.name);
  }

  bulkDelete(data: any[], store: string) {
    const fn = (store) => data.map((obj) => store.delete(typeof obj === "string" ? obj : obj.id));

    return this.invocations.invoke((db, oncomplete, onerror) => runTransaction({ db, store, oncomplete, onerror, fn }));
  }

  getObject<T = any>(key: string, storeId: string) {
    return this.invocations.invoke<T | null>((db, oncomplete, onerror) => {
      const fn = (store) => {
        const rq = store.get(key);
        rq.onsuccess = (event: any) => {
          const obj = event.target.result ?? null;
          if (DEBUG) console.log(`IDB: get object from ${storeId}.${key}`, obj);
          oncomplete(obj);
        };
        return rq;
      };
      runTransaction({ db, store: storeId, mode: "readonly", onerror, fn });
    });
  }

  query<T = any>({
    value: value0 = "",
    store = "items",
    index = null,
    direction,
    predicat = null,
    limit = 0,
  }: DbQueryParams = {}) {
    let value = String(value0 || "");

    const ts0 = DEBUG ? Date.now() : 0;

    const isBound = !value || value.endsWith("*");
    if (value && isBound) {
      value = value.slice(0, -1);
    }
    const keyRangeValue = !value
      ? undefined
      : isBound
        ? IDBKeyRange.bound(value, `${value}\uffff`)
        : IDBKeyRange.only(value);

    if (index?.startsWith("-")) {
      index = index.slice(1);
      direction = "prev";
    }

    if (!index && !limit && !predicat && !direction) {
      return this.invocations.invoke<T[] | null>((db, oncomplete, onerror) => {
        const fn = (datasource: IDBObjectStore) => {
          const rq = datasource.getAll(keyRangeValue, limit);

          rq.onerror = (error: any) => {
            onerror(error);
          };

          rq.onsuccess = (event: any) => {
            const data = event.target.result;
            if (DEBUG) {
              console.log(
                "IDB: query all from",
                store,
                keyRangeValue ?? "",
                "size=",
                data.length,
                "in",
                Date.now() - ts0
              );
            }
            oncomplete(data);
          };
        };

        runTransaction({ db, store, mode: "readonly", onerror, fn });
      });
    }

    return this.invocations.invoke<T[] | null>((db, oncomplete, onerror) => {
      const fn = (datasource: IDBObjectStore) => {
        const data: any[] = [];
        const rq = datasource.openCursor(keyRangeValue, direction);

        rq.onerror = (error: any) => {
          onerror(error);
        };

        const predicatFn = typeof predicat === "function" ? predicat : getPredicat(predicat ?? true);

        rq.onsuccess = (event: any) => {
          const result = event.target.result;
          if (!result || (limit && data.length >= limit)) {
            oncomplete(data);
            return;
          }
          const value = result.value;
          if (predicatFn(value)) {
            data.push(value);
          }
          if (limit && data.length >= limit) {
            oncomplete(data);
            return;
          }
          result.continue();
        };
      };
      runTransaction({ db, store, index: index ?? "", mode: "readonly", onerror, fn });
    });
  }
}
