import type { Guid } from "../types";

const s4 = () =>
  Math.floor((1 + Math.random()) * 0x10000)
    .toString(16)
    .substring(1);

/**
 * Generates a random GUID-shaped string ("xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx", lowercase hex).
 *
 * Uses `Math.random()`; not RFC 4122 compliant and not cryptographically secure.
 */
export const guid = (): Guid => `${s4()}${s4()}-${s4()}-${s4()}-${s4()}-${s4()}${s4()}${s4()}`;
