import type { Fn, XmlNode } from "ultimus";
import { asyncValueCall } from "ultimus";
import { Arrmatron } from "../core/Arrmatron";
import { Component } from "../core/Component";
import { ManifestNode } from "../core/ManifestNode";

class DataConnectorComponent extends Component {
  private _data: unknown;
  change?: Fn;

  get data() {
    return this._data;
  }

  set data(data: unknown) {
    // this.log("Connector data", data);
    this._data = data;
    asyncValueCall(data, (v) => {
      if (v !== undefined) {
        (this.change as Fn)?.(v);
      }
    });
  }
}

class TriggerConnectorComponent extends Component {
  change?: Fn;
  private _trigger: any;
  data: any;

  get trigger() {
    return this._trigger;
  }

  set trigger(trigger: any) {
    this._trigger = trigger;
    asyncValueCall(trigger, (v) => {
      if (v !== undefined) {
        asyncValueCall(this.data, (d) => {
          (this.change as Fn)?.(d);
        });
      }
    });
  }
}

class Connector extends Arrmatron<ConnectorNode> {
  createComponent() {
    const Ctor = this.manifest.componentClass;
    return new Ctor();
  }

  get displayName(): string {
    return "🔹Connector";
  }
}

export class ConnectorNode extends ManifestNode {
  componentClass: typeof Component;

  constructor({ attrs, id }: XmlNode) {
    super(id);
    const { trigger, change, ...props } = attrs as any;
    this.compileAttributes(trigger ? { change, ...props, trigger } : { change, ...props });
    this.componentClass = trigger ? TriggerConnectorComponent : DataConnectorComponent;
  }

  get EntitronConstructor() {
    return Connector;
  }
}
