import { Component } from "arrmatura";
import { objectOmitKeys, type Url, urlParse, urlStringify } from "ultimus";
export class NavigationService extends Component {
  host: any;
  path: any;
  params: any;
  queryParams;
  locationHost;
  locationPage;
  page;

  __init() {
    const hashchange = (ext = {}) => {
      const hash = window.location.hash.slice(1);
      const { host, path, params } = urlParse(window.location.href);
      this.queryParams = params;
      this.locationHost = host;
      this.locationPage = String(path[0] || "").split(".")[0];
      const route = this.parse(hash);
      void this.up({ ...route, route, ...ext });
    };

    window.addEventListener("popstate", hashchange);
    window.addEventListener("hashchange", hashchange);
    this.defer(() => {
      window.removeEventListener("hashchange", hashchange);
      window.removeEventListener("popstate", hashchange);
    });

    setTimeout(() => {
      hashchange({ isReady: true });
    }, 0);
  }

  parse(d: string | Partial<Url>) {
    const fromHash = typeof d === "string";
    const { host, path = [], params = {} } = fromHash ? urlParse(`/${d}`) : d;
    const page = host || "";
    const subpage = path[0] || null;
    const mergedParams = fromHash
      ? { ...this.queryParams, ...params }
      : this.page == page
        ? { ...this.queryParams, ...this.params, ...params }
        : { ...this.queryParams, ...params };
    return {
      locationHost: this.locationHost,
      locationPage: this.locationPage,
      page,
      subpage,
      path,
      params: mergedParams,
    };
  }

  updateHash(d: string | Partial<Url>) {
    const route = this.parse(d);
    const params = objectOmitKeys(route.params, Object.keys(this.queryParams));
    const sUrl = urlStringify({ ...route, host: route.page, params });
    window.location.hash = sUrl.startsWith("//") ? sUrl.slice(1) : sUrl;

    void this.up({ ...route, route });
  }

  updateParams(params: object) {
    if (params) {
      this.updateHash({ host: this.page, path: this.path, params: { ...params } });
    }
  }

  updateParam(expr, val = "") {
    const [key, value = val] = expr.split("=");
    this.updateParams({ ...this.params, [key]: value });
  }
}
