/**
 * String case transformation utilities.
 */

import { str } from "./convert";

/** Uppercases the first character of a string. */
export function capitalize(x: unknown): string {
  const s = str(x);
  return s.length ? s[0].toUpperCase() + s.slice(1) : "";
}

/** Lowercases the first character of a string. */
export function lowerize(x: unknown): string {
  const s = str(x);
  return s.length ? s[0].toLowerCase() + s.slice(1) : "";
}

/**
 * Splits a string by `sep`, maps non-empty chunks through `fn`, drops empty results, joins with `joinSep`.
 * @example mapChunks("a_b", (c, i) => (i ? c.toUpperCase() : c)) // "a_B"
 */
export function mapChunks(x: unknown, fn: (chunk: string, index: number) => string, sep = "_", joinSep = sep): string {
  return x == null ? "" : String(x).split(sep).filter(Boolean).map(fn).filter(Boolean).join(joinSep);
}

/**
 * Converts a separator-delimited string to camelCase.
 * @example camelize("a_b") // "aB"
 */
export function camelize(x: unknown, sep = "_"): string {
  return mapChunks(x, (chunk, index) => (index ? capitalize(chunk) : chunk), sep, "");
}

/**
 * Converts a separator-delimited string to PascalCase.
 * @example properCase("hello_world") // "HelloWorld"
 */
export function properCase(x: unknown, sep?: string): string {
  return capitalize(camelize(x, sep));
}

/**
 * Converts a camelCase string to snake_case.
 * @example snakeCase("helloWorld") // "hello_world"
 */
export function snakeCase(x: unknown): string {
  return str(x)
    .replace(/([a-z])([A-Z])/g, "$1_$2")
    .toLowerCase();
}

/** Converts to uppercase. */
export function upperCase(x: unknown): string {
  return str(x).toUpperCase();
}

/** Converts to lowercase. */
export function lowerCase(x: unknown): string {
  return str(x).toLowerCase();
}

/**
 * Converts a string to a qualified identifier: non-word runs collapse, chunks join as camelCase.
 * @param re pattern for characters to treat as separators
 * @example qname(" Hello-World ") // "helloWorld"
 */
export function qname(x: unknown, re = /\W+/g): string {
  return x == null
    ? ""
    : mapChunks(String(x).trim().replaceAll(re, "_"), (t, i) => (i ? capitalize(t) : lowerize(t)), "_", "");
}

/** @deprecated Use lowerize instead */
export const strLowerize = lowerize;

/** @deprecated Use mapChunks instead */
export const strMapChunks = mapChunks;
