import { strTrim } from "ultimus";

/**
 * Mermaid loading and render orchestration.
 *
 * Mermaid draws into a temporary `div#d<id>` parked on `document.body` and, before it starts, removes
 * every element that already carries `<id>`. Rendering is asynchronous (the diagram type is loaded on
 * demand), so two diagrams sharing one id delete each other's nodes mid-flight and at least one of them
 * ends up blank. Hence: a fresh id per render — never the target element's own id, which mermaid would
 * happily remove — and one render at a time, because mermaid v10 also resets its global config per call.
 */

const MERMAID_CDN = "https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js";

// Timeline period boxes use cScale(N+1) for `.section-N`. The default yellow and greens
// (hue 60/80/90/150 pastels) are too pale to read; replace them with darker tones. Black label text stays readable.
const MERMAID_CONFIG = {
  startOnLoad: false,
  themeVariables: {
    cScale1: "#fdd835",
    cScale2: "#8bc34a",
    cScale8: "#66bb6a",
    cScale9: "#26a69a",
  },
};

export interface MermaidDiagram {
  svg: string;
  bindFunctions?: (elt: unknown) => void;
}

export interface MermaidApi {
  render: (id: string, source: string) => Promise<MermaidDiagram>;
}

let mermaidPromise: Promise<MermaidApi> | null = null;
let renderSeq = 0;
let renderQueue: Promise<unknown> = Promise.resolve();

const nextRenderId = (eltId: string): string => `${strTrim(eltId) || "mermaid"}-svg-${++renderSeq}`;

/** Runs `task` after every render queued before it; a rejected task must not break the chain. */
const enqueue = <T>(task: () => Promise<T>): Promise<T> => {
  const done = renderQueue.then(task);
  renderQueue = done.then(
    () => undefined,
    () => undefined
  );
  return done;
};

/** Mermaid removes its temp container itself, but not when the render threw. */
const dropTempNode = (renderId: string): void => {
  globalThis.document?.getElementById(`d${renderId}`)?.remove();
};

export const errorText = (err: unknown): string =>
  (err instanceof Error ? err.message : strTrim(err)) || "unknown error";

export function loadMermaid(): Promise<MermaidApi> {
  const loaded = (globalThis as any).mermaid as MermaidApi | undefined;
  if (loaded) return Promise.resolve(loaded);
  if (mermaidPromise) return mermaidPromise;

  mermaidPromise = new Promise<MermaidApi>((resolve, reject) => {
    const script = Object.assign(document.createElement("script"), {
      src: MERMAID_CDN,
      onload: () => {
        const mermaid = (globalThis as any).mermaid;
        if (!mermaid) {
          mermaidPromise = null;
          reject(new Error(`Loaded ${MERMAID_CDN}, but it defined no mermaid global`));
          return;
        }
        mermaid.initialize(MERMAID_CONFIG);
        resolve(mermaid);
      },
      onerror: () => {
        mermaidPromise = null;
        reject(new Error(`Failed to load mermaid from ${MERMAID_CDN}`));
      },
    });
    document.head.appendChild(script);
  });
  return mermaidPromise;
}

/** Renders one diagram under an id of its own, serialized against every other render. */
export async function renderDiagram(mermaid: MermaidApi, source: string, eltId: string): Promise<MermaidDiagram> {
  const renderId = nextRenderId(eltId);
  try {
    const diagram = await enqueue(() => mermaid.render(renderId, source));
    if (!strTrim(diagram?.svg)) throw new Error("mermaid produced an empty diagram");
    return diagram;
  } catch (err) {
    dropTempNode(renderId);
    throw err;
  }
}
