import type { Hash } from "ultimus";
import { WebClientService } from "@/core";

export class ItemController extends WebClientService {
  data?: Hash | null;
  delta?: Hash | null;
  api?: any;
  store = "items";
  #itemId = null;

  invokeLoad(id) {
    this.api.loadObject({
      id,
      store: this.store,
      callback: ({ error = null, item, data = item }) => {
        if (error) {
          const msg = (error as Error)?.message;
          this.toast({ id: msg, level: "error", message: `Error: ${msg}` });
        }
        this.up({ isLoading: false, touched: false, data, error });
      },
    });
  }

  get itemId() {
    return this.#itemId;
  }

  set itemId(id) {
    this.#itemId = id;

    this.up({ delta: {}, isLoading: true, error: null, touched: false });

    this.invokeLoad(id);
  }

  doReload() {
    this.up({ isLoading: true, error: null });

    this.invokeLoad(this.#itemId);
  }

  // event handlers:
  onChange = (delta: Hash) => {
    this.up({
      touched: true,
      delta: { ...this.delta, ...delta },
      data: { ...this.data, ...delta },
    });
  };

  onSave(delta = {}) {
    this.up({ isLoading: true, error: null });

    this.api.upsertObject({
      ...this.data,
      ...delta,
      store: this.store,
      callback: ({ error = null, item, data = item }) => {
        if (error) {
          const message = `Error: ${(error as Error)?.message}`;
          this.toast({ id: message, level: "error", message });
          this.up({ isLoading: false, error, data });
        } else {
          const message = "❎ Updated successfully. ";
          this.toast({ message, timeout: 5000 });
          this.up({ isLoading: false, touched: false, data });
        }
      },
    });
  }
}
