import type { Hash } from "ultimus";
import { encodus } from "ultimus";
import { WebClientService } from "@/core";

export class NewItemController extends WebClientService {
  all?: Hash<Hash>;
  store = "";
  itemId = "";
  meta: any;
  api: any;
  data: any = null;

  submit() {
    const { id, store = this.store, ...data } = this.data;
    this.up({ busy: true, error: null });
    this.api.upsertObject({
      ...data,
      id,
      store,
      callback: ({ error = null, item }) => {
        console.log(error, item);
        if (error) {
          const msg = (error as Error)?.message;
          this.toast({
            id: msg,
            level: "error",
            timeout: -1,
            message: `Error: ${msg}`,
          });
          this.up({ busy: false, error });
          return;
        }

        this.toast({
          message: `✅ A new ${store} added.`,
          details: `"${item.name ?? item.id}"`,
          timeout: -1,
          link: `/#/item?id=${encodus(`${item.id}:${store}`)}`,
        });
        this.up({ busy: false, showModal: false });
      },
    });
  }

  // event handlers:
  change(delta: Hash) {
    this.up({
      touched: true,
      data: { ...this.data, ...delta },
    });
  }
}
