import { asyncValueCall } from "ultimus";
import { ExpressionParserBase } from "./ExpressionParserBase";
import { fnFalse, fnNull, fnTrue, fnUndefined } from "./operations";

export type { ParserContext } from "./ParserContext";

export class ExpressionParser extends ExpressionParserBase {
  parse(): any {
    const result = this.parsePipesExpression(this.parseExpression());
    this.checkExceeded();

    // console.log(this.input, result);
    return result;
  }

  parsePipesExpression(expr): any {
    if (this.consumeIf("|")) {
      this.consumeWhitespace();
      const pipeId = this.parseIdentifier().name;
      this.consumeWhitespace();

      const args: any[] = [];
      while (this.consumeIf(":")) {
        this.consumeWhitespace();
        args.push(this.parseExpression());
      }

      return this.parsePipesExpression({
        type: "Pipe",
        args,
        pipeId,
        from: expr,
        fn: (c, ev) => {
          const pipeFn = this.ctx.getFunction(c, pipeId);
          if (!pipeFn) {
            c.logError(`Undefined pipe function:${pipeId}`);
          }
          const value = expr.fn(c, ev);
          return asyncValueCall(value, (pValue) => pipeFn?.call(c, pValue, ...args.map((f) => f.fn(c, ev))));
        },
      });
    }

    return expr;
  }

  parseExpression(): any {
    const result = this.parseTernary();

    this.consumeWhitespace();

    return result;
  }
  parseTernary(): any {
    const condition = this.parseCoalesce();

    if (this.consumeIf("?")) {
      this.consumeWhitespace();
      const trueExpr = this.parseExpression();
      let falseExpr: any;
      if (this.consumeIf(":")) {
        this.consumeWhitespace();
        falseExpr = this.parseExpression();
      }
      return {
        type: "Ternary",
        condition,
        trueExpr,
        falseExpr,
        fn: (c, ev) => (condition.fn(c, ev) ? trueExpr.fn(c, ev) : falseExpr ? falseExpr.fn(c, ev) : undefined),
      };
    }

    return condition;
  }
  parseCoalesce(): any {
    return this.parseLeftRight(["??"], "parseOr", "parseCoalesce");
  }

  parseOr(): any {
    return this.parseLeftRight(["||", "OR"], "parseAnd", "parseOr");
  }

  parseAnd(): any {
    return this.parseLeftRight(["&&", "AND"], "parseCompare", "parseAnd");
  }

  parseCompare(): any {
    return this.parseLeftRight(["===", "==", "!="], "parseEquality", "parseEquality");
  }
  parseEquality(): any {
    return this.parseLeftRight([">=", ">", "GTE", "GT", "<=", "<", "LT"], "parsePlus", "parsePlus");
  }

  parsePlus(): any {
    return this.parseLeftRight(["+", "-"], "parseMulti", "parsePlus");
  }

  parseMulti(): any {
    return this.parseLeftRight(["*", "/", "%"], "parseUnary", "parseMulti");
  }

  parseUnary(): any {
    if (this.consumeIf("!")) {
      const expr = this.parseUnary();
      return { type: "Not", expr, fn: (c, ev) => !expr.fn(c, ev) };
    }

    return this.parsePrimary();
  }

  parsePrimary(): any {
    if (this.consumeIf("(")) {
      this.consumeWhitespace();
      const expr = this.parseExpression();
      this.consume(")");
      return this.parsePropertyAccess(expr);
    }

    if (this.consumeIf("true")) return { type: "Boolean", value: true, fn: fnTrue };
    if (this.consumeIf("false")) return { type: "Boolean", value: false, fn: fnFalse };
    if (this.consumeIf("null")) return { type: "Null", fn: fnNull };
    if (this.consumeIf("undefined")) return { type: "Undefined", fn: fnUndefined };

    if (this.checkIf("'") || this.checkIf('"')) {
      return this.parseString();
    }

    if (this.checkIfNum()) {
      return this.parseNumber();
    }

    return this.parsePropertyAccess(this.parseIdentifier());
  }

  parsePropertyAccess(expr: any): any {
    this.consumeWhitespace();

    if (this.consumeIf(".")) {
      const prop = this.parseIdentifier();
      return this.parsePropertyAccess({
        type: "PropertyAccess",
        object: expr,
        property: prop.name,
        fn: (c, ev) => expr.fn(c, ev)?.[prop.name],
      });
    }

    if (this.consumeIf("(")) {
      this.consumeWhitespace();
      const pipeId = expr.name;
      const args: any[] = [];
      if (!this.consumeIf(")")) {
        args.push(this.parseExpression());
        while (this.consumeIf(",")) {
          this.consumeWhitespace();
          args.push(this.parseExpression());
        }
        this.consumeWhitespace();
        this.consume(")");
      }
      return this.parsePropertyAccess({
        type: "Function",
        args,
        pipeId,
        fn: (c, ev) => {
          if (!pipeId) {
            c.logError(`Empty pipe function: ${pipeId}`);
            return args[0]?.fn(c, ev);
          }
          const pipeFn = this.ctx.getFunction(c, pipeId);
          if (!pipeFn) {
            c.logError(`Undefined pipe function: ${pipeId}`);
          }
          return pipeFn?.apply(
            c,
            args.map((f) => f.fn(c, ev))
          );
        },
      });
    }

    if (this.consumeIf("[")) {
      this.consumeWhitespace();
      const prop = this.parseExpression();
      this.consumeWhitespace();
      this.consume("]");
      return this.parsePropertyAccess({
        type: "ComputedPropertyAccess",
        object: expr,
        property: prop,
        fn: (c, ev) => expr.fn(c, ev)?.[prop.fn(c, ev)],
      });
    }

    return expr;
  }
}
