import type { Dateable } from "../types";

import { DEFAULT_DATE_TIME_FORMAT, monthNames } from "./consts";
import { dateFormat } from "./dateFormat";

export * from "./consts";
export { dateFormat } from "./dateFormat";
export { dateOf } from "./dateOf";
export { dateParseISO8601 } from "./dateParseISO8601";

/** Returns the full English month name for a 1-based month number (1 = January). */
export const monthName = (m: number): string => monthNames[m] as string;

/** Returns the current epoch time in milliseconds. */
export const now = () => Date.now();

/** Alias for `dateFormat`: formats a date-like value, defaulting to "yyyy-MM-dd". */
export const date = (x: Dateable | null, f?: string) => dateFormat(x, f);

/** Formats a date-like value with time, defaulting to "yyyy-MM-dd hh:mm". */
export const dateTimeFormat = (x: Dateable | null, f = DEFAULT_DATE_TIME_FORMAT) => dateFormat(x, f);

/**
 * Formats a duration in seconds as a short label: "45s", "5m", "2h 15m" or "3d 7h".
 *
 * @returns Formatted label, or null when the input is nullish.
 */
export const timeSecondsFormat = (seconds: number): string | null => {
  if (seconds == null) return null;
  if (seconds < 60) return `${seconds}s`;

  const minutes = Math.round(seconds / 60);
  if (minutes < 60) {
    return `${minutes}m`;
  }
  const hours = Math.round(minutes / 60);
  if (hours < 24) {
    return `${hours}h ${minutes % 60}m`;
  }
  const days = Math.round(hours / 24);
  return `${days}d ${hours % 24}h`;
};
