import type { XmlNode } from "ultimus";
import { Arrmatron } from "../core/Arrmatron";
import { ManifestNode } from "../core/ManifestNode";
import type { Composite } from "./composition";

class Slot extends Arrmatron {
  get displayName(): string {
    return "🔸slot";
  }

  getByRef(refId: string) {
    return this.scope?.getByRef(refId);
  }

  get slotContent() {
    return (this.scope as Composite).slotContent((this.manifest as CSlotNode).key);
  }

  get contentManifests() {
    return this.slotContent;
  }

  get scopeForChildren(): Arrmatron {
    return this.scope.scope;
  }
}

export class CSlotNode extends ManifestNode {
  key?: string;

  constructor(x: XmlNode) {
    super(x.id);
    this.key = x.attrs?.Key as string;
  }

  get EntitronConstructor() {
    return Slot;
  }
}
