import type { IArrmatron, IComponent, IComponentDescriptor, LogEntry } from "arrmatura";
import { Platform } from "arrmatura";
import type { Hash, XmlNode } from "ultimus";
import { xmlParse } from "ultimus";
import { DomElement } from "./native/DomElement";
import { DomElementAttributes } from "./native/DomElementAttributes";
import { reflow } from "./reflow";
import type { DomNode, IElement, IWebPlatform } from "./types";

/**
 * Arrmatura platform implementation for Web DOM.
 */
export class WebPlatform extends Platform implements IWebPlatform {
  readonly #asyncCalls = new Map<string, number>();

  constructor(
    readonly rootElement: ShadowRoot | HTMLElement,
    resources: Hash<any> = {}
  ) {
    super({});
    this.NativeElement = DomElement as any;
    this.updateResources(resources);
  }

  redraw(_: IArrmatron, root: IArrmatron) {
    requestAnimationFrame(() => {
      reflow(root.children, this.rootElement);
    });
  }

  getByTag(tag: string): IComponentDescriptor {
    const r = this.typeRegistry.get(tag) ?? (window[tag as keyof typeof window] as IComponentDescriptor | undefined);
    if (r) return r;
    return super.getByTag(tag);
  }

  xmlParse(template: string): XmlNode[] {
    try {
      return xmlParse(template);
    } catch (error) {
      return [
        {
          tag: "div",
          id: "error",
          nodes: [
            { tag: "div", text: String(error), class: "bg-red-600 text-white p-4 rounded mb-4" },
            {
              tag: "details",
              nodes: [
                { tag: "summary", text: "Template" },
                { tag: "pre", text: template },
              ],
            },
          ],
        },
      ] as unknown as XmlNode[];
    }
  }

  createComponent(def: IComponentDescriptor | string): IComponent {
    if (typeof def === "string") return this.createComponent(this.getByTag(def));
    if (def.unknown) {
      this.log({ level: "info", message: `<-- unknown tag: ${def.tag} -->`, source: "platform" });
    }
    return super.createComponent(def);
  }

  setElementAttribute(element: IElement, node: DomNode, key: string, value: any) {
    const setter = DomElementAttributes[key];
    if (setter) {
      setter(element, node, value);
    } else if (value != null) {
      node.setAttribute(key, value);
    } else {
      node.removeAttribute(key);
    }
  }

  addElementAttributeSetters(attrs: Hash<($: IElement, e: DomNode, v: unknown) => void>) {
    Object.assign(DomElementAttributes, attrs);
  }

  applyAsyncValue<T = unknown>(key: string, promiseOrValue: T | Promise<T>, fn: (val: T) => void) {
    if (!(promiseOrValue instanceof Promise)) {
      return fn(promiseOrValue);
    }

    const counter = 1 + (this.#asyncCalls.get(key) ?? 0);
    this.#asyncCalls.set(key, counter);
    return promiseOrValue.then((val) => {
      if (counter === this.#asyncCalls.get(key)) {
        return fn(val);
      }
    });
  }

  log({ level, source = "", message = "", error, params = [] }: LogEntry) {
    if (level === "error") {
      console.error("⛔ ERROR:", source ? `${source}:` : "", message, error?.message ?? "", ...params);
    } else if (level === "warning") {
      console.warn("⚠ WARNING:", source ? `${source}:` : "", message, error?.message ?? "", ...params);
    } else {
      console.log(source, message, ...params);
    }
  }
}
