import type { Url } from "../types";

import { encodus, stringifyUrlParams } from "./stringifyUrlParams";

/**
 * Serializes a Url object into a string of the form `schema://host/path?params#hash`.
 * Path segments, params and hash are URI-encoded; the schema is emitted only together with a host.
 *
 * @example urlStringify({ schema: "https", host: "ex.com", path: ["a"], params: { x: 1 } })
 * // "https://ex.com/a?x=1"
 */
export const urlStringify = (r: Partial<Url> | null): string => {
  if (!r) {
    return "";
  }
  let result = "";
  if (r.host) {
    if (r.schema) {
      result += `${r.schema}:`;
    }
    result += `//${r.host}`;
  }
  if (r.path?.length) {
    result += `/${r.path.filter(Boolean).map(encodeURIComponent).join("/")}`;
  }
  const sparams = r.params ? stringifyUrlParams(r.params) : "";
  if (sparams) {
    result += `?${sparams}`;
  }
  if (r.hash) {
    result += `${r.hash[0] === "#" ? "" : "#"}${encodus(r.hash)}`;
  }

  return result;
};
