import { Component, type LogEntry } from "arrmatura";
import { identity } from "ultimus";
import { ClientStorage } from "./support/ClientStorage";
import type { IWebPlatform, PersistenceType } from "./types";

export class WebClientService extends Component {
  name = "";
  persistence: PersistenceType = "local";

  #local: any;
  #session: any;
  #transient: any;

  get webPlatform() {
    return this.platform as IWebPlatform;
  }

  get storage(): ClientStorage {
    const mode = this.persistence;
    return mode === "local" ? this.localStorage : mode === "session" ? this.sessionStorage : this.transientStorage;
  }

  get storagePrefix() {
    return this.name || this.refId;
  }

  get localStorage() {
    this.#local ??= new ClientStorage("local", this.storagePrefix);
    return this.#local;
  }

  get sessionStorage() {
    this.#session ??= new ClientStorage("session", this.storagePrefix);
    return this.#session;
  }

  get transientStorage() {
    this.#transient ??= new ClientStorage("transient", this.storagePrefix);
    return this.#transient;
  }

  __defineStoredProperty(
    key,
    getter: (val: any, serv: this) => any = identity,
    setter: (val: any, prevGetter: () => any, serv: this) => any = identity
  ) {
    const get = () => getter(this.storage.get(key), this);
    Object.defineProperty(this, key, {
      get,
      set(val) {
        const r = typeof val !== "undefined" ? setter(val, get, this) : undefined;
        if (typeof r !== "undefined") {
          this.storage.set(key, r);
        }
      },
    });
  }

  async fetch(url: string, opts?: RequestInit): Promise<string> {
    const res = await globalThis.fetch(url, opts);
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${url}`);
    return res.text();
  }

  async fetchJson<T = any>(url: string, opts?: RequestInit): Promise<T> {
    const res = await globalThis.fetch(url, opts);
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${url}`);
    return res.json() as Promise<T>;
  }

  toast(entry: LogEntry) {
    this.emit("toaster.send()", entry);
  }

  clearStorage() {
    return ClientStorage.clearAll();
  }
}
