import { Component } from "arrmatura";
import { capitalize } from "ultimus";
import type { IndexedDbService } from "./IndexedDbService";

export class IndexedDbQuery extends Component {
  dbChange = 0;
  store = "";
  db?: IndexedDbService;

  constructor() {
    super();
    this.__defineCalculatedProperties({
      "data(db,value,store,index,limit,predicat,trigger,dbChange)": (db, value, store, index, limit, predicat) => {
        try {
          if (!db || !store || value == null) return null;

          const params = { value, store, index, limit, predicat };

          return db.query(params);
        } catch (error) {
          this.logError(error);

          return Promise.resolve(Object.assign([], { error }));
        }
      },
    });
  }

  __init() {
    if (this.db?.refId) {
      this.subscribeTo(this.db.refId, () => {
        this.up({
          dbChange: this.db?.[`trigger${capitalize((this.store || "items").toLowerCase())}`],
        });
      });
    }
  }
}
