import type { IElement } from "../types";

export function setEventListener($: IElement, key: string, value: (ev: any) => any, options: object | boolean = false) {
  const listeners = $.$listeners ?? ($.$listeners = new Set());
  if (!listeners.has(key)) {
    listeners.add(key);
    const [akey, ekey = akey] = key.split(":");
    $.$dom.addEventListener(ekey, value, options);
  }
}
