import { Component } from "arrmatura";
import type { Delta } from "ultimus";
import { arrayGroupBy, arraySortBy, objectFreeze } from "ultimus";
import type { Item } from "./Item";
import { showCounts } from "./utils";

export class ItemCollectionController extends Component {
  shownLimit = 50;

  // Reactive properties supplied by the framework (calculated props / up()).
  declare sortBy?: any;
  declare groupBy?: any;
  declare sortedData?: Item[] | null;

  constructor() {
    super();

    this.__defineCalculatedProperty(
      "sortedData",
      (data, sortBy) => {
        if (!data) return null;
        if (!sortBy) return data;
        return objectFreeze(arraySortBy(data, sortBy) as unknown as Item[]);
      },
      ["data", "sortBy"]
    );

    this.__defineCalculatedProperty(
      "groupedData",
      (data, groupBy) => {
        if (!data) return null;
        if (!groupBy) return data;
        return objectFreeze(Object.values(arrayGroupBy(data, groupBy)) as unknown as Item[]);
      },
      ["sortedData", "groupBy"]
    );

    this.__defineCalculatedProperty(
      "info",
      function (this: ItemCollectionController, groupedData, data, shownLimit = 50, isLoaded) {
        if (!groupedData || !isLoaded) {
          return { data: null, shownData: null, groupedData, countsInfo: "...", counts: {} };
        }
        const counts = {
          total: this.groupBy ? groupedData.length : data?.length,
          actual: groupedData.length,
          hasMore: shownLimit < groupedData.length,
        };
        return {
          isLoaded,
          sortByExpression: this.sortBy,
          groupBy: this.groupBy,

          data,
          sortedData: this.sortedData,
          groupedData,
          shownData: groupedData ? objectFreeze(groupedData.slice(0, shownLimit)) : null,

          counts: !isLoaded ? {} : counts,
          countsInfo: !isLoaded ? "..." : showCounts(counts),
        };
      },
      ["groupedData", "data", "shownLimit", "isLoaded"]
    );
  }

  onGroupBy({ value: groupBy = null }: Delta) {
    this.up({ groupBy });
  }

  showMore({ size = 50 }) {
    this.up({ shownLimit: this.shownLimit + size });
  }
}
