import { Component } from "arrmatura";
import type { Hash } from "ultimus";

export class MultiSelectController extends Component {
  _value?: string;
  _data?: any[];
  values = new Set<string>();

  isSelected = new Proxy(
    {},
    {
      get: (_target: any, prop: string) => {
        return this.values.has(`${prop}`);
      },
    }
  );

  disabled: any;

  declare onToggleItem?: (e: { id: string; isSelected: boolean }) => void;

  change(_data?: Hash) {
    // no-op
  }

  get enabled() {
    return !this.disabled;
  }

  get selectedIds() {
    return [...this.values.values()];
  }

  get selectedItems() {
    return this.data?.filter(({ id }) => this.values.has(id));
  }

  get canSelectAll() {
    return this.data?.length;
  }

  get selectedCount() {
    return this.values.size;
  }

  get isAllSelected() {
    return this.values.size === this.data?.length;
  }

  get data() {
    return this._data;
  }

  set data(data: any[] | undefined) {
    this._data = data;
    // if (data?.length && this.value !== undefined) {
    //   this.value = this.selectedItems?.map((e) => e.id).join(",") ?? "";
    // }
  }

  get value() {
    return this._value;
  }

  set value(value: string | undefined) {
    const hadValue = this.value !== undefined;
    this.values = new Set(value ? (Array.isArray(value) ? value : value.split(",")) : []);
    this._value = Array.isArray(value) ? value.join(",") : value;
    if (hadValue) {
      this.change?.({ value: this.selectedIds });
    }
  }

  async toggleSelection(id) {
    if (this.disabled) return;

    const isSelected = !this.values.has(id);
    if (isSelected) {
      this.values.add(id);
    } else {
      this.values.delete(id);
    }

    await this.onToggleItem?.({ id, isSelected });
    this.up({ value: this.selectedIds });
  }

  toggleAll() {
    if (this.disabled) return;

    const value = this.isAllSelected ? [] : this.data?.map((value) => value.id);

    this.up({ value });
  }
}
