import type { IPlatform } from "arrmatura";
import { Component } from "arrmatura";
import { defineObjectRef } from "ultimus";
import type { DomNode, IElement, IWebPlatform } from "../types";
import { attachToParent } from "../utils/attachToParent";

const SVGTAGS = ["svg", "path", "polygon", "g", "defs", "rect", "use", "text"]; // "lineargradient", "circle", "polygon", "rect", 'stop'
/**
 * DOM Element abstraction.
 */
export class DomElement extends Component implements IElement {
  declare readonly $dom: DomNode;
  declare readonly $changes: Map<string, any>;
  $listeners: any;

  [key: string]: unknown;

  constructor(tag: string, platform: IPlatform) {
    super();
    const node = (
      SVGTAGS.includes(tag)
        ? document.createElementNS("http://www.w3.org/2000/svg", tag)
        : document.createElement(!tag || tag === "script" ? "div" : tag)
    ) as DomNode;

    defineObjectRef(node, "component", this);
    defineObjectRef(this, "platform", platform);
    defineObjectRef(this, "$dom", node);
    defineObjectRef(this, "$changes", new Map<string, any>());
  }

  __init() {
    this.defer(() => {
      this.$dom.parentElement?.removeChild(this.$dom);
    });
  }

  __stateChanged(changes: Map<string, any>) {
    changes.forEach((value, key) => {
      if (key[0] === "$") return;
      this.$changes?.set(key, value);
    });
  }

  attachToParent(p: ShadowRoot | HTMLElement, before?: ChildNode | HTMLElement | null): DomNode {
    return attachToParent(this.$dom, p, before);
  }

  applyStateChanges() {
    const e = this.$dom;
    if (!this.$changes.size) return;
    this.$changes.forEach((value, key) => {
      if (key[0] === "$") return;
      if (value !== this[key]) {
        (this.platform as IWebPlatform).setElementAttribute(this, e, key, value);
        this[key] = value;
      }
    });
    this.$changes.clear();
  }

  click() {
    this.$dom.click();
  }
}
