import { assert, type Hash, parseJson } from "ultimus";
import { WebClientService } from "@/core";
import { invokeApiAction } from "./rest/api";
import { resolveEndpoints } from "./rest/endpoints";
import { firebaseAuthProvider } from "./rest/provider";
import { downloadUrlOf, objectMetadata, uploadObject } from "./rest/storage";
import type { AuthProvider, AuthSession, AuthUser, EmulatorPorts, FirebaseConfig, RestEndpoints } from "./rest/types";

/** Refresh this long before the id token actually expires, so an in-flight call never races it. */
const TOKEN_REFRESH_MARGIN = 60_000;

/** The account the Auth emulator signs in when no email is supplied. */
const DEFAULT_DEV_EMAIL = "dev@example.com";

type UserListener = (user: AuthUser | null) => void;

/**
 * Firebase client over plain REST — Identity Platform, Cloud Storage and the app's HTTPS `api`
 * function, with no `@firebase/*` SDK.
 *
 * What that buys and what it costs:
 * - The whole SDK (~640 KB minified) leaves every app bundle; esbuild does not code-split, so that
 *   weight was on the critical path of every page.
 * - Realtime Firestore listeners are gone. The Listen channel is gRPC/WebChannel and has no REST
 *   equivalent; anything that needs live documents has to go through the `api` function.
 * - Sign-in needs an OAuth web client id in the config (`googleClientId`) and the app's origins
 *   listed on that client. See {@link FirebaseConfig}.
 */
export class FirebaseService extends WebClientService {
  /** The console's `firebaseConfig` object, or its JSON text. */
  config!: FirebaseConfig | string;
  /** The `emulators` block of the app's `firebase.json`. */
  emulatorsPorts?: EmulatorPorts;

  fileStorageBase = "files";
  /** Email used for the emulator sign-in when `signIn()` is called without one. */
  devUserEmail = DEFAULT_DEV_EMAIL;

  /** Aborts an `api` call that has not answered in this long. */
  callableTimeout = 300_000;

  /** True while a sign-in popup or exchange is in flight. */
  busy = false;

  /** The signed-in account, or `null`. Mirrors `session.user` for templates. */
  user: AuthUser | null = null;

  /** Persisted so a reload resumes the session rather than re-prompting. */
  declare session: AuthSession | null;

  #endpoints?: RestEndpoints;
  #auth?: AuthProvider;
  #listeners = new Set<UserListener>();
  /** Single-flight guard: concurrent callers share one refresh rather than racing the token. */
  #refreshing: Promise<AuthSession | null> | null = null;

  constructor() {
    super();
    this.__defineStoredProperty("session", (value) => value ?? null);
  }

  __init() {
    const config: FirebaseConfig = typeof this.config === "string" ? parseJson(this.config) : this.config;
    assert(config?.apiKey && config?.projectId, "FirebaseService: config needs apiKey and projectId");

    const { fileStorageBase, authPersistence } = config;

    if (fileStorageBase) this.fileStorageBase = fileStorageBase;
    this.persistence = authPersistence || "local";

    this.#endpoints = resolveEndpoints(config, this.emulatorsPorts, window.location.hostname);

    this.#auth = this.createAuthProvider();

    // Warmed up now because `requestAccessToken` has to run inside the click that calls signIn();
    // awaiting the script there would break the user gesture and the popup would be blocked.
    this.#auth.warmUp?.().catch((error) => this.logError(error));

    this.defer(() => this.#listeners.clear());

    void this.restoreSession();
  }

  get endpoints(): RestEndpoints {
    return assert(this.#endpoints, "FirebaseService is not initialised");
  }

  get auth(): AuthProvider {
    return assert(this.#auth, "FirebaseService is not initialised");
  }

  /**
   * The one place that decides which identity provider is used — Google in production, the Auth
   * emulator locally. Everything below this line depends on {@link AuthProvider} only, so a
   * subclass can point the app at another IdP by overriding this and nothing else.
   */
  protected createAuthProvider(): AuthProvider {
    return firebaseAuthProvider(this.endpoints, {
      googleClientId: this.googleClientId,
      requestUri: window.location.origin,
    });
  }

  get googleClientId(): string | undefined {
    const config = typeof this.config === "string" ? parseJson(this.config) : this.config;
    return config?.googleClientId;
  }

  get isAuthorized() {
    return !!this.session?.refreshToken;
  }

  get currentUser(): AuthUser | null {
    return this.session?.user ?? null;
  }

  /** Subscribes to sign-in and sign-out. Returns the unsubscribe function. */
  listenUser(callback: UserListener) {
    this.#listeners.add(callback);
    return () => this.#listeners.delete(callback);
  }

  /** A valid id token, refreshed when it is close to expiry. `null` when signed out. */
  async tokenFactory(): Promise<string | null> {
    const session = this.session;
    if (!session?.refreshToken) return null;

    if (session.expiresAt - Date.now() > TOKEN_REFRESH_MARGIN) return session.idToken;

    const refreshed = await this.refreshSession();
    return refreshed?.idToken ?? null;
  }

  /** Opens the Google account chooser (or signs in to the emulator) and stores the session. */
  async signIn(data?: { email?: string }) {
    if (this.busy) return;
    this.up({ busy: true });

    try {
      this.applySession(await this.auth.signIn({ email: data?.email || this.devUserEmail }));
    } catch (error) {
      this.logError(error);
      this.up({ busy: false });
      this.toast({ id: "signIn", level: "error", message: String((error as Error)?.message ?? error) });
    }
  }

  /** Google has no separate sign-up: the first successful sign-in creates the account. */
  signUp(data?: { email?: string }) {
    return this.signIn(data);
  }

  /** Shaped for `<UserProfileModal>`, which reads `name` alongside the raw provider fields. */
  async loadUser() {
    const user = this.currentUser;
    return { data: { ...user, name: user?.displayName } as Hash };
  }

  async signOut() {
    this.up({ session: null, user: null });
    this.notify(null);

    try {
      await this.clearStorage();
    } catch (error) {
      this.logError(error);
    }

    window.location.reload();
  }

  /** Calls one action on the app's HTTPS `api` function. */
  async invokeApi(data: any) {
    return invokeApiAction(this.endpoints, {
      data,
      idToken: await this.tokenFactory(),
      timeoutMs: this.callableTimeout,
    });
  }

  async generateContent(request: { contents: { role: any; parts: { text: any }[] }[] }) {
    return this.invokeApi({ action: "generateContent", request });
  }

  /** Storage */

  async uploadFile({ value, file = value, fileName = file?.name, callback }: Hash) {
    assert(file, "Please select a file to upload.");

    try {
      const idToken = assert(await this.tokenFactory(), "You must be logged in to upload a file.");
      const path = `${this.fileStorageBase}/${fileName}`;

      const object = await uploadObject(this.endpoints, { path, file, idToken });
      // The v0 API calls the full path `name`; the SDK called it `fullPath`, and callers still do.
      const fullPath = object.name || path;
      const url = downloadUrlOf(this.endpoints, fullPath, object.downloadTokens);

      callback?.({ ...object, fullPath, value: url });

      return fullPath;
    } catch (error) {
      this.logError(error);
      callback?.({ error });
      throw error;
    }
  }

  async openFile(fullPath: string) {
    const url = await this.getFileDownloadUrl(fullPath);
    window.open(url, fullPath.replaceAll(/\W+/g, ""));
  }

  async getFileDownloadUrl(fullPath: string) {
    assert(fullPath, "Please select a file to download.");
    const idToken = assert(await this.tokenFactory(), "You must be logged in to download a file.");

    const object = await objectMetadata(this.endpoints, { path: fullPath, idToken });

    return downloadUrlOf(this.endpoints, fullPath, object.downloadTokens);
  }

  /** Session plumbing */

  /**
   * Resumes a stored session on start-up. A refresh token that Identity Platform no longer accepts
   * means the account was revoked or deleted, so the session is dropped rather than retried.
   */
  private async restoreSession() {
    const session = this.session;
    if (!session?.refreshToken) return;

    const current = session.expiresAt - Date.now() > TOKEN_REFRESH_MARGIN ? session : await this.refreshSession();
    if (!current) return;

    // A session written by an older build, or one whose profile never arrived, has no user yet.
    const user = current.user?.uid ? current.user : await this.auth.lookup(current.idToken);
    this.applySession({ ...current, user: user as AuthUser });
  }

  private async refreshSession(): Promise<AuthSession | null> {
    const session = this.session;
    if (!session?.refreshToken) return null;

    this.#refreshing ??= this.auth
      .refresh(session.refreshToken)
      .then((tokens) => {
        const next = { ...session, ...tokens };
        this.up({ session: next });
        return next;
      })
      .catch((error) => {
        this.logError(error);
        this.dropSession();
        return null;
      })
      .finally(() => {
        this.#refreshing = null;
      });

    return this.#refreshing;
  }

  private applySession(session: AuthSession) {
    this.up({ session, user: session.user, busy: false });
    this.notify(session.user);
  }

  /** Drops an unusable session without reloading — the guard components re-render to signed-out. */
  private dropSession() {
    this.up({ session: null, user: null, busy: false });
    this.notify(null);
  }

  private notify(user: AuthUser | null) {
    this.#listeners.forEach((listener) => listener(user));
    this.touch();
  }
}
