import type { ExpressionText } from "ultimus";
import type { ManifestNode } from "../core/ManifestNode";
import { splitTopLevel } from "../utils/splitTopLevel";
import { compilePlaceholder } from "./compilePlaceholder";

function compileSingleExpression(expr: ExpressionText, _node: ManifestNode) {
  if (expr.startsWith("@")) {
    expr = expr.slice(1);
  }
  const posEq = expr.indexOf("=");
  const posLParen = expr.indexOf("(");
  if (posEq > 0 && (posLParen === -1 || posEq < posLParen)) {
    const key = expr.slice(0, posEq).trim();

    expr = expr.slice(posEq + 1).replaceAll(/@(\w+)\.(\w+)/g, (_, ref, pkey) => {
      return `$RefProp('${ref}', '${pkey}')`;
    });

    const exprFn = compilePlaceholder(expr).functor;
    return (c) => (data) => c.scope?.emit(key, exprFn(c, data));
  }

  if (posLParen > 0) {
    const key = `${expr.slice(0, posLParen)}()`;
    let argExpr = expr.slice(posLParen + 1, -1).trim();
    argExpr = argExpr.replaceAll(/@(\w+)\.(\w+)/g, (_, ref, pkey) => `$RefProp('${ref}', '${pkey}')`);

    if (!argExpr) {
      return (c) => (data) => c.scope?.emit(key, data);
    }

    const argFns = splitTopLevel(argExpr, ",").map((a) => compilePlaceholder(a).functor);
    return (c) => (data) => c.scope?.emit(key, ...argFns.map((fn) => fn(c, data)));
  }

  expr = expr.trim();

  return (c) => (data) => c.scope?.emit(expr, data);
}

export function compileEmitterExpression(expr: ExpressionText, node: ManifestNode) {
  const statements = splitTopLevel(expr, ";").filter(Boolean);

  if (statements.length <= 1) {
    return compileSingleExpression(statements[0] ?? expr, node);
  }

  const fns = statements.map((stmt) => compileSingleExpression(stmt, node));
  return (c) => async (data: unknown) => {
    for (const fn of fns) {
      await fn(c)(data);
    }
  };
}
