import type { XmlNode } from "ultimus";
import { Arrmatron } from "../core/Arrmatron";
import { ManifestNode } from "../core/ManifestNode";

export class Block extends Arrmatron<CBlockNode> {
  get displayName(): string {
    return `💠${this.manifest.tag}`;
  }

  get contentManifests() {
    const nodes = (this.get("Nodes") ?? []) as XmlNode[];
    return this.platform.getCompiledNodes(nodes);
  }
}

export class CBlockNode extends ManifestNode {
  constructor({ id, attrs }: XmlNode) {
    super(id + (attrs?.Ref ? `:${attrs?.Ref}` : ""));
    this.compileAttributes(attrs);
  }

  get EntitronConstructor() {
    return Block;
  }
}
