import { requestJson } from "./http";
import type { RestEndpoints } from "./types";

/**
 * Calls the app's HTTPS `api` function.
 *
 * The wire format is the callable protocol — `{ data }` in, `{ data: { ok, result, error } }` out —
 * because `createHttpApiCallHandler` speaks it deliberately (it is an `onRequest`, not an
 * `onCall`). Reproducing it here is a POST with a bearer token.
 */
export async function invokeApiAction(
  endpoints: RestEndpoints,
  { data, idToken, timeoutMs }: { data: any; idToken?: string | null; timeoutMs?: number }
): Promise<any> {
  const response = await requestJson<{ data?: { ok?: boolean; result?: any; error?: any } }>(endpoints.api, {
    headers: {
      "Content-Type": "application/json",
      ...(idToken ? { Authorization: `Bearer ${idToken}` } : {}),
    },
    body: { data },
    timeoutMs,
  });

  const { result, error } = response?.data ?? {};

  // A handled failure can still arrive with a 2xx status, so the body is checked either way.
  if (error) throw new Error(error.message, { cause: error });

  return result;
}
