import { Component } from "arrmatura";
import type { Datum, Hash } from "ultimus";
import { filterByKeyword } from "ultimus";

export class TagsValueController extends Component {
  #value?: string;
  values: string[] = [];
  categoryValue?: string;
  kliuq?: string;
  prefixValue = "";
  options: Datum[] = [];
  optionsMap?: Map<string, Datum>;
  disabled: any;
  multi: any;

  change(_data?: Hash) {
    // no-op
  }

  get evaluatedOptions() {
    return [
      ...this.orphanedValues,
      ...(this.options?.map?.(({ id, name = id, type }) => ({
        id,
        isSelected: this.values?.includes(id),
        name,
        type,
      })) ?? []),
    ];
  }

  get selectedOptions() {
    const options = this.evaluatedOptions;
    return this.values?.length ? options.filter(({ isSelected }) => isSelected) : [];
  }

  get orphanedValues() {
    return (
      this.values
        ?.filter((v) => !this.options?.some((vv) => vv.id == v))
        .map((id) => ({
          id,
          name: `'${id}'`,
          isSelected: true,
          isOrphaned: true,
          isErroneous: true,
        })) ?? []
    );
  }

  get availableOptions() {
    let options = this.evaluatedOptions;
    if (this.values?.length) {
      options = options.filter(({ isSelected }) => !isSelected);
    }
    if (this.kliuq) {
      options = filterByKeyword(options, this.kliuq);
    }
    return options;
  }

  get value() {
    return this.#value;
  }

  set value(value: string | undefined) {
    const hadValue = this.value !== undefined;
    if (this.value !== value) {
      this.#value = value;
      this.values = this.value
        ? String(this.value)
            .split(",")
            .map((s) => s.trim())
            .filter(Boolean)
        : [];
      if (hadValue) {
        this.change({ value });
      }
    }
  }

  doToggle({ value = "", ...extra }) {
    if (this.disabled) return;

    let val = this.values.filter((e) => e !== value);
    if (val.length === this.values.length) {
      val.unshift(value);
    }
    if (!this.multi) {
      val = val.slice(0, 1);
    }
    this.up({ value: val.join(","), ...extra });
  }

  doKliuq({ value = "" }) {
    if (this.disabled) return;

    this.up({ kliuq: String(value ?? "") });
  }

  doToggleAndClearKliuq(datum: Hash) {
    if (this.disabled) return;
    this.doToggle({ ...datum, kliuq: "" });
  }

  doReset() {
    if (this.disabled) return;

    this.up({ value: "", kliuq: "" });
  }
}
