import { defineObjectHashCodeProperty, hashCodeOf } from "./hashCodeOf";

/**
 * Freezes an object and memoizes its content hash under `HASH_SYMBOL` (enables O(1) `isEquals`).
 *
 * Non-objects and already-frozen values are returned as-is. Array elements are frozen recursively,
 * but plain-object property values are NOT deep-frozen (top level only).
 */
export const objectFreeze = <T>(e: T): T => {
  if (!e || typeof e !== "object") return e;
  if (Object.isFrozen(e)) return e;
  if (Array.isArray(e)) {
    for (const item of e) objectFreeze(item);
  }
  return Object.freeze(defineObjectHashCodeProperty(e, hashCodeOf(e))) as T;
};
