/**
 * Checks whether a value is empty.
 *
 * - Falsy values (`null`, `undefined`, `0`, `""`, `false`, `NaN`) are empty.
 * - Arrays are empty at length 0; Map/Set at size 0; Date at epoch time 0.
 * - Other objects are empty when they have no own enumerable keys.
 * - Any other truthy value is not empty.
 */
export const isEmpty = (x: unknown): boolean => {
  if (!x) {
    return true;
  }
  if (typeof x === "object") {
    if (Array.isArray(x)) {
      return x.length === 0;
    }
    if (x instanceof Map || x instanceof Set) {
      return x.size === 0;
    }
    if (x instanceof Date) {
      return x.getTime() === 0;
    }
    return Object.keys(x).length === 0;
  }
  return false;
};
