/** Date captured at module load; supplies the default timezone offset for `dateParseISO8601`. */
export const SAMPLE = new Date();

const ISO8601_RE = /^(\d\d\d\d)-(\d\d)-(\d\d)[ T](\d\d):(\d\d)(?::(\d\d)(\.\d\d\d?)?)?(Z?)(([+-])(\d\d):?(\d\d)?)?/;

/**
 * Parses an ISO 8601 date/date-time string into a Date.
 *
 * Date-only strings ("yyyy-MM-dd") are interpreted as noon UTC. Strings without a timezone suffix
 * are interpreted using `TZ` (minutes behind UTC, defaults to the local offset at module load).
 *
 * @param TZ - Timezone offset in minutes (as `Date#getTimezoneOffset()`) applied when the string has no zone info.
 * @returns Parsed Date, or null when the string is empty, malformed, or has a "00" month or day.
 */
export function dateParseISO8601(x: string, TZ = SAMPLE.getTimezoneOffset()): Date | null {
  if (!x) {
    return null;
  }
  if (x.length === 10) {
    x += "T12:00Z";
  }
  const m = ISO8601_RE.exec(x);
  if (!m || m[2] === "00" || m[3] === "00") {
    return null;
  }
  // milliseconds since the epoch, ignoring the timezone
  const localMillis = Date.UTC(
    parseInt(m[1], 10),
    parseInt(m[2], 10) - 1,
    parseInt(m[3], 10),
    parseInt(m[4], 10),
    parseInt(m[5], 10),
    m[6] ? parseInt(m[6], 10) : 0,
    m[7] ? parseInt(m[7].slice(1), 10) : 0
  );

  // offset of the parsed wall-clock time relative to UTC, in minutes
  const localOffset =
    m[8] === "Z"
      ? 0
      : !m[9]
        ? -TZ
        : (m[10] === "-" ? -1 : +1) * (parseInt(m[11], 10) * 60 + (m[12] ? parseInt(m[12], 10) : 0));

  return new Date(localMillis - localOffset * 60000);
}
