import { gettusFn } from "../object/gettus";
import { strHead, strTail } from "../string";
import type { Obj } from "../types";

/**
 * Builds a tree from a flat list of parent-linked items (items are shallow-copied; the input is not mutated).
 *
 * Items whose parent id is missing from the list are collected under a synthetic "???" node.
 *
 * @param options.fieldsIds - link spec "parentKey>idKey"; a bare "parentKey" keeps id key "id"
 *   (defaults: "parent" and "id")
 * @param options.childPropertyName - property that receives child items (default "items")
 * @returns `{ [childPropertyName]: topLevelItems, index }` where `index` maps ids to the copied nodes
 * @example
 * arrayToTree([{ id: "a" }, { id: "b", parent: "a" }]).items // [{ id: "a", items: [{ id: "b", ... }] }]
 */
export function arrayToTree<T extends Obj>(list: T[] | null, { fieldsIds = "", childPropertyName = "items" } = {}) {
  if (!list) return { [childPropertyName]: [], index: {} };

  const top: T[] = [];

  const hasSep = fieldsIds?.includes(">");
  const idKey = (hasSep ? strTail(fieldsIds, ">") : null) || "id";
  const parentKey = (fieldsIds ? (hasSep ? strHead(fieldsIds, ">") : fieldsIds) : null) || "parent";

  const getId = gettusFn(idKey);
  const getParentId = gettusFn(parentKey);

  const index: Record<string, any> = Object.fromEntries(list.map((e) => [String(getId(e)), { ...(e as any) }]));
  const getItemById = (id: unknown) => (id ? index[String(id)] : null);
  let unknownParent: any = getItemById("???");

  list.forEach((e: T) => {
    const item = getItemById(getId(e));
    if (!item) return;

    const pId = getParentId(item);

    const parent = getItemById(pId);

    if (parent) {
      (parent[childPropertyName] ?? (parent[childPropertyName] = [])).push(item);
      return;
    }

    if (pId) {
      if (!unknownParent) {
        unknownParent = { [idKey]: "???", [childPropertyName]: [] };
        top.push(unknownParent as unknown as T);
        index["???"] = unknownParent;
      }
      item.parent2 = pId;
      item.parent = "???";
      (unknownParent[childPropertyName] ?? (unknownParent[childPropertyName] = [])).push(item);
      return;
    }

    top.push(item);
  });

  return { [childPropertyName]: top, index };
}
