import { Component } from "arrmatura";
import { SpeechService } from "@/modules/speech/src/SpeechService";

export class TextareaVoiceController extends Component {
  value = "";
  onChange: ((e: { value: string }) => void) | null = null;
  speechService: SpeechService | null = null;
  isRecording = false;
  voiceText = "";
  language = "en-US";

  __init() {
    this.speechService = new SpeechService();
    this.speechService.language = this.language;

    this.up({ isRecording: false, voiceText: "" });
  }

  async startRecording() {
    if (!this.speechService) return;

    this.up({ isRecording: true, voiceText: "" });

    await this.speechService.startRecognition((voiceText: string) => {
      this.up({ voiceText });
    });

    // Recording can also end on its own — a lost microphone, or a long enough silence.
    // Drop the recording state either way, so the button never lies about the mic.
    this.up({ isRecording: false });
  }

  stopRecording() {
    if (!this.speechService) return;

    this.speechService.stopRecognition();
    this.up({ isRecording: false });
  }

  applyVoiceInput() {
    if (!this.speechService) return;

    const recognizedText = this.speechService.getRecognizedText();
    if (recognizedText && this.onChange) {
      const newValue = this.value ? `${this.value} ${recognizedText}` : recognizedText;
      this.onChange({ value: newValue });
    }
    this.stopRecording();

    this.clearVoiceInput();
  }

  clearVoiceInput() {
    if (this.speechService) {
      this.speechService.recognizedText = "";
      this.speechService.interimText = "";
    }
    this.up({ voiceText: "" });
  }
}
