import type { Token, Tokens } from "marked";
import { CONTAINER_TAGS } from "./tags";

export function groupHtmlContainers(tokens: Token[]): Token[] {
  const result: Token[] = [];
  let i = 0;
  while (i < tokens.length) {
    const token = tokens[i];
    if (token.type === "html") {
      const text = (token as Tokens.HTML).text;
      const openMatch = text.match(/^<(\w+)[\s\n>]/);
      const tag = openMatch?.[1]?.toLowerCase() ?? "";
      if (CONTAINER_TAGS.has(tag)) {
        const closingTag = `</${tag}>`;
        const innerTokens: Token[] = [];
        i++;
        while (i < tokens.length) {
          const t = tokens[i] as any;
          if (t.type === "html" && t.text.trim().toLowerCase() === closingTag) {
            i++;
            break;
          }
          innerTokens.push(tokens[i]);
          i++;
        }
        result.push({ type: "htmlContainer", tag, openingHtml: text, tokens: innerTokens } as unknown as Token);
        continue;
      } else {
        result.push(token);
        i++;
        continue;
      }
    }
    result.push(token);
    i++;
  }
  return result;
}
