import { Component } from "arrmatura";
import type { Delta, Hash, StringHash } from "ultimus";
import { arraySortBy, mapEntries, objectFreeze } from "ultimus";

import type { Item } from "./Item";

export const getSuggestionsIndex = (data: Item[], searchFields: string) => {
  const index: Hash = {};
  data.forEach((e) => {
    const w = String(e[searchFields] || "").toLowerCase();
    index[w] = (index[w] ?? 0) + 1;
  });

  return arraySortBy(
    mapEntries(index, (id, count) => ({ name: `${id}`, id, count })),
    "name"
  );
};
export const getSearchKeySuggestions = (index: Item[], kluq: string = "") => {
  if (!kluq || kluq.length < 3) return [];

  const lokey = kluq.toLowerCase();

  return index.filter((e: Item) => e.id?.startsWith(lokey));
};

export class ItemSearchController extends Component {
  kluqPoshuku = "";

  _data?: any[] | null = null;

  searchKey = "";
  searchFields = "name";

  constructor() {
    super();

    this.__defineCalculatedProperty(
      "suggestions",
      (suggestionsIndex, searchKey) => {
        if (!suggestionsIndex) return null;
        if (!searchKey || searchKey.length < 3) return suggestionsIndex;
        return getSearchKeySuggestions(suggestionsIndex, searchKey);
      },
      ["suggestionsIndex", "searchKey"]
    );
    this.__defineCalculatedProperty(
      "suggestionsIndex",
      (data, searchFields) => {
        if (!data) return null;
        return getSuggestionsIndex(data, searchFields || "name");
      },
      ["data", "searchFields"]
    );
    this.__defineCalculatedProperty(
      "actualData",
      (data, kluqPoshuku, searchFields) => {
        if (!data) return null;
        if (!kluqPoshuku) return data;
        if (!searchFields) return data;
        const lokey = kluqPoshuku.toLowerCase();
        return objectFreeze(
          data.filter((e) => {
            const w = String(e[searchFields] || "").toLowerCase();
            return w.startsWith(lokey);
          })
        );
      },
      ["data", "kluqPoshuku", "searchFields"]
    );
  }

  get data() {
    return this._data;
  }

  set data(data: any[] | null | undefined) {
    this._data = !data ? null : Array.isArray(data) ? data : Object.values(data);
  }

  // event handlers:

  inputKluq({ value }: Delta) {
    this.up({ searchKey: value || "" });
  }

  znajdzPoKluqu({ value }: StringHash) {
    this.up({ searchKey: value || "", kluqPoshuku: value || "" });
  }
}
