import { marked, type Token, type Tokens } from "marked";
import { stringHashCode, stringify, urlParse, type XmlNode, xmlParse } from "ultimus";
import { HEADING_CLS } from "../consts";
import type { Attrs, HtmlContainerToken } from "../types";
import { type DefinitionListToken, definitionListExtension } from "./definitionList";
import { escapeText, wrapText } from "./escapeText";
import { groupHtmlContainers } from "./groupHtmlContainers";
import { highlight } from "./highlight";
import { CONTAINER_TAGS, HTML_BLOCK_TAGS } from "./tags";

const COLLAPSIBLE_LEVELS = new Set([1, 2, 3]);
export { CONTAINER_TAGS };

// Configure marked to use GFM and handle custom XML block tags.
marked.use({
  gfm: true,
  breaks: false,
  pedantic: false,
  extensions: [
    definitionListExtension,
    {
      name: "xmlBlock",
      level: "block" as const,
      start(src: string) {
        return src.indexOf("<");
      },
      tokenizer(src: string): Tokens.HTML | undefined {
        // Match a self-contained single-line custom XML tag: <tag ...>content</tag>
        // Content must not contain '<' or newlines (avoids swallowing nested markup).
        const match = /^<([a-z][a-z0-9-.]*)(\s[^>]*)?>([^<\n]*)<\/\1>[ \t]*\n?/i.exec(src);
        if (match && !HTML_BLOCK_TAGS.has(match[1].toLowerCase())) {
          return { type: "html", raw: match[0], text: match[0].trimEnd(), pre: false, block: true };
        }
        return undefined;
      },
    },
  ],
});
// ── public ────────────────────────────────────────────────────────────────────

export function markdownToNodes(md: string, prefix = "MD", mdKey = ""): XmlNode[] {
  if (!md) return [];

  let _uid = 0;
  const uid = () => String(++_uid);
  const el = (tag: string, attrs?: Attrs, nodes?: XmlNode[]): XmlNode => ({
    tag,
    id: uid(),
    ...(attrs ? { attrs } : {}),
    ...(nodes ? { nodes } : {}),
  });
  const txt = (text: string): XmlNode => ({
    tag: "span",
    id: uid(),
    text: escapeText(text),
  });

  // ── inline ────────────────────────────────────────────────────────────────────

  function inlineTokens(tokens: Token[]): XmlNode[] {
    return tokens.flatMap((t): XmlNode[] => {
      switch (t.type) {
        case "text": {
          const tt = t as Tokens.Text;
          return tt.tokens ? inlineTokens(tt.tokens) : expandQuoted(tt.text);
        }
        case "strong":
          return [
            el("strong", { class: "inline-block bg-base-300 rounded-xs mx-1 px-1" }, [
              el("span", {}, inlineTokens((t as Tokens.Strong).tokens ?? [])),
            ]),
          ];
        case "em":
          return [
            el("i", { class: "inline-block bg-base-200 rounded-xs mx-1 px-1" }, [
              el("span", {}, inlineTokens((t as Tokens.Em).tokens ?? [])),
            ]),
          ];
        case "codespan":
          return [el("MDCodespan", { text: escapeText((t as Tokens.Codespan).text) })];
        case "link": {
          const { href, text, raw } = t as Tokens.Link;
          const { host, path, schema } = urlParse(href);
          const [fileName, fileExt] = path.at(-1)?.split(".") ?? ["", ""];
          return [el(`MDLink`, { href, text: escapeText(text), raw, uid: uid(), fileName, fileExt, host, schema })];
        }
        case "image": {
          const { href, text, title } = t as Tokens.Image;
          return [el("MDImage", { src: href, alt: escapeText(text), title: title ?? "", uid: uid() })];
        }
        case "escape":
          return [el(`MDEscape`, { uid: uid(), text: escapeText((t as Tokens.Escape).text) })];
        // A hard line break — a trailing backslash or two trailing spaces. Without this
        // case the token falls through and the break is dropped, which is how a glossary
        // definition and the aside under it used to run together on one line.
        case "br":
          return [el("br")];
        default:
          return [];
      }
    });
  }

  // Preserves the custom "quoted text" inline pattern from the original processInline
  function expandQuoted(text: string): XmlNode[] {
    const result: XmlNode[] = [];
    const re = /"([^"]+)"/g;
    let last = 0;
    let m: RegExpExecArray | null;
    while ((m = re.exec(text)) !== null) {
      if (m.index > last) result.push(txt(text.slice(last, m.index)));
      result.push(el("strong", { class: "inline-block bg-base-300 mx-1 px-1" }, [txt(m[1] ?? m[2])]));
      last = m.index + m[0].length;
    }
    if (last < text.length) result.push(txt(text.slice(last)));
    return result.length > 0 ? result : [txt(text)];
  }

  // ── list ──────────────────────────────────────────────────────────────────────

  function listItem(item: Tokens.ListItem, depth: number, prefix: string = ""): XmlNode {
    const nested = item.tokens?.find((t) => t.type === "list") as Tokens.List | undefined;
    const textToken = item.tokens?.find((t) => t.type === "text") as Tokens.Text | undefined;
    const children = textToken?.tokens ? inlineTokens(textToken.tokens) : [txt(item.text)];
    const key = stringHashCode(stringify(children)) + prefix;

    if (item.task) {
      const checkboxEl = el(`MDCheckbox`, {
        checked: item.checked || null,
        key,
      });

      return el("li", { class: `flex items-center` }, [
        checkboxEl,
        el("span", {}, children),
        ...(nested ? [list(nested, depth + 1, prefix + String(depth + 1))] : []),
      ]);
    }

    return el("li", {}, [el("span", {}, children), ...(nested ? [list(nested, depth + 1)] : [])]);
  }

  function list(token: Tokens.List, depth: number, prefix?: string): XmlNode {
    const tag = `MD${token.items[0]?.task ? "Task" : ""}${token.ordered ? "Ordered" : ""}List`;
    return el(
      tag,
      { depth },
      token.items.map((item) => listItem(item, depth, prefix || String(uid())))
    );
  }

  // ── definition list ───────────────────────────────────────────────────────────

  function definitionList(token: DefinitionListToken): XmlNode {
    return el(
      "dl",
      { class: "my-4 text-sm" },
      token.entries.flatMap(({ term, definitions }) => [
        el("dt", { class: "font-semibold text-base-content mt-4 first:mt-0" }, inlineTokens(term)),
        ...definitions.map((blocks) =>
          el("dd", { class: "ml-4 mb-1 leading-relaxed text-base-content/80" }, definitionBody(blocks))
        ),
      ])
    );
  }

  /** A one-paragraph definition renders inline, so a plain term/definition pair stays
   *  tight instead of gaining a paragraph's margins. Anything longer keeps its blocks. */
  function definitionBody(blocks: Token[]): XmlNode[] {
    if (blocks.length === 1 && blocks[0].type === "paragraph") {
      return inlineTokens((blocks[0] as Tokens.Paragraph).tokens ?? []);
    }
    return blockTokens(blocks, { sectionCounter: 1, hasFirstH1: true });
  }

  // ── block ─────────────────────────────────────────────────────────────────────

  function blockTokens(tokens: Token[], state: { sectionCounter: number; hasFirstH1: boolean }): XmlNode[] {
    const result: XmlNode[] = [];
    const sectionStack: Array<{ level: number; childNodes: XmlNode[] }> = [];

    const target = (): XmlNode[] =>
      sectionStack.length > 0 ? sectionStack[sectionStack.length - 1].childNodes : result;

    for (const token of tokens) {
      switch (token.type) {
        case "heading": {
          const { depth: level, tokens: iTokens = [] } = token as Tokens.Heading;
          if (COLLAPSIBLE_LEVELS.has(level)) {
            while (sectionStack.length > 0 && sectionStack[sectionStack.length - 1].level >= level) {
              sectionStack.pop();
            }
            const childNodes: XmlNode[] = [el("span", { Slot: "title" }, inlineTokens(iTokens))];
            const sectionKey = `section-${mdKey}+${state.sectionCounter++}`;
            const section: XmlNode = {
              tag: `MDSection.${prefix}`,
              id: sectionKey,
              attrs: {
                ...(state.hasFirstH1 ? {} : { open: "true" }),
                key: sectionKey,
                level,
                class: HEADING_CLS[level],
              },
              nodes: childNodes,
            };
            target().push(section);
            sectionStack.push({ level, childNodes });
            if (level === 1) state.hasFirstH1 = true;
          } else {
            target().push(el(`h${level}`, { class: HEADING_CLS[level] }, inlineTokens(iTokens)));
          }
          break;
        }
        case "paragraph":
          target().push(
            el("p", { class: "my-2 leading-relaxed text-sm" }, inlineTokens((token as Tokens.Paragraph).tokens ?? []))
          );
          break;
        case "code": {
          const { text, lang = "" } = token as Tokens.Code;
          if (lang === "mermaid") {
            const diagramId = `mermaid-${prefix}-${uid()}`;
            target().push(el("MDMermaid", { diagramId, plain: wrapText(text) }));
            break;
          }
          target().push(el(`MDCode.${lang}`, { lang }, highlight(text, lang)));
          break;
        }
        case "blockquote":
          target().push(
            el(
              "MDBlockQuote",
              {},
              blockTokens((token as Tokens.Blockquote).tokens ?? [], { sectionCounter: 1, hasFirstH1: false })
            )
          );
          break;
        case "hr":
          target().push(el("hr", { class: "border-base-300 my-6" }));
          break;
        case "table": {
          const t = token as Tokens.Table;
          const thead = el("thead", {}, [
            el(
              "tr",
              {},
              t.header.map((h) => el("th", { class: "font-semibold" }, inlineTokens(h.tokens ?? [])))
            ),
          ]);
          const rows = t.rows.map((row) =>
            el(
              "tr",
              {},
              row.map((cell) => el("td", {}, inlineTokens(cell.tokens ?? [])))
            )
          );
          target().push(
            el("div", { class: "overflow-x-auto my-4" }, [
              el("table", { class: "table table-sm w-full text-sm" }, [thead, ...rows]),
            ])
          );
          break;
        }
        case "list":
          target().push(list(token as Tokens.List, 0));
          break;
        case "defList":
          target().push(definitionList(token as unknown as DefinitionListToken));
          break;
        case "html": {
          const node = xmlParse(token.text.trim())[0];

          target().push(node);
          break;
        }
        case "htmlContainer": {
          const ct = token as unknown as HtmlContainerToken;
          const childNodes = blockTokens(ct.tokens, { sectionCounter: 0, hasFirstH1: false });
          if (ct.tag === "details") {
            const summaryMatch = ct.openingHtml.match(/<summary>([\s\S]*?)<\/summary>/i);
            const summaryText = summaryMatch?.[1]?.trim() ?? "";
            target().push(el("MDDetails", { summary: summaryText }, [...childNodes]));
          } else {
            // For self-contained tags (<quiz>24</quiz>), surface inner text as `value` attr.
            const innerMatch = ct.openingHtml.match(new RegExp(`^<${ct.tag}[^>]*>([^<]*)<\\/${ct.tag}>`, "i"));
            const value = innerMatch?.[1]?.trim();
            target().push(el(ct.tag, value ? { value } : {}, childNodes));
          }
          break;
        }
        case "space":
          break;
        default:
        // target().push(txt(`Unsupported token type: ${token.type}`));
      }
    }
    return result;
  }

  return blockTokens(groupHtmlContainers(marked.lexer(md)), { sectionCounter: 1, hasFirstH1: false });
}
