import { stringSplit } from "../string";
import { arrayJoin } from "./arrayJoin";

/**
 * Adds `id` to the collection if absent, removes it if present. Accepts an array (returns a new array)
 * or a separated string (returns a string); falsy `id` returns the input unchanged.
 */
export function arrayToggleElement(items: string | any[], id: any, sep?: string) {
  if (!id) return items;

  if (typeof items === "string") {
    return arrayJoin(arrayToggleElement(stringSplit(items, sep), id), sep);
  }

  if (!items) return items;

  if (items.includes(id)) {
    return items.filter((e) => e !== id);
  }
  return [...items, id];
}
