import { type Datum, type Delta, type Hash, hashCodeOf, type Uid, type XmlNode } from "ultimus";
import { Arrmatron } from "../core/Arrmatron";
import { ManifestNode } from "../core/ManifestNode";
import type { EContent, IArrmatron, IManifestNode, IPlatform } from "../types";
import { narrowData } from "../utils/narrowData";

class Iterative extends Arrmatron<CForNode> {
  pkHash: Hash<Datum> = {};

  get displayName(): string {
    return `🟪each:${this.manifest.itemName}`;
  }

  get eachList() {
    return (this.$component as unknown as { each: unknown }).each;
  }

  get contentManifests() {
    const each = narrowData(this.eachList);
    const itemNode = this.manifest.getItemCtxNode(this.platform);
    const nodes: Map<Uid, IManifestNode> = new Map();
    // Reset and repopulate the shared pkHash in place. Resolvers attached on prior
    // renders close over `this.pkHash` (the Iterative), so they read the current
    // datum on each render — this is how mutations to existing items propagate
    // to reused child arrmatrons. Do NOT close over `datum` directly.
    this.pkHash = {};

    each.forEach((datum: Datum) => {
      const pk = String(datum.id || hashCodeOf(datum));
      if (this.pkHash[pk]) {
        this.logError(`ERROR: duplicate item id : ${pk} (skipped)`, datum);
        return;
      }

      this.pkHash[pk] = datum;

      const inode = itemNode.cloneWithDatum(datum, this.platform);

      inode.propertyResolvers.push((_c: IArrmatron, delta: Delta) => {
        delta[itemNode.itemName] = this.pkHash[pk];
        return delta;
      });

      nodes.set(inode.uid, inode);
    });

    return nodes;
  }
}

export class CForNode extends ManifestNode {
  #itemNode?: CItemNode;
  itemName: string;
  #xmlNode: XmlNode;
  constructor(xmlNode: XmlNode, itemName: string, exprValue: string) {
    super(xmlNode.id);
    this.#xmlNode = xmlNode;
    this.itemName = itemName;
    this.bindExpression(exprValue, (v) => ({ each: v }));
  }

  getItemCtxNode(platform: IPlatform) {
    return (
      this.#itemNode ??
      (this.#itemNode = new CItemNode(this.#xmlNode.id, this.itemName, platform.getCompiledNodes([this.#xmlNode])))
    );
  }

  get EntitronConstructor() {
    return Iterative;
  }
}

class IterativeItem extends Arrmatron<CItemNode> {
  get scopeForChildren(): Arrmatron {
    return this;
  }

  get displayName(): string {
    return `🟪each:item:${this.manifest.itemName}`;
  }

  emit(key: string, ...args: any[]) {
    return this.scope.emit(key, ...args);
  }

  get(propId: string) {
    const iName: string = this.manifest.itemName;
    const value = propId.startsWith(`${iName}.`) || propId === iName ? super.get(propId) : this.scope.get(propId);
    return value;
  }
}

class CItemNode extends ManifestNode {
  itemName: string;
  constructor(id: string, itemName: string, content?: EContent) {
    super(id);
    this.itemName = itemName;
    this.$content = content;
  }

  cloneWithDatum(datum: Datum, platform: IPlatform) {
    const uid = `${String(this.uid)}#${datum.id || hashCodeOf(datum)}`;
    const c = new CItemNode(uid, this.itemName, this.getSubNodes(platform));
    c.uid = uid;
    return c;
  }

  get EntitronConstructor() {
    return IterativeItem;
  }
}
