import type { Token, TokenizerAndRendererExtension } from "marked";

/**
 * Definition lists, the extended-markdown syntax `marked` does not implement.
 *
 *     Solution
 *     : An artificial phenomenon a Team designs for someone outside it
 *
 * Without this, the pair is one paragraph and the colon is printed as text. The rules
 * below are pandoc's, because the same documents are rendered to EPUB and PDF by
 * pandoc and the two must agree on what a definition contains:
 *
 * - a term is a bare line whose successor is a definition line — nothing else marks it,
 *   so a heading, a list item or a table row is excluded explicitly;
 * - a definition runs from its `:` marker to the next blank line, and a non-blank line
 *   below it is folded in, which is how a trailing `\` gives a line break;
 * - a block indented by four spaces stays inside the definition, so a definition can
 *   hold a list or a second paragraph;
 * - one term may carry several `:` definitions.
 */

const MARKER_RE = /^:[ \t]+(.*)$/;
const INDENT_RE = /^(?: {4}|\t)/;
// Anything that opens a block of its own is not a term — a list item, a quote, a table
// row, a heading, an indented line, or a code fence whose first line happens to start
// with a colon.
const NOT_A_TERM_RE = /^(\s|[-*+>|#]|\d+\.|```|~~~)/;

const isBlank = (line: string) => !line.trim();

const isTerm = (lines: string[], at: number) =>
  at + 1 < lines.length &&
  !isBlank(lines[at]) &&
  !NOT_A_TERM_RE.test(lines[at]) &&
  !MARKER_RE.test(lines[at]) &&
  MARKER_RE.test(lines[at + 1]);

/** Read one `:`-marked definition, returning its body lines and the line after it. */
function readDefinition(lines: string[], start: number): { body: string[]; next: number } {
  const body = [lines[start].replace(MARKER_RE, "$1")];
  let at = start + 1;

  while (at < lines.length) {
    if (isBlank(lines[at])) {
      // A blank line belongs to the definition only if an indented block follows it;
      // otherwise the definition — and possibly the list — ends here.
      let ahead = at;
      while (ahead < lines.length && isBlank(lines[ahead])) ahead += 1;
      if (ahead >= lines.length || !INDENT_RE.test(lines[ahead])) break;
      for (; at < ahead; at += 1) body.push("");
      continue;
    }
    if (INDENT_RE.test(lines[at])) {
      body.push(lines[at].replace(INDENT_RE, ""));
      at += 1;
      continue;
    }
    if (MARKER_RE.test(lines[at])) break;
    body.push(lines[at].trim()); // lazy continuation of the definition's first paragraph
    at += 1;
  }

  return { body, next: at };
}

export interface DefinitionEntry {
  term: Token[];
  definitions: Token[][];
}

export interface DefinitionListToken {
  type: "defList";
  raw: string;
  entries: DefinitionEntry[];
}

export const definitionListExtension: TokenizerAndRendererExtension = {
  name: "defList",
  level: "block",

  // Where a paragraph must be cut short for a definition list to begin. This has to be
  // the offset of the term's own line: a match found part-way into a line would cut it
  // there, and the tail of a table row or a list item reads as a term once its opening
  // marker has been sliced off.
  start(src: string) {
    const lines = src.split("\n");
    let offset = 0;
    for (let at = 0; at < lines.length; at += 1) {
      if (isTerm(lines, at)) return offset;
      offset += lines[at].length + 1;
    }
    return undefined;
  },

  tokenizer(src: string) {
    const lines = src.split("\n");
    if (!isTerm(lines, 0)) return undefined;

    const entries: DefinitionEntry[] = [];
    let at = 0;

    while (isTerm(lines, at)) {
      const term = this.lexer.inlineTokens(lines[at].trim());
      const definitions: Token[][] = [];
      at += 1;

      while (at < lines.length && MARKER_RE.test(lines[at])) {
        const { body, next } = readDefinition(lines, at);
        definitions.push(this.lexer.blockTokens(body.join("\n").trim()));
        at = next;
      }
      entries.push({ term, definitions });

      // One blank line between entries is the normal shape; skip it and carry on only
      // if another entry follows, so trailing blank lines stay outside `raw`.
      let ahead = at;
      while (ahead < lines.length && isBlank(lines[ahead])) ahead += 1;
      if (!isTerm(lines, ahead)) break;
      at = ahead;
    }

    const raw = lines.slice(0, at).join("\n") + (at < lines.length ? "\n" : "");
    return { type: "defList", raw, entries } as DefinitionListToken;
  },
};
