import { Expression } from "./Expression";
import { ExpressionParser } from "./ExpressionParser";

export function compilePlaceholder(expr: string) {
  const ctx = new Expression();
  try {
    const top = new ExpressionParser(expr, ctx).parse();
    ctx.functor = top.fn;
  } catch (error) {
    console.error(`Expression: ${expr}`, error);
    throw error;
  }
  return ctx;
}
