import { gettus } from "../object";
import type { Data, Hash, Predicat } from "../types";

/**
 * Compiles an atomic predicate: a field truthiness check or a (in)equality comparison.
 */
const compileAtom = (s: string): Predicat<Data> => {
  const trimmed = s.trim();
  let tokens = trimmed.match(/^[\w.]+$/);
  if (tokens) {
    const [key] = tokens;
    return (d, ctx) => !!(gettus(d, key) ?? gettus(ctx, key));
  }
  // Comparison: key=value or key!=value (quoted or unquoted values, comma-separated for IN)
  tokens = trimmed.match(/^([\w.]+)\s*(!?)==?\s*(?:'([^']*)'|([\w,а-яА-Я]+))$/);
  if (tokens) {
    const [, key, neg, quotedVal, unquotedVal] = tokens;
    const values = (quotedVal ?? unquotedVal).split(",");
    const fn: Predicat<Data> = (d, ctx) => values.includes(String(gettus(d, key) ?? gettus(ctx, key)));
    return neg ? (d, ctx) => !!(gettus(d, key) ?? gettus(ctx, key)) && !fn(d, ctx) : fn;
  }

  // Fallback: plain property truthiness check
  return (d) => !!d[trimmed];
};

/**
 * Tokenizes a predicate expression into operators, parens, and atoms.
 */
const tokenize = (input: string): string[] => {
  const result: string[] = [];
  let i = 0;

  while (i < input.length) {
    // Skip whitespace
    while (i < input.length && /\s/.test(input[i])) i++;
    if (i >= input.length) break;

    const c = input[i];
    const c2 = input.slice(i, i + 2);

    // Check for operators and parens
    if (c2 === "||" || c2 === "&&") {
      result.push(c2);
      i += 2;
    } else if (c === "(" || c === ")") {
      result.push(c);
      i++;
    } else if (c === "!" && input[i + 1] !== "=") {
      // NOT operator (but not !=)
      result.push("!");
      i++;
    } else {
      // Try to match a comparison expression: key [!]= 'value'
      const compMatch = input.slice(i).match(/^([\w.]+)\s*(!?==?)\s*'([^']*)'/);
      if (compMatch) {
        const [, key, op, val] = compMatch;
        result.push(`${key}${op}'${val}'`);
        i += compMatch[0].length;
      } else {
        // Atom - collect until we hit an operator, paren, or whitespace
        let atom = "";
        while (i < input.length) {
          const cc = input[i];
          const cc2 = input.slice(i, i + 2);

          if (/\s/.test(cc) || cc === "(" || cc === ")" || cc2 === "||" || cc2 === "&&") {
            break;
          }
          // Handle ! - only break if it's NOT operator (not part of !=)
          if (cc === "!" && input[i + 1] !== "=") {
            break;
          }

          atom += cc;
          i++;
        }
        if (atom) {
          result.push(atom);
        }
      }
    }
  }

  return result;
};

/**
 * Recursive descent parser for predicate expressions
 *
 * Precedence (lowest to highest):
 * 1. OR (||)
 * 2. AND (&&)
 * 3. NOT (!)
 * 4. Atoms and parentheses
 */
class PredicatParser {
  private tokens: string[];
  private pos = 0;

  constructor(input: string) {
    this.tokens = tokenize(input);
  }

  private peek(): string | undefined {
    return this.tokens[this.pos];
  }

  private consume(): string {
    return this.tokens[this.pos++];
  }

  /** Parse OR expressions (lowest precedence) */
  private parseOr(): Predicat<Data> {
    let left = this.parseAnd();

    while (this.peek() === "||") {
      this.consume();
      const right = this.parseAnd();
      const leftFn = left;
      left = (d, ctx) => leftFn(d, ctx) || right(d, ctx);
    }

    return left;
  }

  /** Parse AND expressions */
  private parseAnd(): Predicat<Data> {
    let left = this.parseUnary();

    while (this.peek() === "&&") {
      this.consume();
      const right = this.parseUnary();
      const leftFn = left;
      left = (d, ctx) => leftFn(d, ctx) && right(d, ctx);
    }

    return left;
  }

  /** Parse unary NOT expressions */
  private parseUnary(): Predicat<Data> {
    if (this.peek() === "!") {
      this.consume();
      const expr = this.parseUnary();
      return (d, ctx) => !expr(d, ctx);
    }
    return this.parsePrimary();
  }

  /** Parse atoms and parenthesized expressions (highest precedence) */
  private parsePrimary(): Predicat<Data> {
    if (this.peek() === "(") {
      this.consume();
      const expr = this.parseOr();
      if (this.peek() === ")") {
        this.consume();
      }
      return expr;
    }

    const atom = this.consume();
    return atom ? compileAtom(atom) : () => false;
  }

  parse(): Predicat<Data> {
    if (this.tokens.length === 0) {
      return () => false;
    }
    return this.parseOr();
  }
}

const compilePredicat = (s: string | boolean): Predicat<Data> => {
  if (!s || s === "FALSE" || s === "false") return () => false;
  if (s === "ALWAYS" || s === "TRUE" || s === "true" || s === true) return () => true;

  return new PredicatParser(String(s)).parse();
};

const PREDICATS: Hash<Predicat<Data>> = {};

/**
 * Returns a cached predicate function compiled from a string expression.
 *
 * Supports field truthiness (`isActive`), negation (`!x`, `!(expr)`), equality (`status=active`),
 * inequality (`status!=active`), IN checks (`role=admin,editor`), `&&`, `||`, and parentheses.
 * Dotted paths (`user.role`) are resolved on the data argument first, then on the optional context.
 * `TRUE`/`true`/`ALWAYS`/boolean `true` always match; empty/`FALSE`/`false` never match.
 * @example getPredicat("isActive && (role=admin || role=editor)")({ isActive: true, role: "admin" }) // true
 */
export const getPredicat = (s: string | boolean = ""): Predicat<Data> =>
  PREDICATS[String(s)] || (PREDICATS[String(s)] = compilePredicat(s));
