import { assert } from "../func/fx";

/** Options for {@link loadJson}: standard `fetch` init plus a required `url`; `body` may be any JSON value. */
export type LoadJsonOptions = Omit<RequestInit, "body"> & {
  url: string;
  body?: unknown;
};

/**
 * Fetches a URL and resolves with the parsed JSON response.
 *
 * - Method defaults to `post` when a body is given, `get` otherwise; a `get` never sends a body.
 * - Object bodies are JSON-stringified; string bodies pass through unchanged.
 * - Rejects on non-2xx status, and rejects with `res.error` when the JSON payload carries a truthy `error` field.
 * - Deliberately sets NO default `Content-Type` header (some endpoints, e.g. Google Apps Script, reject
 *   preflighted requests); callers must supply their own via `headers` when needed.
 *
 * @param arg a URL string (plain GET) or a {@link LoadJsonOptions} object
 */
export function loadJson<T = any>(arg: string | LoadJsonOptions): Promise<T> {
  const { url, body = null, method = body ? "post" : "get", ...opts } = typeof arg === "string" ? { url: arg } : arg;
  assert(url, "url is required");
  const rawBody = body && typeof body === "object" ? JSON.stringify(body) : ((body as BodyInit | null) ?? null);
  return fetch(url, {
    method,
    mode: "cors",
    redirect: "follow",
    body: method === "get" ? undefined : rawBody,
    ...opts,
    headers: {
      ...opts.headers,
    },
  })
    .then(async (res) => {
      if (!res.ok) {
        throw new Error(`HTTP ${res.status} ${res.statusText} for ${url}`);
      }
      return (await res.json()) as T;
    })
    .then((res) => {
      if (res && typeof res === "object" && (res as { error?: unknown }).error)
        throw (res as { error?: unknown }).error;
      return res;
    });
}
