import { Component } from "arrmatura";
import type { FilterField } from "./FilterField";
import type { ItemsFilterController } from "./ItemsFilterController";

export class FilterFieldHistogram extends Component {
  trigger = 0;
  fieldId?: FilterField;
  ctrl?: ItemsFilterController;

  constructor() {
    super();

    this.__defineCalculatedProperty(
      `data`,
      (fieldId, ctrl) => ctrl.fields.find((ff) => ff.id === fieldId)?.histogram ?? null,
      ["fieldId", "ctrl", "trigger"]
    );
  }

  __init() {
    if (this.ctrl?.refId) {
      this.subscribeTo(this.ctrl.refId, () => {
        this.up({
          trigger: this.trigger + 1,
        });
      });
    }
  }
}
