import type { Url } from "../types";

import { parseQueryString } from "./parseQueryString";

/**
 * Parses a URL string into its components: schema, host, path segments, query params and hash.
 * The host is only extracted from `//host/...` forms; `+` is treated as a space in query and hash.
 *
 * @example urlParse("https://ex.com/a?x=1#top")
 * // { schema: "https", host: "ex.com", path: ["a"], params: { x: 1 }, hash: "top" }
 */
export const urlParse = (x: string): Url => {
  const r: Url = { path: [], params: {}, host: "" };
  if (!x) {
    return r;
  }
  let p: number;
  let s = String(x);
  // extract hash:
  p = s.indexOf("#");
  if (p > -1) {
    r.hash = decodeURIComponent(s.slice(p + 1).replace(/\+/g, " "));
    s = s.slice(0, p);
  }
  // extract query params (apply +→space only here, not on path):
  p = s.indexOf("?");
  if (p > -1) {
    parseQueryString(s.slice(p + 1).replace(/\+/g, " "), r.params);
    s = s.slice(0, p);
  }
  // extract schema:
  p = s.indexOf(":");
  if (p > -1) {
    r.schema = s.slice(0, p);
    s = s.slice(p + 1);
  }

  // host and path:
  r.path = s.split("/").map(decodeURIComponent);
  if (r.path.length > 2 && !r.path[0] && !r.path[1]) {
    r.path.shift();
    r.path.shift();
    r.host = r.path.shift() ?? "";
  }

  return r;
};
