import { Component } from "arrmatura";
import { arraySortBy } from "ultimus";
import { speak } from "@/core";
import { SpeechListener } from "./SpeechListener";

/**
 * Speech API.
 * @see https://developer.mozilla.org/en-US/docs/Web/API/SpeechSynthesis/speak
 * @see https://developer.mozilla.org/en-US/docs/Web/API/SpeechRecognition
 */
export class SpeechService extends Component {
  voices = window.speechSynthesis.getVoices();
  voicesList = arraySortBy(
    this.voices.map((e, id) => ({
      ...e,
      id,
      name: `${e.name} (${e.lang})`,
      language: e.lang,
      voice: e,
    })),
    "name"
  );

  defaultVoice = this.voices.find((e) => e.default) ?? this.voices[0] ?? { lang: "en-US", name: "English" };
  currentVoice = this.defaultVoice;
  language = this.defaultVoice.lang?.slice(0, 2) ?? "en";

  // Speech recognition properties
  isRecognizing = false;
  recognizedText = "";
  interimText = "";

  /** Called back with the live text — set for the duration of one recording. */
  private onVoiceText: ((voiceText: string) => void) | null = null;

  /**
   * Owns the microphone. One recording is one open-ended attempt: it accumulates
   * across pauses and ends only on `stopRecognition()`, an error, or the recognizer
   * stopping on its own — restarting between utterances would drop dictated words.
   */
  private readonly listener = new SpeechListener({
    lang: () => this.language,
    untilStopped: true,
    interimResults: true,
    onHeard: ({ text, confirmed, interim }) => {
      this.recognizedText = confirmed;
      this.interimText = interim;
      this.onVoiceText?.(text);
      this._up({ isRecognizing: this.isRecognizing, recognizedText: confirmed, interimText: interim });
    },
    onError: (code) => {
      if (code) console.error("Speech recognition error:", code);
    },
  });

  protected _up(d: any) {
    if (this.$$) this.up(d);
  }

  /** Record until `stopRecognition()`; `callback` receives the text as it comes in. */
  async startRecognition(callback?: (voiceText: string) => void) {
    if (this.isRecognizing) return;

    this.onVoiceText = callback ?? null;
    this.recognizedText = "";
    this.interimText = "";
    this.isRecognizing = true;
    this._up({ isRecognizing: true, recognizedText: "", interimText: "" });

    await this.listener.listen();

    // A stop may already have started the next recording — leave that one alone.
    if (this.listener.isListening) return;
    this.onVoiceText = null;
    this.isRecognizing = false;
    this.interimText = "";
    this._up({ isRecognizing: false, interimText: "" });
  }

  stopRecognition() {
    if (!this.isRecognizing) return;
    this.isRecognizing = false;
    this._up({ isRecognizing: false });
    this.listener.abort();
  }

  getRecognizedText() {
    return this.recognizedText.trim();
  }

  textToSpeech({ text, ...options }: any) {
    speak(text, options);
  }

  get currentVoices() {
    return this.voicesList.filter((e) => e.language.startsWith(this.language));
  }

  get voice() {
    return this.currentVoice;
  }
  get voiceId() {
    return this.voice.lang;
  }

  set voiceId(voiceId) {
    this.currentVoice = this.voicesList.find((e) => e.lang === voiceId) ?? this.defaultVoice;
  }
}
