import { hashCodeOf, type XmlNode } from "ultimus";
import { WebClientService } from "@/core";
import { markdownToNodes } from "./utils/markdownToNodes";
import { parseFrontmatter } from "./utils/parseFrontmatter";

/**
 * MarkdownViewService — converts Markdown to a component node tree and injects it as a dynamic component.
 * The tree is wrapped in a single `MDDocument` node carrying the frontmatter as attributes.
 */
export class MarkdownViewService extends WebClientService {
  #text: string = "";
  prefix: string = "";
  key: string = "";

  set text(text: string) {
    this.#text = text;
    this._load(this.#text);
  }

  private _load(text: string) {
    try {
      const { attrs, body } = parseFrontmatter(text);
      const mdKey = this.key || hashCodeOf(body);
      const document: XmlNode = {
        tag: "MDDocument",
        id: mdKey,
        attrs: attrs as XmlNode["attrs"],
        nodes: markdownToNodes(body, this.prefix || "MD", mdKey),
      };
      this.up({ mdKey, attrs, nodes: [document] });
    } catch (err) {
      this.up({ loading: false, error: String(err), nodes: null });
    }
  }
}
