import { type Fn, loadJson, stringSplit } from "ultimus";

export const initialDataFactory = async ({ name, initialData, initialUrl }: any, bundleApplicator: Fn) => {
  if (initialData) {
    await bundleApplicator(typeof initialData === "function" ? await initialData() : initialData);
  }

  const urls = stringSplit(initialUrl, ";");
  const bundles = await Promise.all(urls.map((url) => loadJson({ url }).then((data) => ({ url, data }))));
  for (const { url, data } of bundles) {
    await bundleApplicator(data);
    console.log(`loaded db ${name} bundle from: ${url}`);
  }
};
