const RE_ESCAPE_XML_ENTITY = /["'&<>]/g;

const RE_XML_ENTITY = /&#?[0-9a-zA-Z]{2,5};/g;

const SUBST_XML_ENTITY: Record<string, string> = {
  amp: "&",
  gt: ">",
  lt: "<",
  quot: '"',
  nbsp: " ",
};

const ESCAPE_XML_ENTITY: Record<string, string> = {
  34: "&quot;",
  38: "&amp;",
  39: "&#39;",
  60: "&lt;",
  62: "&gt;",
};
const FN_ESCAPE_XML_ENTITY = (m: string) => ESCAPE_XML_ENTITY[m.charCodeAt(0)];

const FN_XML_ENTITY = (s0: string) => {
  const s = s0.slice(1, -1);
  if (s[0] !== "#") return SUBST_XML_ENTITY[s] || " ";
  const rest = s.slice(1);
  const code = rest[0] === "x" || rest[0] === "X" ? parseInt(rest.slice(1), 16) : parseInt(rest, 10);
  return Number.isFinite(code) ? String.fromCharCode(code) : " ";
};

/** HTML tags that must always be rendered with an explicit closing tag. */
export const htmlDoubleTags = ["script", "title", "iframe", "body", "div", "span", "p", "a"];

/**
 * Strips a matching pair of surrounding quote characters, if present.
 *
 * @param sym expected opening character (default `"`)
 * @param sym2 expected closing character (defaults to sym)
 */
export const skipQuotes = (s: string, sym = '"', sym2 = sym) =>
  s[0] === sym && s[s.length - 1] === sym2 ? s.slice(1, -1) : s;

/**
 * Decodes XML entities (`&amp;`, `&#65;`, `&#x41;`, ...) in a string;
 * unrecognized named entities of 2-5 characters become a space.
 */
export const decodeXmlEntities = (s?: string) => String(s ?? "").replaceAll(RE_XML_ENTITY, FN_XML_ENTITY);

/** Escapes the XML special characters `& < > " '` for safe use in text or attribute values. */
export const escapeXml = (s?: string) => (!s ? "" : `${s}`.replaceAll(RE_ESCAPE_XML_ENTITY, FN_ESCAPE_XML_ENTITY));
