import { mapEntries } from "../object";
import { stringSplit } from "../string";

/**
 * Normalizes arbitrary input into a list of `{ id, name }`-shaped items.
 *
 * Accepts a comma-separated string (underscores in names become spaces), an array of strings/objects,
 * any iterable, a plain object (entries become items keyed by `id`), or a scalar; nullish input yields [].
 */
export const narrowItemList = (data: any) => {
  if (!data) {
    return [];
  }
  if (typeof data === "string") return stringSplit(data).map((id) => ({ id, name: id.replaceAll("_", " ") }));
  if (Array.isArray(data))
    return data.map((e) => (typeof e === "string" ? { id: e, name: e } : { ...e, id: String(e.id ?? "") }));
  if (typeof data[Symbol.iterator] === "function") return [...data];
  if (typeof data === "object")
    return mapEntries(data, (key, value) =>
      typeof value === "object" ? { ...value, id: key } : { id: key, name: String(value) }
    );
  return [{ id: String(data), name: String(data) }];
};
