/**
 * 32-bit FNV-1a hash of a string, returned as an 8-digit lowercase hex string.
 *
 * Reference: http://isthe.com/chongo/tech/comp/fnv/
 *
 * @param seed - Initial hash value; defaults to the FNV-1a 32-bit offset basis.
 */
export function stringHashFNV1a(str: string, seed = 0x811c9dc5): string {
  let hval = seed;
  for (let i = 0, l = str.length; i < l; i++) {
    hval ^= str.charCodeAt(i);
    hval += (hval << 1) + (hval << 4) + (hval << 7) + (hval << 8) + (hval << 24);
  }
  return `0000000${(hval >>> 0).toString(16)}`.slice(-8);
}

/**
 * 64-bit string hash as a 16-digit hex string: FNV-1a of the input concatenated
 * with FNV-1a of (first hash + input).
 */
export function stringHash(str: string, seed?: number): string {
  const h1 = stringHashFNV1a(str, seed);
  return h1 + stringHashFNV1a(h1 + str, seed);
}
