export const runTransaction = ({
  db,
  store,
  index = "",
  oncomplete = (_r: any) => {},
  onerror = (_error: any) => {},
  mode = "readwrite",
  durability = "relaxed",
  fn,
}): void => {
  try {
    const stores = (typeof store === "string" ? [store] : store).filter((id) => db.objectStoreNames.contains(id));

    if (!stores.length) {
      throw new Error(`Unexisting IndexDB store: ${store}`);
    }

    const tx = db.transaction(stores, mode, { durability });

    tx.oncomplete = oncomplete;
    tx.onerror = onerror;

    stores.forEach((storeId) => {
      try {
        const store: IDBObjectStore = tx.objectStore(storeId);
        const datasource: IDBObjectStore | IDBIndex = index ? store.index(index) : store;
        const rx = fn(datasource, onerror);
        if (rx) {
          if (Array.isArray(rx)) {
            rx.forEach((rrx) => {
              rrx.onerror = onerror;
            });
          } else {
            rx.onerror = onerror;
          }
        }
        if (mode === "readwrite") {
          // tx.commit?.();
        }
      } catch (error: any) {
        console.error("IDB Transaction: store=", storeId, "index=", index, error.message);
        onerror(error);
      }
    });
  } catch (error) {
    console.error("IDB Transaction", error);
    onerror(error);
  }
};
