import { debounce } from "ultimus";
import type { DomNode, IElement } from "@/core";
import { findParentElement, WebClientService } from "@/core";

const PORTAL_ID = "dropdownsPortal";
const ENTER_MS = 140;
const SLIDE_PX = 6;

/** Opacity + slide only: a scaling transform would change the measured size the position sync reads back. */
const shownFrame = { opacity: 1, transform: "translateY(0)" };
const hiddenFrame = (flippedUp: boolean) => ({
  opacity: 0,
  transform: `translateY(${flippedUp ? SLIDE_PX : -SLIDE_PX}px)`,
});

const isFlippedUp = (element: DomNode) => element.dataset.dropdownFlip === "up";
const prefersReducedMotion = () => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true;

function getPortal(): HTMLElement {
  let portal = document.body.children.namedItem(PORTAL_ID) as HTMLElement | null;
  if (!portal) {
    portal = document.createElement("div");
    portal.setAttribute("id", PORTAL_ID);
    document.body.appendChild(portal);
  }
  portal.classList.add("absolute");
  return portal;
}

let currentDropdown: IElement | null;
function syncDropdownPosition() {
  if (!currentDropdown) return true;

  const parent = currentDropdown.originalParent as DomNode;
  const element = currentDropdown.$dom;
  if (!parent?.isConnected || !element?.isConnected) {
    currentDropdown.dropdown?.();
    currentDropdown = null;
    return;
  }

  const popStyle = element.style;

  const { x, y, height: hp } = parent.getBoundingClientRect();

  const { width: ww, height: hh } = element.getBoundingClientRect();
  const { width: w00 } = window.document.body.getBoundingClientRect();
  const w0 = Math.min(w00, window.document.body.clientWidth);
  const h0 = window.innerHeight; //Math.max(h00, );

  const flippedUp = y + hp + hh + 0 > h0;
  element.dataset.dropdownFlip = flippedUp ? "up" : "down";
  popStyle.top = flippedUp ? `${Math.max(0, y - hh - 5)}px` : `${y + hp + 4}px`;
  if (ww <= w0) {
    //&& w0 > 375
    popStyle.left = `${Math.max(0, Math.min(x, w00 - ww - 5))}px`;
  } else {
    popStyle.left = `4px`;
    popStyle.right = `4px`;
    popStyle.width = `${w0 - 8}px`;
    popStyle.maxWidth = `${w0 - 8}px`;
    // popStyle.top = `${Math.max(0, (Math.max(420, h0) - Math.max(40, hh)) / 2)}px`;
  }
  popStyle.position = "fixed";
  popStyle.zIndex = "100";

  setTimeout(() => requestAnimationFrame(syncDropdownPosition), 10);
}

/** Fades the panel in once it has been placed by the first position sync. */
function animateIn(element: DomNode) {
  if (prefersReducedMotion()) return;
  element.animate([hiddenFrame(isFlippedUp(element)), shownFrame], { duration: ENTER_MS, easing: "ease-out" });
}

const dropdown = ($: IElement, element: DomNode): void => {
  if ($.dropdown) return;

  $.attachToParent = (parent) => {
    let attached = false;
    try {
      const portal = getPortal();
      if (portal === element.parentElement) return;
      // if (currentDropdown?.$.uid === $.$.uid) return;

      currentDropdown = $;
      currentDropdown.originalParent = parent;

      const popStyle = element.style;
      popStyle.position = "relative";
      popStyle.left = "-10000px";
      popStyle.top = "-10000px";
      popStyle.display = "flex";

      element.parentElement?.removeChild(element);
      portal.appendChild(element);
      attached = true;
    } finally {
      syncDropdownPosition();
      if (attached) animateIn(element);
    }
  };
};

function autoCloseCurrentDropdownOnClickOutside(event) {
  if (!currentDropdown) return true;

  const target = event.target;
  const inDropdown = findParentElement(target, (p: any) => p === currentDropdown?.$dom);
  if (!inDropdown) {
    // close
    currentDropdown.dropdown?.();
    currentDropdown = null;
  }
}

export class DropdownsPlugin extends WebClientService {
  __init() {
    this.webPlatform.addElementAttributeSetters({ dropdown });

    const handler = debounce(autoCloseCurrentDropdownOnClickOutside, 10);
    document.addEventListener("touchstart", handler, { capture: true });
    document.addEventListener("mousedown", handler, { capture: true });
    this.defer(() => {
      document.removeEventListener("touchstart", handler, { capture: true });
      document.removeEventListener("mousedown", handler, { capture: true });
    });
  }
}
