import type { Op } from "ultimus";
import { WebClientService } from "@/core";

export class StoredData extends WebClientService {
  action?: Op;
  defaults = null;
  data: any = null;
  __opened = false;

  constructor() {
    super();

    this.__defineStoredProperty(
      "data",
      (v, serv) => (v == null ? serv.defaults : v),
      (value, _, serv) => {
        if (!serv.__opened) return;
        return value;
      }
    );
  }

  assign(key, value) {
    this.up({ data: typeof key === "object" ? { ...this.data, ...key } : { ...this.data, [key]: value } });
  }

  toggle(key) {
    this.up({ data: { ...this.data, [key]: !this.data?.[key] } });
  }

  reset() {
    this.up({ data: null });
  }

  __getStateProperty(propName: string) {
    switch (propName) {
      case "name":
      case "action":
      case "defaults":
      case "persistence":
      case "assign":
      case "toggle":
      case "reset":
      case "data":
        return this[propName];
      default:
        return this.data?.[propName];
    }
  }

  __stateChanged(changes: Map<string, any>) {
    changes.forEach((value, propName) => {
      switch (propName) {
        case "persistence":
        case "action":
        case "defaults":
        case "data":
          this[propName] = value;
          return;
        default:
          this.data = { ...this.data, [propName]: value };
          return;
      }
    });
  }

  __init() {
    this.action?.(this.data);
    this.__opened = true;
  }
}
