import { launch } from "arrmatura";
import * as lib from "ultimus";
import { assert } from "ultimus";
import type { WebAppOptions } from "./types";
import { WebPlatform } from "./WebPlatform";

/**
 * Creates an instance of the "App" component and launch it on Web Platform.
 *
 * @param template: Specifies the markup with root component of the application, default is <App />.
 * @param types: An array of component templates, in this case, the contents of the templates.xml file.
 * @param resources: An object that contains the static data used in the application.
 * @param functions: An object that contains functions that can be used in component templates.
 * @returns root node
 */
export function launchWebApp(config?: WebAppOptions) {
  const {
    rootElement,
    resources = {},
    functions: $functions,
    components = [],
    template = "<App/>",
    Platform = WebPlatform,
  } = config ?? (window as WebAppOptions);

  const functions = { launchWebApp, ...lib, ...resources?.functions, ...$functions };

  functions.callFunction = (name: string, ...args: any[]) => {
    const fn = functions[name];
    if (typeof fn === "function") {
      return fn(...args);
    } else {
      console.warn(`Function ${name} not found in functions object.`);
    }
  };

  const rootElt = assert(
    rootElement
      ? typeof rootElement === "string"
        ? document.getElementById(rootElement)
        : rootElement
      : document.getElementById("app") || window.document.body,
    "Root element not found"
  );

  const platform = new Platform(rootElt, {
    ...resources,
    functions,
    components,
  });

  const top = launch(platform, template);

  const onBeforeUnload = () => top.done();
  window.addEventListener("beforeunload", onBeforeUnload, { once: true });

  return top;
}
