import type { Fn, Obj } from "../types";

/**
 * Writes a value into an object by key spec, mutating and returning the object.
 *
 * - function key: called as `key(o, value)`; its result is ignored.
 * - `"a.b.c"` or `["a", "b", "c"]`: sets the leaf, creating missing intermediate objects.
 * - No-op (returns `o` unchanged) when `o` is not an object or `key` is falsy.
 */
export const settus = (
  o: Obj,
  key: Fn | string | string[] | ((e: Obj, v: unknown) => unknown),
  value: unknown
): Obj => {
  if (!o || !key || typeof o !== "object") return o;

  if (typeof key === "function") {
    key(o, value);
  } else {
    const parts = typeof key === "string" ? key.split(".") : key.slice();
    const last = parts.pop();
    const target = parts.length ? parts.reduce<object>((r, seg) => r[seg] ?? (r[seg] = {}), o) : o;
    if (last && target && typeof target === "object") {
      target[last] = value;
    }
  }
  return o;
};
