export class Heartbeat {
  watcher?: () => unknown;
  interval: any;

  constructor(
    watcher?: () => unknown,
    readonly intervalTime = 1000
  ) {
    this.setWatcher(watcher);
  }

  setWatcher(watcher?: () => unknown) {
    this.watcher = watcher;
  }

  startWatch() {
    this.interval ||= setInterval(() => {
      this.watcher?.();
    }, this.intervalTime);
  }

  stopWatch() {
    if (this.interval) {
      clearInterval(this.interval);
      this.interval = 0;
    }
  }

  setActive(active: boolean) {
    if (!active) {
      this.stopWatch();
    } else {
      this.startWatch();
    }
  }
}
