import { arrayGroupBy } from "./arrayGroupBy";
import { arraySortBy } from "./arraySortBy";

/**
 * Merges items sharing the same `field` value into one object; later items (per `priorityOrder`, ascending)
 * overwrite earlier ones. Nullish input is returned as-is.
 *
 * @param priorityOrder - sort key used to decide overwrite order within a duplicate group (default: `ts`)
 * @example
 * arrayMergeDuplicates([{ name: "a", v: 1, ts: 1 }, { name: "a", v: 2, ts: 2 }])
 * // => [{ name: "a", v: 2, ts: 2 }]
 */
export function arrayMergeDuplicates<T extends object>(
  list: T[] | null | undefined,
  field = "name",
  priorityOrder: (e: T) => string | number = (e) => String((e as { ts?: unknown }).ts || 0)
) {
  if (!list) return list;

  const groupedByName = arrayGroupBy(list, field);
  return Object.values(groupedByName).map((group) =>
    group.items.length === 1 ? group.items[0] : Object.assign({}, ...arraySortBy(group.items, priorityOrder))
  );
}
