import { arrayToObject, type Hash } from "ultimus";

export class OrderedListTransaction {
  changes: Hash = {};
  head?: Hash;
  listMap: Record<string, Hash>;

  constructor(private readonly data?: Hash[] | null) {
    this.head = data?.find((e) => e._first);
    // Ensure there's a head and build _next chain.
    if (!this.head && data?.length) {
      let prev: Hash | undefined;
      for (const node of data) {
        if (prev) {
          this.setNextOf(prev, node.id);
        } else {
          this.setHead(node);
        }
        prev = node;
      }
    }
    this.listMap = arrayToObject(data);
  }

  setNextOf = (node, value?: string) => {
    node._next = value;
    this.changes[node.id] = { ...(this.changes[node.id] || {}), _next: value ?? null };
    return value;
  };

  setHead = (nodeId) => {
    if (!nodeId) return;

    if (this.head) {
      this.head._first = null;
      this.changes[this.head.id] = { ...(this.changes[this.head.id] || {}), _first: null };
    }

    this.head = this.listMap[nodeId];
    if (this.head) {
      this.head._first = true;
      this.changes[this.head.id] = { ...(this.changes[this.head.id] || {}), _first: true };
    }
    return this.head;
  };

  findPrev(fromId: string) {
    if (!this.data?.length || !this.head) return null;

    let current = this.head;
    let prev: Hash | null = null;

    while (current?.id !== fromId && current?._next != null) {
      prev = current;
      current = this.listMap[String(current._next)];
    }
    return prev;
  }

  /**
   * Reorder item with fromId to the position before toId
   */
  reorderItems({ fromId, toId }: { fromId: string; toId: string }) {
    if (fromId === toId || !this.data?.length) return;

    if (!this.head) return;

    const fromNode = this.listMap[fromId];
    if (!fromNode) return;

    if (!this.listMap[toId]) return;

    // === Remove from current position ===
    let prev: Hash | null = this.findPrev(fromId);
    const nextId = fromNode?._next;

    // Update previous node or head
    if (prev === null) {
      // fromNode is the head
      if (nextId != null) {
        this.setHead(String(nextId));
      }
    } else {
      this.setNextOf(prev, nextId);
    }

    // === Insert before toId ===
    if (this.head.id === toId) {
      // Insert at beginning
      this.setNextOf(fromNode, this.head.id);
      this.setHead(fromId);

      return this.changes;
    }

    // Otherwise, find node before `toId`
    prev = this.findPrev(toId);
    if (prev) {
      this.setNextOf(prev, fromId);
    }

    this.setNextOf(fromNode, toId);

    return this.changes;
  }
}
