import type { Hash } from "../types";

/** Full English month names, 1-based (index 0 is an empty string). */
export const monthNames = [
  "",
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

/** Abbreviated English month names, 1-based (index 0 is an empty string). */
export const monthNamesShort = ["", "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

/** Full English day names, indexed by `Date#getDay()` (0 = Sunday). */
export const dayNames = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

/** Two-digit day-of-month labels: "01".."31". */
export const monthDaysNames = Array.from({ length: 31 }, (_, i) => pad(i + 1));

/** Two-letter English day names, indexed by `Date#getDay()` (0 = Sunday). */
export const dayNamesShort = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

function pad(x: number) {
  const s = String(x);
  return s.length < 2 ? `0${s}` : s;
}

/**
 * Formats a timezone offset in minutes (as returned by `Date#getTimezoneOffset()`) as "Z" or "+hhmm"/"-hhmm".
 *
 * The sign is inverted relative to the input: a positive offset (behind UTC) yields "-hhmm".
 *
 * @returns Formatted offset, or "" when the input is not a number.
 */
export const formatTimezone = (tzOffsetInMinutes: string | number): string => {
  const offset = Number(tzOffsetInMinutes);
  if (Number.isNaN(offset)) return "";
  if (offset === 0) return "Z";
  return offset > 0 ? `-${pad(offset / 60)}${pad(offset % 60)}` : `+${pad(-offset / 60)}${pad(-offset % 60)}`;
};

/**
 * Format-token renderers used by `dateFormat`, keyed by token:
 * yyyy (full year), MM (2-digit month), MMM (short month name), MMMM (full month name), dd (2-digit day),
 * hh (2-digit hours, 24h), mm (2-digit minutes), ss (2-digit seconds), SSS (milliseconds, padded to 2 digits),
 * w (full day name), ww (2-letter day name), l (epoch milliseconds), X (local timezone offset).
 */
export const DATE_FORMATTERS: Hash<(date: Date) => string> = {
  hh: (date) => pad(date.getHours()),
  mm: (date) => pad(date.getMinutes()),
  ss: (date) => pad(date.getSeconds()),
  SSS: (date) => pad(date.getMilliseconds()),

  dd: (date) => pad(date.getDate()),
  w: (date) => dayNames[date.getDay()],
  ww: (date) => dayNamesShort[date.getDay()],
  MMMM: (date) => monthNames[date.getMonth() + 1],
  MMM: (date) => monthNamesShort[date.getMonth() + 1],
  MM: (date) => pad(date.getMonth() + 1),
  yyyy: (date) => `${date.getFullYear()}`,
  l: (date) => `${date.getTime()}`,
  X: (date) => formatTimezone(date.getTimezoneOffset()),
};

/** Default date-only format. */
export const DEFAULT_DATE_FORMAT = "yyyy-MM-dd";

/** Default date-time format. */
export const DEFAULT_DATE_TIME_FORMAT = "yyyy-MM-dd hh:mm";
