import type { Hash, XmlNode } from "ultimus";
import { xmlParse } from "ultimus";
import { Arrmatron } from "../core/Arrmatron";
import { ManifestNode } from "../core/ManifestNode";
import type { EContent, IPlatform } from "../types";
import type { CCompositeNode } from "./composition";

class RootCtx extends Arrmatron<CCompositeNode> {
  get displayName(): string {
    return `ROOT`;
  }

  get scopeForChildren(): Arrmatron {
    return this;
  }

  slotContent(_slotId?: string): EContent | undefined {
    return undefined;
  }

  createComponent() {
    return this.platform.createComponent({});
  }
}

export class CRootNode extends ManifestNode {
  slotContent: Hash<EContent>;
  nodes?: XmlNode["nodes"];
  parsed: XmlNode[];

  constructor(private template: string) {
    super("R0");
    this.slotContent = {};
    this.parsed = xmlParse(this.template);
  }

  getSubNodes(platform: IPlatform) {
    return platform.getCompiledNodes(this.parsed);
  }

  getSlotContent(_platform: IPlatform, _slotId?: string) {
    return undefined;
  }

  get EntitronConstructor() {
    return RootCtx;
  }
}
