import type { Scalar } from "../types";

/**
 * Parses a string into a scalar value.
 *
 * Rules, in order:
 * - `""` stays `""`; `"true"`/`"false"` become booleans.
 * - Strings starting with a digit, `+` or `-` and at most 17 chars long are coerced with unary `+`;
 *   if the result is `NaN` (e.g. `"12abc"`), the original string is returned. Longer numeric strings
 *   stay strings (float-precision guard).
 * - `"null"` becomes `null`; `"undefined"` (or no input) becomes `undefined`.
 * - Anything else is returned as-is.
 */
export const scalarParse = (s?: string): Scalar | null => {
  if (s === "") {
    return "";
  }
  if (s === "true") {
    return true;
  }
  if (s === "false") {
    return false;
  }
  if (s === "0") {
    return 0;
  }
  if (s === "1") {
    return 1;
  }
  if (s && "1234567890+-".includes(s[0]) && s.length <= 17) {
    const num = +s;
    return Number.isNaN(num) ? s : num;
  }
  if (s === "null") {
    return null;
  }
  if (s === "undefined") {
    return undefined;
  }
  return s;
};
