/**
 * One JSON transport for every Firebase REST surface.
 *
 * `loadJson` from ultimus is not used here on purpose: it throws on a non-2xx status before
 * reading the body, and both Google's APIs and our own `api` function put the only useful part of
 * a failure — the message — inside that body.
 */

/** A failed request, carrying the parsed response body so callers can branch on the real code. */
export class RestError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: any
  ) {
    super(message);
    this.name = "RestError";
  }
}

/**
 * Pulls the human-readable message out of a failure body.
 *
 * - Google APIs answer `{ error: { code, message, status } }`.
 * - `createHttpApiCallHandler` answers `{ data: { ok: false, error: { code, message } } }`.
 */
export function errorMessageOf(body: any): string | undefined {
  const message = body?.error?.message ?? body?.data?.error?.message ?? body?.error_description;
  return typeof message === "string" && message ? message : undefined;
}

export interface RequestJsonOptions extends Omit<RequestInit, "body"> {
  /** Sent as-is when a string or Blob, JSON-stringified otherwise. */
  body?: unknown;
  /** Aborts the request after this many milliseconds. */
  timeoutMs?: number;
}

/** Performs a request and resolves with the parsed JSON body, throwing {@link RestError} on failure. */
export async function requestJson<T = any>(url: string, options: RequestJsonOptions = {}): Promise<T> {
  const { body, timeoutMs, headers, ...init } = options;
  const controller = timeoutMs ? new AbortController() : undefined;
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : undefined;

  const isRaw = typeof body === "string" || body instanceof Blob || body instanceof ArrayBuffer;

  try {
    const response = await fetch(url, {
      method: body === undefined ? "GET" : "POST",
      mode: "cors",
      signal: controller?.signal,
      ...init,
      headers,
      body: body === undefined ? undefined : isRaw ? (body as BodyInit) : JSON.stringify(body),
    });

    const text = await response.text();
    // Storage DELETE and a few emulator routes answer 200 with an empty body.
    const parsed = text ? JSON.parse(text) : null;

    if (!response.ok) {
      throw new RestError(
        errorMessageOf(parsed) ?? `HTTP ${response.status} ${response.statusText} for ${url}`,
        response.status,
        parsed
      );
    }

    return parsed as T;
  } finally {
    clearTimeout(timer);
  }
}
