import { parseJson } from "ultimus";
import { type DomNode, type IElement, setEventListener, WebClientService } from "@/core";

const attrs = {
  draggable: ($: IElement, elt: DomNode, value) => {
    const enabled = !!value;
    elt.setAttribute("draggable", String(enabled));
    const className = String(elt.getAttribute("dragClass") ?? "dragging").split(" ");
    setEventListener($, "draggable:dragend", (_e) => {
      if (enabled) {
        elt.classList.remove(...className);
      }
    });

    setEventListener($, "draggable:dragstart", (event) => {
      if (!enabled) return;

      const anchorId = elt.getAttribute("dragAnchor");
      if (anchorId) {
        const anchor = elt.getElementsByClassName(anchorId).item(0);
        if (!anchor || !elt.contains(anchor)) {
          event.preventDefault(); // Cancel drag if not from anchor
          return;
        }
      }

      elt.classList.add(...className);
      event.dataTransfer.effectAllowed = "all";
      event.dataTransfer.setData("text/plain", JSON.stringify({ ...elt.$dataset, dragdropType: $.dragdropType }));
    });
  },

  dragstart: ($: IElement, elt: DomNode) => {
    setEventListener($, "dragstart", (e) => {
      e.preventDefault();
      setTimeout(() => {
        $.dragstart?.({ ...elt.$dataset, nativeEvent: e });
      }, 0);
    });
  },
  dragend: ($: IElement, elt: DomNode) => {
    setEventListener($, "dragend", (e) => {
      e.preventDefault();
      setTimeout(() => {
        $.dragend?.({ ...elt.$dataset, nativeEvent: e });
      }, 0);
    });
  },
  dragover: ($: IElement, elt: DomNode) => {
    setEventListener($, "dragover", (e) => {
      e.preventDefault();
      setTimeout(() => {
        $.dragover?.({ ...elt.$dataset, nativeEvent: e });
      }, 0);
    });
  },
  dragenter: ($: IElement, elt: DomNode) => {
    setEventListener($, "dragover", (e) => {
      e.preventDefault();
      const className = String(elt.getAttribute("dragoverClass") ?? "dragover");
      elt.classList.add(className);
      setTimeout(() => {
        $.dragover?.({ ...elt.$dataset, nativeEvent: e });
      }, 0);
    });
  },
  dragleave: ($: IElement, elt: DomNode) => {
    setEventListener($, "dragover", (e) => {
      e.preventDefault();
      const className = String(elt.getAttribute("dragoverClass") ?? "dragover");
      elt.classList.remove(className);
      setTimeout(() => {
        $.dragover?.({ ...elt.$dataset, nativeEvent: e });
      }, 0);
    });
  },

  dragdrop: ($: IElement, elt: DomNode) => {
    const className = String(elt.getAttribute("dragoverClass") ?? "dragover").split(" ");

    setEventListener($, "dragdrop:dragenter", (e) => {
      elt.classList.add(...className);
      e.preventDefault();
    });
    setEventListener($, "dragdrop:dragover", (e) => {
      elt.classList.add(...className);
      e.preventDefault();
    });
    setEventListener($, "dragdrop:dragleave", (_e) => {
      elt.classList.remove(...className);
    });

    setEventListener(
      $,
      "drop",
      (e) => {
        elt.classList.remove(...className);

        const raw = e.dataTransfer.getData("text/plain");
        const { dragdropType, ...source } = parseJson(raw) ?? {};

        if (dragdropType && dragdropType !== $.dragdropType) return;

        $.dragdrop?.({ ...elt.$dataset, ...source, source, target: elt.$dataset });
      },
      true
    );
  },
};

export class DragPlugin extends WebClientService {
  __init() {
    this.webPlatform.addElementAttributeSetters(attrs);
  }
}
