import type { Hash } from "../types";

/** Max candidates kept per keyword line — a long paste should stay scannable. */
const MAX_PER_LINE = 10;

/** Lowercases and reduces every non-alphanumeric run to a single space, so punctuation never blocks a match. */
const normalize = (text: unknown) =>
  String(text ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

/**
 * Scores how well `text` matches one keyword `line`, in 0..1.
 *
 * Every word of the line must occur in the text (any order, punctuation-insensitive);
 * a missing word scores 0. Beyond that, a match scores higher the more of the text the
 * words cover, the more of them land on whole words, and if the text starts with the first word.
 */
export const scoreKeywordMatch = (text: unknown, line: unknown): number => {
  const haystack = normalize(text);
  const needle = normalize(line);
  if (!haystack || !needle) return 0;
  if (haystack === needle) return 1;

  const words = needle.split(" ");
  if (!words.every((word) => haystack.includes(word))) return 0;

  const haystackWords = haystack.split(" ");
  const coverage = Math.min(1, words.reduce((sum, word) => sum + word.length, 0) / haystack.length);
  const wholeWordRatio = words.filter((word) => haystackWords.includes(word)).length / words.length;
  const prefixBonus = haystack.startsWith(words[0]) ? 1 : 0;

  return 0.6 * coverage + 0.3 * wholeWordRatio + 0.1 * prefixBonus;
};

export type KeywordMatch<T> = T & { score: number };
export type KeywordMatchGroup<T> = { line: string; items: KeywordMatch<T>[] };

/** Splits a multiline keyword blob into its non-empty, trimmed lines. */
export const keywordLines = (keywords: unknown): string[] =>
  String(keywords ?? "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

/**
 * Matches `items` against every line of a multiline `keywords` blob.
 *
 * Returns one group per non-empty line — kept even when nothing matched, so a pasted
 * list shows which entries could not be found — each holding its scored candidates,
 * best first, capped at {@link MAX_PER_LINE}.
 */
export const matchByKeywords = <T extends Hash<any>>(
  items: T[] | undefined,
  keywords: unknown,
  propName = "name"
): KeywordMatchGroup<T>[] => {
  const lines = keywordLines(keywords);
  if (!items?.length || !lines.length) return [];

  return lines.map((line) => ({
    line,
    items: items
      .map((item) => ({ ...item, score: scoreKeywordMatch(item[propName], line) }))
      .filter((item) => item.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, MAX_PER_LINE),
  }));
};
