import { hashCodeOf } from "ultimus";
import type { Component } from "../core/Component";

export function defineCalculatedProperty(target: Component, key, fn: (...args: any[]) => any, deps?: string[]) {
  let depKeys: any[];
  let depValue: any;
  let requestId = 0;
  Object.defineProperty(target, key, {
    get() {
      const args: any[] = deps?.length ? deps.map((k) => target.get(k)) : [];
      const hasAsync = args.some((v) => v instanceof Promise);

      const functor = (args) => {
        const newKeys: number[] = args.map((v) => hashCodeOf(v));
        if (!depKeys || newKeys.some((e, i) => e !== depKeys[i])) {
          depKeys = newKeys;
          depValue = fn.apply(target, args);
        }
        return depValue;
      };
      if (!hasAsync) return functor(args);

      requestId++;
      return new Promise((res, rej) => {
        Promise.all(args.map((v) => (v instanceof Promise ? v : Promise.resolve(v))))
          .then(functor)
          .then(
            ((id) => (r) => {
              // console.log(">>>>", r);
              if (id === requestId) {
                res(r);
              }
            })(requestId)
          )
          .catch((err) => {
            rej(err);
          });
      });
    },
  });
}
