// Wraps text in single quotes for CML attribute usage; escapes embedded apostrophes and CML metacharacters.
// CML eats `{…}` in attribute text — escape `{` and `@` so they survive interpolation.
const escapeForCml = (text: string) => String(text); //.replaceAll("\\", "\\\\"); //.replaceAll("@", "&#x40;");

export const escapeText = (text: string) => `'${escapeForCml(text)}'`;
export const wrapText = (text: string) => `'${escapeForCml(text)}'`;
