import type { Dateable } from "../types";

import { DATE_FORMATTERS, DEFAULT_DATE_FORMAT } from "./consts";
import { dateOf } from "./dateOf";

/**
 * Formats a date-like value using a token pattern (default "yyyy-MM-dd").
 *
 * Supported tokens: yyyy (full year), MM (2-digit month), MMM (short month name), MMMM (full month name),
 * dd (2-digit day), hh (2-digit hours, 24h), mm (2-digit minutes), ss (2-digit seconds),
 * SSS (milliseconds, padded to 2 digits), w (full day name), ww (2-letter day name),
 * l (epoch milliseconds), X (local timezone offset, e.g. "Z" or "+0200").
 * Underscores in the format are replaced with newlines.
 *
 * @param x - Anything `dateOf` accepts: Date, epoch millis, ISO 8601 string, or `{ getTime }`/`{ toDate }` object.
 * @returns Formatted string, or "" when the input is falsy or not convertible to a Date.
 */
export const dateFormat = (x: Dateable | null, format = DEFAULT_DATE_FORMAT): string => {
  if (!x) {
    return "";
  }
  const date = dateOf(x);
  if (!date) {
    return "";
  }
  return format
    .replace(/_/g, "\n")
    .replace(/(yyyy|MMM?M?|dd|hh|mm|ss|SSS|X|ww?|l)/g, (key) =>
      key in DATE_FORMATTERS ? DATE_FORMATTERS[key](date) : key
    );
};
