import { LOCAL_SCOPE_PREFIX } from "../core/Arrmatron";
import { resolveExpression } from "./resolveExpression";

let COUNTER = 1;

export function prepareConnectedProps(v: string) {
  const props: Record<string, string> = {};
  v = v.replaceAll(/@(\w+)\.(\w+)/g, (key) => {
    const prop = LOCAL_SCOPE_PREFIX + COUNTER++;
    props[prop] = key.slice(1);
    return prop;
  });

  const expr = resolveExpression(v);
  return { expr, props: Object.entries(props) };
}
