import { stringHash } from "ultimus";
import { requestJson } from "./http";
import type { AuthSession, AuthUser, RestEndpoints } from "./types";

const GOOGLE_PROVIDER = "google.com";

/** The account half of an Identity Toolkit response — all that `accounts:lookup` returns. */
interface AccountInfo {
  localId: string;
  email?: string;
  displayName?: string;
  photoUrl?: string;
  emailVerified?: boolean;
  providerId?: string;
}

/** An `accounts:signInWithIdp` response: an account plus a freshly minted token pair. */
interface IdpResponse extends AccountInfo {
  idToken: string;
  refreshToken: string;
  expiresIn: string;
}

const withKey = (base: string, path: string, apiKey: string) => `${base}/${path}?key=${encodeURIComponent(apiKey)}`;

const JSON_HEADERS = { "Content-Type": "application/json" };

/** Turns the `expiresIn` seconds string every Google token endpoint returns into an absolute deadline. */
export function expiryFrom(expiresIn: string | number, now = Date.now()): number {
  return now + Number(expiresIn || 3600) * 1000;
}

/** Normalizes an Identity Toolkit response into the SDK-shaped user the templates already read. */
export function userFromIdp(response: AccountInfo): AuthUser {
  const user = {
    uid: response.localId,
    email: response.email ?? "",
    displayName: response.displayName ?? "",
    photoURL: response.photoUrl ?? "",
    emailVerified: response.emailVerified ?? false,
  };

  return { ...user, providerData: [{ providerId: response.providerId ?? GOOGLE_PROVIDER, ...user }] };
}

const sessionFromIdp = (response: IdpResponse): AuthSession => ({
  idToken: response.idToken,
  refreshToken: response.refreshToken,
  expiresAt: expiryFrom(response.expiresIn),
  user: userFromIdp(response),
});

/**
 * Exchanges a Google OAuth access token for a Firebase session.
 *
 * This is the same call the Firebase SDK makes once its popup closes; the only difference is that
 * the token comes from Google Identity Services rather than from the SDK's hosted handler.
 */
export async function signInWithGoogleToken(
  endpoints: RestEndpoints,
  accessToken: string,
  requestUri: string
): Promise<AuthSession> {
  const response = await requestJson<IdpResponse>(
    withKey(endpoints.identity, "accounts:signInWithIdp", endpoints.apiKey),
    {
      headers: JSON_HEADERS,
      body: {
        postBody: `access_token=${encodeURIComponent(accessToken)}&providerId=${GOOGLE_PROVIDER}`,
        requestUri,
        returnIdpCredential: true,
        returnSecureToken: true,
      },
    }
  );

  return sessionFromIdp(response);
}

/**
 * Signs in against the Auth emulator, which accepts a plain JSON object in place of a signed
 * Google id_token. Real Google is never contacted, so local dev and e2e need no credentials.
 *
 * `sub` is derived from the email so that repeated runs land on the same emulator account.
 */
export async function signInAsEmulatorUser(
  endpoints: RestEndpoints,
  { email, name = email.split("@")[0] }: { email: string; name?: string },
  requestUri: string
): Promise<AuthSession> {
  const claims = { sub: `google-${stringHash(email)}`, email, email_verified: true, name };

  const response = await requestJson<IdpResponse>(
    withKey(endpoints.identity, "accounts:signInWithIdp", endpoints.apiKey),
    {
      headers: JSON_HEADERS,
      body: {
        postBody: `id_token=${encodeURIComponent(JSON.stringify(claims))}&providerId=${GOOGLE_PROVIDER}`,
        requestUri,
        returnSecureToken: true,
      },
    }
  );

  return sessionFromIdp(response);
}

/** Trades the long-lived refresh token for a fresh id token. Google may rotate the refresh token. */
export async function refreshIdToken(
  endpoints: RestEndpoints,
  refreshToken: string
): Promise<Pick<AuthSession, "idToken" | "refreshToken" | "expiresAt">> {
  const response = await requestJson<{ id_token: string; refresh_token: string; expires_in: string }>(
    withKey(endpoints.secureToken, "token", endpoints.apiKey),
    {
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: `grant_type=refresh_token&refresh_token=${encodeURIComponent(refreshToken)}`,
    }
  );

  return {
    idToken: response.id_token,
    refreshToken: response.refresh_token,
    expiresAt: expiryFrom(response.expires_in),
  };
}

/** Reads the account behind an id token — used when a restored session has a token but no profile. */
export async function lookupUser(endpoints: RestEndpoints, idToken: string): Promise<AuthUser | null> {
  const response = await requestJson<{ users?: AccountInfo[] }>(
    withKey(endpoints.identity, "accounts:lookup", endpoints.apiKey),
    { headers: JSON_HEADERS, body: { idToken } }
  );

  const [account] = response?.users ?? [];
  return account ? userFromIdp(account) : null;
}
