import { guid } from "../crypto/guid";

/** Symbol under which a memoized hash code is stored on an object (see {@link defineObjectHashCodeProperty}). */
export const HASH_SYMBOL = Symbol("HASH_SYMBOL");

const STRING_CACHE = new Map([["", __stringHashCode("__empty__")]]);

const CONST_CACHE = new Map<unknown, number>([
  [undefined, stringHashCode("__undefined__")],
  [null, stringHashCode("__null__")],
  ["", stringHashCode("__empty__")],
  [NaN, stringHashCode("__NaN__")],
  [false, stringHashCode("__false__")],
  [true, stringHashCode("__true__")],
]);

const TYPE_NUMS = {
  Object: stringHashCode("__Object__"),
  Date: stringHashCode("__Date__"),
  Array: stringHashCode("__Array__"),
  Map: stringHashCode("__Map__"),
  Set: stringHashCode("__Set__"),
} as const;

function __stringHashCode(x: string) {
  let h = 0x811c9dc5 | 0;
  for (let i = 0; i < x.length; i++) {
    h ^= x.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h | 0;
}

function numberHashCode(n: number, r: number) {
  return Math.imul(r ^ n, 0x01000193) | 0;
}

/** FNV-1a 32-bit hash of a string, memoized in a module-level cache. */
export function stringHashCode(x: string) {
  const c = STRING_CACHE.get(x);
  if (c) return c;

  const h = __stringHashCode(x);

  STRING_CACHE.set(x, h);

  return h;
}

/**
 * Memoizes a hash code on an object as a hidden read-only `HASH_SYMBOL` property.
 *
 * No-op when the object already carries one. Without an explicit `val`, a random
 * identity hash is used (identity semantics for functions and Promises).
 *
 * @returns the same object
 */
export function defineObjectHashCodeProperty(obj: object, val?: number) {
  if (!obj || Object.hasOwn(obj, HASH_SYMBOL)) return obj;

  const code = val ?? __stringHashCode(guid());

  Object.defineProperty(obj, HASH_SYMBOL, {
    get() {
      return code;
    },
    configurable: false,
    enumerable: false,
  });

  return obj;
}

function containerHashCode(x: any, deepLevel: number) {
  // Depth cap: also bounds cyclic structures — recursion terminates here instead
  // of being detected as a cycle, so no visited-set bookkeeping (or alloc) is needed.
  if (deepLevel > 10) return -1;
  const next = deepLevel + 1;

  let r = 0;

  if (x instanceof Map) {
    r = numberHashCode(TYPE_NUMS.Map, r);
    for (const [key, v] of x) {
      r = numberHashCode(stringHashCode(key), r);
      r = numberHashCode(TYPE_NUMS.Map, r);
      r = numberHashCode(hashCodeOf(v, next), r);
    }
  } else if (x instanceof Set) {
    r = numberHashCode(TYPE_NUMS.Set, r);
    for (const v of x) {
      r = numberHashCode(hashCodeOf(v, next), r);
    }
  } else if (Array.isArray(x)) {
    r = numberHashCode(TYPE_NUMS.Array, r);
    for (const v of x) {
      r = numberHashCode(hashCodeOf(v, next), r);
    }
  } else {
    r = numberHashCode(TYPE_NUMS.Object, r);
    for (const key in x) {
      if (Object.hasOwn(x, key) && key[0] !== "$") {
        r = numberHashCode(stringHashCode(key), r);
        r = numberHashCode(TYPE_NUMS.Object, r);
        r = numberHashCode(hashCodeOf(x[key], next), r);
      }
    }
  }

  return r;
}

/**
 * Order-sensitive structural hash of any value.
 *
 * Numbers hash to themselves; strings via FNV-1a; functions and Promises get a memoized identity
 * hash; objects with a memoized `HASH_SYMBOL` return it; containers hash recursively (depth-capped
 * at 10, which also bounds cycles). Plain-object keys starting with `$` are skipped.
 *
 * @param deepLevel internal recursion depth; callers should omit it
 */
export const hashCodeOf = (x: any, deepLevel = 0) => {
  if (CONST_CACHE.has(x)) return CONST_CACHE.get(x);

  if (typeof x === "string") return stringHashCode(x);
  if (typeof x === "number") return x;
  if (typeof x === "bigint") return stringHashCode(x.toString(16));
  if (typeof x === "symbol") return stringHashCode(x.description ?? x.toString());
  if (typeof x === "function") return defineObjectHashCodeProperty(x)[HASH_SYMBOL];

  if (HASH_SYMBOL in x) return x[HASH_SYMBOL];

  if (x instanceof Date) return numberHashCode(x.getTime(), TYPE_NUMS.Date);
  if (x instanceof Promise) return defineObjectHashCodeProperty(x)[HASH_SYMBOL];

  return containerHashCode(x, deepLevel);
};

/**
 * Content hash specialized for `isEquals`. Precondition: `x` is a non-null object with no memoized
 * `HASH_SYMBOL` — the leaf case reached after primitives and hashed objects are ruled out. Skips
 * `hashCodeOf`'s constant-cache lookup, `typeof` ladder and `HASH_SYMBOL` check; produces the same
 * value as `hashCodeOf(x)` for those inputs.
 */
export const objectHashCode = (x: any, deepLevel = 0) => {
  if (x instanceof Date) return numberHashCode(x.getTime(), TYPE_NUMS.Date);
  if (x instanceof Promise) return defineObjectHashCodeProperty(x)[HASH_SYMBOL];
  return containerHashCode(x, deepLevel);
};
