import type { Uid, XmlNode } from "ultimus";
import { xmlParse } from "ultimus";
import { compileManifestNode, compileManifestNodes } from "../compiler";
import type { IComponent, IComponentDescriptor, IManifestNode, LogEntry } from "../types";
import { createRegisterTypes } from "../utils/createRegisterTypes";
import { Component } from "./Component";
import { NativeElement } from "./NativeElement";

/**
 * Component type registry and template compilation cache — the base {@link Platform} builds on.
 *
 * Holds what every instance of a component shares: its descriptor (constructor or template source) and
 * the compiled manifest tree of that template. Compilation is memoized per tag, so a template is parsed
 * once no matter how many instances exist.
 */
export class Registry {
  /** Descriptors by tag, populated by registering components on the platform. */
  typeRegistry = new Map<string, IComponentDescriptor>();
  /** Memoized compilation results, keyed by tag or by the parsed nodes themselves. */
  compiledTemplates = new Map<string | XmlNode | XmlNode[], IManifestNode | Map<Uid, IManifestNode>>();
  /** Class used for tags with no registered component; swapped by the DOM platform for a real element. */
  NativeElement = NativeElement;

  registerTypes(value: any) {
    createRegisterTypes((ctr: IComponentDescriptor) => {
      const tag = String(ctr.tag);
      this.compiledTemplates.delete(tag);
      this.typeRegistry.set(tag, ctr);
    })(value);
  }

  /**
   * Resolves a tag to its descriptor, falling back through dotted prefixes:
   * `Page.Speaking.Header` tries `Page.Speaking`, then `Page`.
   *
   * That fallback makes namespaced tags inherit a generic implementation — and equally means a tag
   * registered at a shorter prefix will silently capture longer ones.
   *
   * @returns The descriptor, or an `unknown: true` placeholder rendered as a plain `div`.
   */
  getByTag(tag: string): IComponentDescriptor {
    const r = this.typeRegistry.get(tag);

    if (r) return r;
    const parts = tag.split(".");
    for (parts.pop(); parts.length; parts.pop()) {
      const r = this.typeRegistry.get(parts.join("."));
      if (r) return r;
    }

    return { tag, unknown: true };
  }

  /** Parses template XML, degrading a parse failure into a `div` showing the error instead of throwing. */
  xmlParse(template: string): XmlNode[] {
    try {
      return xmlParse(template);
    } catch (error) {
      return [{ tag: "div", text: String(error), id: "error" } as unknown as XmlNode];
    }
  }

  /**
   * Compiles a template into manifest nodes, memoizing by tag.
   *
   * Only the string (by-tag) form is cached, since it is the one hit repeatedly during rendering;
   * pre-parsed nodes are compiled on each call. A tag with no template yields an empty list.
   */
  getCompiledNodes(tag: XmlNode): IManifestNode;
  getCompiledNodes(tag: string): Map<string, IManifestNode>;
  getCompiledNodes(tag: XmlNode[]): Map<string, IManifestNode>;
  getCompiledNodes(tag: string | XmlNode | XmlNode[]) {
    if (typeof tag === "string") {
      const map = this.compiledTemplates;
      if (map.has(tag)) {
        return map.get(tag);
      }
      const def = this.getByTag(tag);
      if (!def?.template) return [];

      const template = def.template;
      const parsed = typeof template === "string" ? this.xmlParse(template) : template;

      const nodes = compileManifestNodes(parsed);
      map.set(tag, nodes);
      return nodes;
    }
    if (Array.isArray(tag)) {
      return compileManifestNodes(tag);
    }
    return compileManifestNode(tag);
  }

  /**
   * Builds the component implementation for a descriptor, by precedence:
   * native element -> registered `Ctor` -> plain `Component` for template-only types.
   *
   * Never throws: an unknown tag or a failing constructor is logged and replaced by a `div`, so one bad
   * component cannot take down the render.
   *
   * @param def - Descriptor, or a tag to look up via {@link getByTag}.
   */
  createComponent(def: IComponentDescriptor | string): IComponent {
    if (typeof def === "string") return this.createComponent(this.getByTag(def));
    const NativeConstructor = this.NativeElement;
    try {
      const { Ctor, tag, unknown, native } = def;

      if (native) {
        const c = new NativeConstructor(tag ?? "div", this as any);
        return c;
      }

      if (Ctor) return new Ctor();

      if (unknown) {
        this.log({ level: "info", message: `<-- unknown tag: ${tag} -->`, source: "registry" });
        return new NativeConstructor("div", this as any);
      }

      return new Component();
    } catch (error: any) {
      this.log({ level: "error", message: "createComponent failed", error, source: "registry" });
      return new NativeConstructor("div", this as any);
    }
  }

  /** Console logging; overridden by {@link Platform} subclasses that route logs elsewhere. */
  log(entry: LogEntry | string) {
    if (typeof entry === "string") {
      console.log(entry);
    } else {
      console.log(entry.source ?? "", entry.message ?? "", ...(entry.params ?? []));
    }
  }
}
