import type { Delta, XmlNode } from "ultimus";
import { Arrmatron } from "../core/Arrmatron";
import { ManifestNode } from "../core/ManifestNode";
import type { EContent, IArrmatron, IPlatform } from "../types";
import type { Composite } from "./composition";

class Conditional extends Arrmatron<CIfNode> {
  get contentManifests() {
    return this.ifCondition ? this.ifBranches.thenBlock : this.ifBranches.elseBlock;
  }

  get ifCondition() {
    return (this.$component as unknown as { condition: boolean }).condition;
  }

  get ifBranches() {
    return this.manifest.getBranches(this.platform);
  }

  get displayName(): string {
    return `🔹if:${this.manifest.expr}`;
  }
}

export class CIfNode extends ManifestNode {
  #xml: XmlNode;
  #branches?: { thenBlock?: EContent; elseBlock?: EContent };
  expr: string;
  constructor(xml: XmlNode, expr: string) {
    super(xml.id);
    this.#xml = xml;
    this.expr = expr;
    this.compileCondition(expr);
  }

  get EntitronConstructor() {
    return Conditional;
  }

  getBranches(platform: IPlatform) {
    if (this.#branches) {
      return this.#branches;
    }

    this.#branches = {};

    const { nodes } = this.#xml;

    let $then: XmlNode[] | undefined = [this.#xml];
    if (nodes?.length) {
      const ifElse = nodes.find((e) => e.tag === "Else");
      const ifThen = nodes.find((e) => e.tag === "Then");
      if (ifElse) {
        this.#branches.elseBlock = ifElse.nodes ? platform.getCompiledNodes(ifElse.nodes) : undefined;
        $then = ifThen ? ifThen.nodes : [{ ...this.#xml, nodes: nodes.filter((e) => e !== ifElse) }];
      } else if (ifThen) {
        $then = ifThen.nodes;
      }
    }
    this.#branches.thenBlock = $then ? platform.getCompiledNodes($then) : undefined;

    return this.#branches;
  }

  compileCondition(exprValue: string): void {
    if (exprValue.startsWith("Slot(")) {
      const slotId = exprValue.slice(5, -1);
      // DO NOT place inside iterations.
      this.propertyResolvers.push((c: IArrmatron, delta: Delta) => {
        delta.condition = !!(c.scope as Composite).slotContent?.(slotId)?.size;
        return delta;
      });
    } else {
      if (exprValue[0] === "{" && exprValue[exprValue.length - 1] === "}") {
        exprValue = exprValue.slice(1, -1);
      }
      this.bindExpression(exprValue, (v) => ({ condition: !!v }));
    }
  }
}
