/**
 * Serializes an array of flat objects to CSV; cells are JSON-quoted, nullish values become "".
 *
 * @param headers - column keys; defaults to the keys of the first row
 */
export function arrayToCSV(data: any[], headers?: string[]) {
  if (!Array.isArray(data) || data.length === 0) {
    return "";
  }
  const cols = headers ?? Object.keys(data[0]);
  const cell = (v: unknown) => JSON.stringify(v == null ? "" : v);
  const rows = data.map((obj) => cols.map((h) => cell(obj[h])).join(","));
  return [cols.join(","), ...rows].join("\n");
}
