/**
 * Defines a hidden (non-enumerable, non-configurable) read-only reference property on an object.
 *
 * Keeps back-references out of enumeration, serialization, and content hashing.
 *
 * @returns the same object, for chaining
 */
export function defineObjectRef<T extends object>(obj: T, key: PropertyKey, val: unknown): T {
  Object.defineProperty(obj, key, {
    get() {
      return val;
    },
    enumerable: false,
    configurable: false,
  });

  return obj;
}
