import { debounce, stringify } from "ultimus";
import { copyToClipboard, WebClientService } from "@/core";

/** Tailwind CSS v4 default min-width breakpoints (px), widest first. Anything below `sm` is `xs`. */
const BREAKPOINTS: Array<[name: string, minWidth: number]> = [
  ["2xl", 1536],
  ["xl", 1280],
  ["lg", 1024],
  ["md", 768],
  ["sm", 640],
  ["xs", 0],
];

const breakpointOf = (width: number) => BREAKPOINTS.find(([, minWidth]) => width >= minWidth)?.[0] ?? "xs";

/**
 * Common browser API.
 */
export class BrowserService extends WebClientService {
  /** Current Tailwind breakpoint name: xs | sm | md | lg | xl | 2xl. */
  breakpoint = breakpointOf(window.innerWidth);

  __init() {
    const onResize = debounce(() => {
      this.up({ breakpoint: breakpointOf(window.innerWidth) });
    }, 150);

    window.addEventListener("resize", onResize);
    this.defer(() => window.removeEventListener("resize", onResize));
  }

  get isMobile() {
    return this.breakpoint === "xs" || this.breakpoint === "sm";
  }

  get title() {
    return window.document.title;
  }

  set title(title: any) {
    window.document.title = `${title}`;
  }

  get location() {
    return window.location;
  }

  get hash() {
    return window.location.hash;
  }

  set hash(hash: any) {
    window.location.hash = `${hash}`;
  }

  reload() {
    window.location.reload();
  }

  scrollIntoView(eltId = "top") {
    const element = document.getElementById(eltId);
    if (!element) return;
    element.scrollIntoView({ behavior: "smooth", block: "end", inline: "nearest" });
  }

  addScript({ src = "", type = "module" }) {
    document.body.appendChild(Object.assign(document.createElement("script"), { type, src }));
  }

  copyToClipboard(data: any, fSilent = false) {
    copyToClipboard(data, fSilent ? null : (t) => this.toast(t));
  }

  fromClipboard() {
    if (document.hasFocus()) {
      return navigator.clipboard.readText().then((text) => {
        console.log(text);
        return text;
      });
    }
  }
  // Function to create a download link from an inline text string
  downloadContentAsFile({ filename, content = "", type = "text/plain" }: any) {
    if (content instanceof Promise) {
      return content.then((val) => this.downloadContentAsFile({ filename, type, content: val }));
    }

    // If the text content is not a string, convert it to a JSON string
    if (typeof content !== "string") {
      content = stringify(content);
    }
    // Create a Blob from the text content
    const blob = new Blob([content], { type });

    // Create a URL for the Blob
    const url = URL.createObjectURL(blob);

    // Create a new anchor element
    const link = document.createElement("a");

    // Set the download attribute with the desired file name
    link.download = filename;

    // Set the href to the Blob URL
    link.href = url;

    // Add the link to the document (optional, for visibility)
    document.body.appendChild(link);

    // Simulate a click on the link to start the download
    link.click();

    // Remove the link from the document
    document.body.removeChild(link);

    // Revoke the Blob URL to free up memory
    URL.revokeObjectURL(url);
  }
}
