import { Component, type LogEntry } from "arrmatura";
import type { Datum } from "ultimus";
import { Heartbeat } from "@/core";

export class ToastService extends Component {
  #items: LogEntry[] = [];

  heartbeat = new Heartbeat(() => {
    void this.emit("this.tick(data)", {});
  }, 250);

  get items() {
    return this.#items;
  }

  set items(items: LogEntry[]) {
    this.heartbeat.setActive(!!items.length);
    this.#items = items;
  }

  send(data: LogEntry) {
    const { items } = this;
    const now = Date.now();
    const id = String(data.id ?? now);
    const close = () => this.emit("this.close(data)", { id });
    const stop = () => this.emit("this.stop(data)", { id });
    const toast = {
      ...data,
      message: data.message || String(data),
      level: data?.message?.toLowerCase().startsWith("error") || data instanceof Error ? "error" : data.level,
      id,
      close,
      stop,
      createdAt: now,
      expireAt: data.timeout === -1 ? 0 : now + (data.timeout || 6000),
    };
    const prev = items.find((e) => e.id === id);
    if (prev) {
      toast.counter = (prev.message === toast.message ? 1 : 0) + (prev.counter ?? 1);
    }
    this.up({
      items: [toast, ...items.filter((e) => e.id !== id)],
    });
  }

  tick(_: unknown) {
    const now = Date.now();
    this.up({
      items: this.items
        .filter((e: LogEntry) => !e.expireAt || e.expireAt > now)
        .map((e: LogEntry) => ({
          ...e,
          progress: e.expireAt && e.createdAt ? 100 * (1 - (e.expireAt - now) / (e.expireAt - e.createdAt)) : 0,
        })),
    });
  }

  close({ id }: Datum) {
    this.up({
      items: this.items.filter((e) => e.id !== id),
    });
  }

  stop({ id }: Datum) {
    this.up({
      items: this.items.map((e) => (e.id !== id ? e : { ...e, expireAt: 0, stop: () => {} })),
    });
  }
}
