import { mapEntries } from "ultimus";
import type { ComponentConstructor, IComponentDescriptor } from "../types";

let COUNTER = 1;
type RegisterCallback = (ctr: IComponentDescriptor) => void;

function registerFromFunction(ctr: ComponentConstructor, register: RegisterCallback) {
  register({ Ctor: ctr, tag: ctr.name ?? fnName(ctr) });
}
function registerFromString(ctr: string, register: RegisterCallback) {
  ctr.replaceAll(/<Component\s+id="([^"]+)"(?:[^>]*)>([\s\S]*?)<\/Component>/gm, (_, tag, template) => {
    template = template
      .replaceAll(/<Signature\b[^>]*?\/>/gm, "")
      .replaceAll(/<Signature\b[^>]*?>[\s\S]*?<\/Signature>/gm, "")
      .replaceAll(/<Subcomponent\s+id="([^"]+)"(?:[^>]*)>([\s\S]*?)<\/Subcomponent>/gm, (_, subtag, subtemplate) => {
        subtemplate = subtemplate
          .replaceAll(/<(\/?)This-/gm, (_, slash) => {
            return `<${slash}${tag}-`;
          })
          .trim();
        register({ tag: `${tag}-${subtag}`, template: subtemplate });
        return "";
      })
      .replaceAll(/<(\/?)This-/gm, (_, slash) => {
        return `<${slash}${tag}-`;
      })
      .trim();

    register({ tag, template });
    return "";
  });
}

const fnName = (ctor: ComponentConstructor) =>
  (/^function\s+([\w$]+)\s*\(/.exec(ctor.toString()) ?? [])[1] ?? `C${String(COUNTER++)}`;

export function createRegisterTypes(register: RegisterCallback) {
  return (types?: any) => {
    if (!types) return;

    const registerType = (ctr) => {
      if (Array.isArray(ctr)) {
        ctr.filter(Boolean).forEach(registerType);
      } else if (typeof ctr === "string") {
        registerFromString(ctr, register);
      } else if (typeof ctr === "function") {
        registerFromFunction(ctr, register);
      } else if (ctr.tag || ctr.id) {
        register({ ...ctr, tag: ctr.tag ?? ctr.id });
      } else {
        mapEntries(ctr, (tag, template) => register({ tag, template }));
      }
    };

    registerType(types);
  };
}
