/**
 * String splitting and extraction utilities.
 */

import { str } from "./convert";

/** Splits a string by separator, trims each part, and drops empty parts. */
export function stringSplit(x: unknown, sep: string | RegExp = ","): string[] {
  if (x == null || x === "") return [];
  return String(x)
    .split(sep)
    .map((s) => s.trim())
    .filter(Boolean);
}

/** Returns the portion after the last occurrence of separator (the whole string if absent). */
export function strTail(x: unknown, sep = " "): string {
  const s = str(x);
  if (!s) return "";
  const pos = s.lastIndexOf(sep);
  return pos === -1 ? s : s.slice(pos + sep.length);
}

/** Returns the portion before the first occurrence of separator (the whole string if absent). */
export function strHead(x: unknown, sep: RegExp | string = /[\s:/]/): string {
  const s = str(x);
  if (!s) return "";
  const [result] = s.split(sep);
  return result;
}

/**
 * Merges two delimited strings, de-duplicating parts case-insensitively (later occurrences win).
 * @param keys accumulator of lowercased part -> original part; pre-seeded entries are included in the result
 * @example stringMerge("a,b", "B,c") // "B,c" wins over "b" -> "a,B,c"
 */
export function stringMerge(s1: unknown, s2: unknown, sep = ",", keys: Record<string, string> = {}): string {
  if (!s1 && !s2) return "";
  if (!s1) return str(s2);
  if (!s2) return str(s1);
  if (s1 === s2) return str(s1);

  const addKey = (s: string) => {
    const key = s.trim().toLowerCase();
    if (key) keys[key] = s;
  };

  stringSplit(s1, sep).forEach(addKey);
  stringSplit(s2, sep).forEach(addKey);

  return Object.values(keys).join(sep);
}
