/**
 * String transformation utilities.
 */

import type { Hash } from "../types";
import { str } from "./convert";

/** Trims whitespace from a string. */
export function strTrim(x: unknown): string {
  return str(x).trim();
}

/** Left-pads a string to at least `size` characters by prepending `fill`. */
export function strPad(x: string | number, size = 2, fill = " "): string {
  let s = str(x);
  while (s.length < size) {
    s = `${fill}${s}`;
  }
  return s;
}

/**
 * Substitutes a non-empty value into a template, replacing every `*`; returns `def` for empty values.
 * @example strEnhance("Name", "[*]") // "[Name]"
 */
export function strEnhance(x: unknown, template = "*", def = ""): string {
  const val = str(x);
  return val ? template.replaceAll("*", val) : def;
}

/**
 * Formats a template by substituting `{key}` placeholders from params.
 * Placeholder syntax is `{key?template?default}`: a falsy param falls back to `default`,
 * and when `template` is given the `@` inside it is replaced with the value.
 * @example stringFormat("Hi {name?Mr. @?Anon}", {}) // "Hi Mr. Anon"
 */
export function stringFormat(template: string, params: Hash = {}, regExp = /\{([^}]+?)\}/gi): string {
  return str(template).replaceAll(regExp, (_, key) => {
    const [prop, tpl = "", def = ""] = key.split("?");
    const val = params?.[prop] || def;
    if (!val) return "";
    return tpl ? tpl.replace("@", val) : val;
  });
}

/** Replaces a pattern in a string; `def` is used when no replacement is given. */
export function strReplace(x: unknown, pattern: string | RegExp, replacement?: string, def = ""): string {
  return str(x).replace(pattern, replacement ?? def);
}

/**
 * Reverses a string.
 * @example mirror("ab") // "ba"
 */
export function mirror(x: unknown): string {
  return str(x).split("").reverse().join("");
}

/**
 * Builds an uppercase abbreviation from the first letters of the first two words.
 * @example abbreviate("John Ronald Doe") // "JR"
 */
export function abbreviate(x: unknown, sep = " "): string {
  const s = str(x);
  if (!s) return "";
  return s
    .split(sep)
    .filter(Boolean)
    .map((word) => word[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();
}
