import type { XmlNode } from "../types";

import { stringifyAttributes } from "./stringifyAttributes";
import { escapeXml, htmlDoubleTags } from "./utils";

/** Options for xmlStringify/htmlStringify. */
export type XmlStringifyOptions = {
  /** Tags that always get an explicit closing tag, even when empty. */
  doubleTags?: string[];
};

/** Renders an XmlNode tree as HTML: common container tags are never self-closed. */
export function htmlStringify(node: XmlNode, tab = "", options: XmlStringifyOptions = {}): string {
  return xmlStringify(node, tab, { doubleTags: htmlDoubleTags, ...options });
}

/**
 * Renders an XmlNode tree as an indented XML string; text (from `node.text` or the `#text` attr)
 * and attribute values are XML-escaped. Empty nodes are self-closed unless listed in doubleTags.
 *
 * @param tab indentation prefix for this node; children are indented two extra spaces
 * @example xmlStringify({ tag: "a", id: "1", attrs: { x: 1 } }) // '<a x="1"/>'
 */
export function xmlStringify(node: XmlNode, tab = "", options: XmlStringifyOptions = {}): string {
  if (!node) return "";
  const { doubleTags } = options;
  const { tag, attrs, nodes = [], text = attrs?.["#text"] } = node;
  const stext = text ? escapeXml(String(text)) : "";

  const ssubs = nodes.map((c) => xmlStringify(c, `  ${tab}`, options)).join("\n");

  const sattrs = attrs ? stringifyAttributes(attrs) : "";
  const singleTag = !ssubs && !stext && !doubleTags?.includes(tag);
  return `${tab}<${tag}${sattrs}${singleTag ? "/>" : `>${ssubs ? `\n${ssubs}\n${tab}` : ""}${stext}</${tag}>`}`;
}
