import type { Hash } from "../types";

/**
 * Deep-merges `target` into `source`, mutating and returning `source`.
 *
 * Nested plain objects are merged recursively; arrays and non-object values are replaced.
 * If either argument is not an object, the other one is returned.
 */
export const mergeObject = (source: Hash<any>, target: Hash<any>) => {
  if (!source || typeof source !== "object") return target;
  if (!target || typeof target !== "object") return source;

  for (const [key, val] of Object.entries(target)) {
    if (typeof val === "object" && typeof source[key] === "object") {
      if (Array.isArray(source[key])) {
        source[key] = val;
      } else {
        source[key] = mergeObject(source[key], val);
      }
    } else {
      source[key] = val;
    }
  }
  return source;
};
