import { Component } from "arrmatura";
import { arrayGroupBy, type Data, getPredicat, type Hash, type StringHash, str } from "ultimus";

export type FieldMeta = {
  id: string;
  hidden?: string;
  disabled?: string;
  required?: string;
  caption?: string;
  name: string;
  typeSpec?: string;
};

export type GroupMeta = {
  id: string;
  name?: string;
  items: FieldMeta[];
  hidden?: boolean;
};

type GroupInfo = {
  tab: string;
  name?: string;
  visible?: string;
  isHorizontal?: boolean;
  isConditional?: boolean;
};

const getFieldsGroups = (fields: FieldMeta[], ctrl: FormController): GroupMeta[] => {
  return Object.values(arrayGroupBy(fields, "group")).map(({ id: id0, ...e }, index) => {
    const id = str(id0 || index);
    const size = e.items.length;
    const { name = "", visible, isHorizontal, isConditional } = ctrl.groups[id] ?? {};
    return {
      ...e,
      name,
      cols: isHorizontal ? (size > 3 ? 2 : size) : 1,
      id,
      isConditional,
      onChange: ctrl.createOnChangeFor(id),
      get hidden() {
        return visible ? !getPredicat(visible)(ctrl.data) : false;
      },
    };
  });
};

function getTabInfo(ctrl: FormController) {
  const tabs = Object.values(arrayGroupBy(ctrl.fields, ({ tab = "tab" }: any) => tab)).map(({ id, items }) => ({
    id,
    name: ctrl.tabs?.[id],
    items: getFieldsGroups(items as FieldMeta[], ctrl),
  }));
  const fixedTab = tabs.length === 1 || tabs[0]?.id === "top" ? tabs.shift() : null;
  return { fixedTab, tabs };
}

export class FormController extends Component {
  #data: { [k: string]: unknown } = {};
  #tabId: any;
  meta: any;
  error: any;
  change: any;
  groups: Hash<GroupInfo> = {};
  #fields: FieldMeta[] = [];
  counter = 0;
  declare errors: Hash[];
  disabled: any;
  context?: any;
  tabs: StringHash = {};

  get tabsInfo() {
    return getTabInfo(this);
  }

  get data() {
    return this.#data;
  }

  set data(d: Data) {
    this.#data = { ...d };
  }

  get tabId() {
    return this.#tabId ?? this.meta?.[0]?.tab;
  }

  set tabId(id: string) {
    this.#tabId = id;
  }

  set metaId(_id: unknown) {
    this.#fields = [];
    this.#tabId = null;
  }

  createOnChangeFor(id: string) {
    return ({ value, key = id }: { value: unknown; key?: string }) => {
      if (this.data[key] === value) return;

      this.data = { ...this.data, [key]: value };

      this.change?.(this.data);

      this.up({ touched: true });
    };
  }

  get fields(): FieldMeta[] {
    if (this.#fields?.length) return this.#fields;

    const getData = () => this.data;

    const getDisabled = () => this.disabled;

    const onChangeFor = new Proxy(
      {},
      {
        get: (target: any, prop: string) => {
          return target[`$${prop}`] || (target[`$${prop}`] = this.createOnChangeFor(prop));
        },
      }
    );

    const ctx = this.context;

    const metadata =
      this.meta
        ?.filter?.(({ tab, type, typeSpec, id, name, visible, isConditional, isHorizontal }: StringHash) => {
          if (type === "group") {
            this.groups[id] = {
              tab,
              name,
              visible,
              isConditional: !!isConditional || typeSpec?.includes("conditional"),
              isHorizontal: !!isHorizontal || typeSpec?.includes("horizontal"),
            };
            return false;
          }
          return true;
        })
        .map((fieldRecord: StringHash) => {
          const { id, visible, disabled = false, name, caption = name, type, multi, typeSpec, ...rest } = fieldRecord;
          const field = fieldRecord.field || id;
          const ff = {
            ...rest,
            id,
            type: multi ? `${type}.Multi` : type,
            typeSpec,
            caption,
            multi,
            error: (this.errors as Hash[])?.find((err) => err.field === field)?.message ?? null,
            onChange: this.createOnChangeFor(field),
            onChangeFor,
            get value() {
              // console.log("get value", id, getData()?.[id]);
              return getData()?.[field] ?? null;
            },
            get data() {
              return getData();
            },
            get disabled() {
              return getDisabled() || (disabled && getPredicat(disabled)(getData(), ctx));
            },
            get hidden() {
              return !(visible ? getPredicat(visible)(getData(), ctx) : true);
            },
          };
          return ff;
        }) ?? [];

    this.#fields = metadata;

    return this.#fields;
  }
}
