import type { Uid, XmlNode } from "ultimus";

import { Arrmatron } from "../core/Arrmatron";
import { ManifestNode } from "../core/ManifestNode";
import type { IManifestNode, IPlatform } from "../types";

class DynamicTag extends Arrmatron<CDynamicTagNode> {
  get displayName(): string {
    return "dynamics";
  }

  get _dynamicTag() {
    return (this.$component as unknown as { _dynamicTag: string })._dynamicTag;
  }

  get contentManifests(): Map<Uid, IManifestNode> {
    const tag = this._dynamicTag;
    const uid = `${this.uid}:${String(tag ?? "")}`;
    const compiled = this.manifest.getCompiledForTag(this.platform, tag);
    return new Map([[uid, Object.assign(compiled, { uid })]]);
  }
}

export class CDynamicTagNode extends ManifestNode {
  xml: XmlNode & { tag: string };
  #cache = new Map<string, IManifestNode>();

  constructor(xml: XmlNode, expr: string) {
    super(xml.id);
    this.compileAttribute("_dynamicTag", expr);
    this.xml = xml;
  }

  getCompiledForTag(platform: IPlatform, tag: string): IManifestNode {
    const key = String(tag ?? "");
    let compiled = this.#cache.get(key);
    if (!compiled) {
      compiled = platform.getCompiledNodes({ ...this.xml, tag } as XmlNode);
      this.#cache.set(key, compiled);
    }
    return compiled;
  }

  get EntitronConstructor() {
    return DynamicTag as any;
  }
}
