import type { UrlParams } from "../types";

/** Encodes a value as a URI component; objects are JSON-stringified first. */
export const encodus = (value: unknown): string => {
  return encodeURIComponent(typeof value === "object" ? JSON.stringify(value) : String(value));
};

/**
 * Serializes a params object into a query string, skipping empty keys and null/undefined values.
 *
 * @example stringifyUrlParams({ a: 1, b: "x y" }) // "a=1&b=x%20y"
 */
export const stringifyUrlParams = (params: unknown): string => {
  if (!params) return "";

  const hash = params as UrlParams;

  return Object.keys(hash)
    .filter((key) => key && hash[key] != null)
    .map((key) => `${encodeURIComponent(key)}=${encodus(hash[key])}`)
    .join("&");
};
