import { strEnhance, stringSplit } from "../string";
import type { Obj } from "../types";

export * from "./defineObjectRef";
export * from "./gettus";
export * from "./hashCodeOf";
export * from "./isEmpty";
export * from "./isEquals";
export * from "./mergeObject";
export * from "./objectFreeze";
export * from "./settus";
export * from "./transformObject";

const DEFAULT_ENTRY_HANDLER = (id: string, n: unknown) => ({ id, value: n });

/**
 * Reads property `k` (default `"name"`) from an object, with an optional key-enhancement pattern.
 *
 * Falsy property values fall back to `def`.
 */
export const dot = (x: any, k = "name", pattern?: string, def: any = null) =>
  x?.[pattern ? strEnhance(k, pattern, def) : k] || def;

/** Joins array items with a delimiter (default `", "`); returns `null` for a missing array. */
export const join = (x: any[], delim = ", ") => (x ? x.join(delim) : null);

/** `Object.keys` that returns `null` for a falsy input. */
export const keysOf = (x: any) => (x ? Object.keys(x) : null);

/** `Object.values` that returns `null` for a falsy input. */
export const valuesOf = (x: any) => (x ? Object.values(x) : null);

/** Like `typeof`, but distinguishes `"null"`, `"undefined"`, and `"array"`. */
export const typeOf = (x: any) =>
  x == null ? (x === null ? "null" : "undefined") : Array.isArray(x) ? "array" : typeof x;

/** Maps object entries to `{ id, value }` records; returns `null` for a falsy input. */
export const entriesOf = (x: any) => (x ? Object.entries(x).map(([id, value]) => ({ id, value })) : null);

/**
 * Pretty-prints a value as JSON: `""` for nullish input, one line per item for arrays.
 *
 * @returns a string, or a Promise of one when given a Promise
 */
export const stringify = (x: any, indent = 2) => {
  if (x == null) return "";
  if (x instanceof Promise) return x.then((val) => stringify(val, indent));
  if (Array.isArray(x)) return `[\n${x.map((e: any) => `${JSON.stringify(e)}`).join(",\n")}\n]`;
  return JSON.stringify(x, null, indent);
};

/** Creates a prototype-less object (`Object.create(null)`). */
export const objectCreate = (): object => {
  return Object.create(null);
};

/**
 * Builds a prototype-less object from an entries array, from alternating `key, value` args,
 * or by merging object args in place of a key.
 */
export const objectFrom = (...args: any[]): object => {
  if (Array.isArray(args[0])) return Object.fromEntries(args[0]);

  const obj = Object.create(null);
  for (let i = 0; i < args.length; i += 2) {
    if (args[i]) {
      if (typeof args[i] === "object") {
        Object.assign(obj, args[i]);
      } else {
        obj[args[i]] = args[i + 1];
      }
    }
  }
  return obj;
};

/** `Object.assign` that tolerates a falsy target (starts from `{}`). */
export const assign = (o: Obj, ...delta: unknown[]): object => {
  return Object.assign(o || {}, ...delta);
};

/** Assigns a single key/value onto an object (falsy target starts from `{}`). */
export const assignKeyValue = (o: Obj, key: string, value: unknown): object => {
  return Object.assign(o || {}, { [key]: value });
};

/** Maps object entries through `fn(key, value)` (default: `{ id, value }` records); `[]` for falsy input. */
export const mapEntries = <T = any, O extends object = object>(
  o: O | null | undefined,
  fn: (key: string, value: any) => T = DEFAULT_ENTRY_HANDLER as (key: string, value: any) => T
): T[] => {
  return !o ? [] : Object.entries(o).map(([key, value]: [string, any]) => fn(key, value));
};

/** Picks the listed keys (array or delimited string) into a new object. */
export const pickByKeys = (o: object | null | undefined, keys: string | string[]): object => {
  keys = Array.isArray(keys) ? keys : stringSplit(keys);
  return !o || !keys ? {} : Object.fromEntries(Object.entries(o).filter(([key]) => keys.includes(key)));
};

/** Returns a new object without the listed keys (array or delimited string). */
export const objectOmitKeys = (o: object | null | undefined, keys: string | string[]): object => {
  keys = Array.isArray(keys) ? keys : stringSplit(keys);
  return !o || !keys ? (o ?? {}) : Object.fromEntries(Object.entries(o).filter(([key]) => !keys.includes(key)));
};

/** Converts `{ id: props }` maps into an array of `{ ...props, id }` records; `[]` for falsy input. */
export const objectToArray = <T = any>(o: object | null | undefined): T[] => {
  return !o ? [] : Object.entries(o).map(([id, value]: any) => ({ ...value, id }));
};

/** True when a value carries data: non-nullish scalar, non-empty array, or object with a non-nullish value. */
export const isValuable = (x: any): boolean => {
  if (x == null) return false;
  if (Array.isArray(x)) return x.length > 0;
  if (typeof x === "object") return Object.values(x).find((v) => v != null) != null;
  return true;
};

/** True when `x[propName]` (default `"children"`) is a non-empty array. */
export const hasChildren = (x: any, propName = "children"): boolean => {
  const ch = x?.[propName];
  return ch != null && Array.isArray(ch) && ch.length > 0;
};

/**
 * Wraps a value as `{ [key]: x }` (default key `"value"`).
 *
 * @returns the wrapper object, or a Promise of one when given a Promise
 */
export const pack = (x?: unknown, key = "value"): object => {
  if (x instanceof Promise) return x.then((val) => pack(val, key));
  return { [key]: x };
};
