import { Component } from "arrmatura";
import { type Hash, parseJson } from "ultimus";

export class FieldFileController extends Component {
  disabled: any;
  value?: string;
  #files?: any[] | null;
  field = "file";

  // Reactive properties supplied by the framework (item context / up()).
  declare trigger?: string;
  declare itemId?: string;

  change(_data?: Hash) {
    //no-op
  }

  uploadFile(_data?: { value: FormData; fileName: string; callback: (...args: any[]) => void }) {
    //no-op
  }

  get files() {
    if (this.#files) return this.#files;
    if (!this.value) return [];
    if (typeof this.value === "string") return parseJson(this.value, []);
    return this.value;
  }

  setTrigger(value: string) {
    this.trigger = value;
    this.#files = null;
  }

  set files(files) {
    this.#files = files;

    const value = files?.length
      ? files
          .filter((f) => !f.status || f.status == "uploaded" || f.status == "saved")
          .map((e) => ({
            id: e.id,
            name: e.name,
            type: e.type,
            fullPath: e.fullPath,
          }))
      : null;

    this.change({ value });

    this.value = value;
  }

  appendFile({ value = [] }) {
    if (this.disabled) return;

    if (!value?.length) return;

    const files = [...this.files];

    // const formData = new FormData();

    [...value].forEach((file) => {
      const { lastModified, name, type } = file;
      const id = `${this.itemId}#${name}#${lastModified}`;
      let item = files.find((file) => file.id == id);
      if (item) return;

      item = {
        id,
        name,
        status: "loading",
        type,
        url: URL.createObjectURL(file),
      };
      files.push(item);

      this.uploadFile({
        value: file,
        fileName: `${this.itemId}-${name}`,
        callback: ({ value: url, fullPath, error }) => {
          this.up({
            files: files.map((e) =>
              e.id === id
                ? {
                    ...e,
                    fullPath,
                    status: error ? "error" : "uploaded",
                    url,
                    error: error?.message,
                  }
                : e
            ),
          });
        },
      });
    });

    this.up({ files });
  }
}
