import { assert, capitalize } from "ultimus";
import { type DomElement, WebClientService } from "@/core";

const REQUESTS_MAP = new Map();

function resolveTargetWindow(targetId: string): Window | undefined {
  if (targetId === "parent") {
    return window.parent;
  }
  if (targetId === "opener") {
    return window.opener;
  }
  if (targetId === "rnwv") {
    return window?.["ReactNativeWebView" as keyof typeof window];
  }
  const iframe = window.document.getElementById(targetId) as unknown as {
    contentWindow: any;
  };

  return iframe?.contentWindow;
}

export class PostMessageChannel extends WebClientService {
  eventOrigin = "";
  postOrigin = "/";
  targetId;
  disabled = false;
  ttl = 30000;
  targetRef: any;

  __init() {
    if (this.disabled) return;

    const handler = async (event: MessageEvent) => {
      const { action, data, requestId, error } = event.data;
      if (action === "@RESPONSE") {
        try {
          const promise = REQUESTS_MAP.get(requestId);
          assert(promise, `Received response to ${requestId}, but no promise found`);
          REQUESTS_MAP.delete(requestId);
          console.info(`Received response to ${requestId}`);
          if (error) {
            promise.reject(error);
          } else {
            promise.resolve(data);
          }
        } catch (error) {
          const { message } = error as Error;
          console.error(message);
        }
      } else {
        try {
          const handler = this[`on${capitalize(action)}`];
          if (handler) {
            console.info(`Received ${requestId ? "request for" : "message"} ${action}`);
            const result = await handler(data);
            if (requestId) {
              this.post({ action: "@RESPONSE", data: result, requestId });
            }
          }
        } catch (error) {
          const { message } = error as Error;
          console.error(message);
          if (requestId) {
            this.post({ action: "@RESPONSE", error: { message }, requestId });
          }
        }
      }
    };

    window.addEventListener("message", handler, false);
    this.defer(() => {
      window.removeEventListener("message", handler, false);
    });

    const timer = setInterval(() => {
      const now = Date.now();
      for (const [requestId, { reject, expires, message }] of REQUESTS_MAP.entries()) {
        if (expires && now > expires) {
          reject(new Error(`Timeout: ${message.action}`));
          REQUESTS_MAP.delete(requestId);
        }
      }
    }, 2000);

    this.defer(() => {
      clearInterval(timer);
    });
  }

  setPostMessage(message) {
    this.post(message);
  }

  post(message: any) {
    message = typeof message === "string" ? { action: message } : message;

    const {
      targetId = this.targetId,
      targetRef = this.targetRef,
      action = "action",
      requestId = action + Date.now(),
      timeout = this.ttl,
      data,
    } = message;

    return new Promise((resolve, reject) => {
      let targetWindow: Window | null | undefined = null;
      if (targetId) {
        targetWindow = resolveTargetWindow(targetId);
        if (!targetWindow) {
          reject(new Error(`Target window "${targetId}" not found`));
          return;
        }
      } else if (targetRef) {
        targetWindow = targetRef.$dom.contentWindow;
      } else {
        const dom = (this.$parentComponent as DomElement)?.$dom as any;
        if (!dom) {
          reject(new Error(`Target not set`));
          return;
        }
        if (dom.contentWindow) {
          targetWindow = dom.contentWindow;
        } else {
          dom.onload = () => {
            this.post(message)
              .then((r) => resolve(r))
              .catch((err) => reject(err));
          };
          return;
        }
      }

      if (this.disabled) {
        reject(new Error(`Channel is disabled`));
        return;
      }

      if (requestId && action !== "@RESPONSE") {
        REQUESTS_MAP.set(requestId, {
          message,
          resolve,
          reject,
          expires: timeout ? Date.now() + timeout : 0,
        });
      }

      targetWindow?.postMessage({ action, requestId, data }, this.postOrigin);
    });
  }
}
