import { type DomNode, type IElement, WebClientService } from "@/core";

const portalAttributeSetter = ($: IElement, element: DomNode, portalId: string): void => {
  if ($.attachToParent === portalAttributeSetter) return;

  $.attachToParent = (p: ShadowRoot | HTMLElement, _before?: ChildNode | HTMLElement | null) => {
    const portal = portalId ? document.getElementById(portalId) : null;

    // No portal found or portalId is empty, than dropping the element silently.
    if (!portal) return null;

    if (portal !== element.parentElement) {
      element.parentElement?.removeChild(element);
      portal.appendChild(element);
    }
    return element;
  };
};

export class PortalsPlugin extends WebClientService {
  __init() {
    this.webPlatform.addElementAttributeSetters({ portal: portalAttributeSetter });
  }
}
