import { Component } from "arrmatura";

/**
 * Fires its `action` handler once, when the component is mounted.
 *
 * The framework exposes no DOM mount event, so declarative one-shot side
 * effects (e.g. counting a page visit) are wired through the `__init`
 * lifecycle hook instead.
 *
 * Usage:
 *   <OnMount action="-> @docs.incViewCount(key)" />
 */
export class OnMount extends Component {
  declare action?: (data?: unknown) => unknown;

  __init() {
    this.action?.();
  }
}
