/** biome-ignore-all lint/suspicious/noDoubleEquals: as designed */

/** Alias of Array.isArray. */
export const isArray = (x: any) => Array.isArray(x);
/** Null-safe map; extra args are appended to each `fn(item, ...args)` call; nullish input yields []. */
export const map = (x: any, fn: any, ...args: any) => x?.map((e) => fn(e, ...args)) ?? [];
/** Null-safe `x.includes(p)`; returns false for non-searchable input. */
export const includes = (x: any, p: string) => x?.includes?.(p) ?? false;
/** Same as `includes` with arguments flipped: checks whether `x` contains `p`. */
export const included = (p: string, x: any) => x?.includes?.(p) ?? false;
/** Null-safe slice for arrays and strings; nullish input yields "" for strings, [] otherwise. */
export function slice(x: string, b?: number, e?: number): string;
export function slice<T>(x: T[] | null | undefined, b?: number, e?: number): T[];
export function slice(x: any, b = 0, e?: number) {
  return x?.slice?.(b, e) || (typeof x === "string" ? "" : []);
}
/** Null-safe string split (default separator: space); non-strings yield []. */
export const split = (x: string, key = " ") => x?.split?.(key) || [];
/** Concatenates values and arrays into a single flat (one level) array. */
export const concat = (...x: any[]) => [].concat(...x);
/** Finds the first item whose `key` property loosely equals `val`; returns null when absent. */
export const find = <T extends Record<string, any>>(x: T[], val: unknown, key = "id") =>
  x?.find?.((e: T) => e?.[key] == val) ?? null;
