import type { Dateable } from "../types";

import { dateParseISO8601 } from "./dateParseISO8601";

/**
 * Converts a date-like value to a Date: epoch millis, ISO 8601 string, Date,
 * or an object with `getTime()` (Date-like) or `toDate()` (e.g. Firestore Timestamp).
 *
 * @returns A new Date instance, or null when the value is nullish or not convertible.
 */
export function dateOf(x: Dateable | null): Date | null {
  if (x == null) {
    return null;
  }
  if (typeof x === "number") {
    return new Date(x);
  }
  if (typeof x === "string") {
    return dateParseISO8601(x);
  }
  if (typeof x === "object") {
    const dx = x as { getTime?: () => number; toDate?: () => Date };
    if (dx.getTime) {
      return new Date(dx.getTime());
    }
    if (dx.toDate) {
      return dx.toDate();
    }
  }
  return null;
}
