import { createStringInterpolator, scalarParse } from "ultimus";

import { compilePlaceholder } from "./compilePlaceholder";

const CACHE = new Map();

function compileConstant(a: string) {
  const vv = scalarParse(a);
  return () => vv;
}

function _resolveExpression(v: unknown) {
  if (typeof v !== "string") return () => v;

  if (v.includes("{")) {
    const vCutOne = v.slice(1, -1);
    if (v[0] === "{" && v.at(-1) === "}" && !vCutOne.includes("{")) {
      return compilePlaceholder(vCutOne).functor;
    }
    return createStringInterpolator(v, (expr) => compilePlaceholder(expr).functor);
  }
  return compileConstant(v);
}

export const resolveExpression = (x: unknown) => {
  return CACHE.has(x) ? CACHE.get(x) : CACHE.set(x, _resolveExpression(x)).get(x);
};
