import type { Delta, Fn, Hash, Proc, Uid } from "ultimus";
import { capitalize, defineObjectHashCodeProperty, defineObjectRef, hashCodeOf, isEquals } from "ultimus";
import type { IArrmatron, IComponent, IManifestNode, IPlatform } from "../types";
import { applyStateChangedToImpl } from "../utils/applyStateChangedToImpl";
import { stringify } from "../utils/stringify";
import { Component } from "./Component";
import { ARRMATURA } from "./consts";

/** Prefix marking a key that resolves against `__localScope` instead of the enclosing scope. */
export const LOCAL_SCOPE_PREFIX = "outer$";
/** Process-wide memo of `"a.b.c"` -> `["a", "b", "c"]`, shared by all instances. */
export const SPLITTED_KEYS = new Map<string, string[]>();
const EMPTY_PATH: string[] = [];
/** Re-entrancy counter: only the outermost `touch()` triggers `platform.redraw`. */
let TOUCH_DEPTH = 0;

/**
 * The main class of the framework: one instance per manifest node of the live component tree.
 *
 * Each instance owns a component implementation ({@link $component}), that component's state, its
 * children, and the reference registry of its scope — together they are the runtime mirror of the
 * compiled manifest tree.
 *
 * Lifecycle:
 * 1. `new Arrmatron(...)` — builds `$component` and registers itself under `refId` in its scope.
 * 2. {@link settle} — first call wires connectors, applies initial props, calls `$component.__init()`;
 *    subsequent calls just re-apply props resolved from the manifest.
 * 3. {@link up} — diffs a delta into state, then re-runs {@link touch}.
 * 4. {@link touch} — reconciles children against the manifest, notifies listeners, redraws once.
 * 5. {@link done} — marks the instance dead; the final `touch()` disposes children, refs and caches.
 *
 * State model:
 * - `__fprints` is the source of truth — the last applied value per key, used to diff incoming deltas.
 * - `$component` is a write-through projection of it (see `applyStateChangedToImpl`).
 * - `__propCache` memoizes what {@link get} returned; it is dropped on every `touch()` and per changed key.
 *
 * Convention: `__name` members are internal but reachable from sibling core classes and manifests;
 * `#name` members are strictly private to this class.
 */
export class Arrmatron<T extends IManifestNode = IManifestNode> implements IArrmatron {
  /** The component implementation this instance drives; state is projected onto it. */
  readonly $component: IComponent;
  /** Topmost instance of the tree (`this` when there is no enclosing scope). */
  readonly root: IArrmatron;
  /** Scope owning the `refId` registry this instance publishes into; `this` for a scope root. */
  readonly scope: Arrmatron;

  /** Live children by uid, rebuilt from `contentManifests` on every `touch()`. */
  __children?: Map<Uid, Arrmatron>;
  /** Memoized `get()` results for flat keys; cleared on `touch()` and invalidated per changed key. */
  __propCache?: Map<any, any>;
  /** Values injected by the parent under `LOCAL_SCOPE_PREFIX` keys (loop vars and the like). */
  __localScope?: Map<any, any>;
  /** Set by `done()`; blocks `up`/`emit` and turns the next `touch()` into a disposal pass. */
  __isDone = false;
  /** Guards the one-time branch of `settle()`. */
  __isInited = false;
  /** Last applied value per state key — the diff baseline for `up()`. */
  __fprints: Hash = {};
  /** State-change subscribers, notified at the end of each non-disposing `touch()`. */
  __listeners?: Set<(c: Arrmatron) => void>;
  /** Cleanup callbacks (unsubscribers) run once during disposal. */
  __defered?: Array<(c: IArrmatron) => void> = [];
  /** Resolved accessor per property id — the `get()` lookup is done once, then reused. */
  __propFnMap?: Map<string, Proc>;
  /** Instances registered in this scope by `refId`, looked up via `getByRef`. */
  #refs?: Hash<IArrmatron>;
  /** Remaining depth budget for `up()` -> `touch()` -> `up()` recursion; at 0 the redraw is skipped. */
  #isLocked = 10;
  /** Non-null only inside the init window of `settle()`, where `up()` accumulates instead of applying. */
  #initialState?: Delta | null;

  constructor(
    readonly platform: IPlatform,
    protected readonly manifest: T,
    private __parent?: Arrmatron,
    scope?: Arrmatron
  ) {
    defineObjectHashCodeProperty(this);

    this.scope = scope ?? this;
    this.root = scope?.root ?? this;

    const c = this.createComponent();
    defineObjectHashCodeProperty(c);
    defineObjectRef(c, ARRMATURA, this);
    this.$component = c;

    if (this.refId) {
      this.scope.addReference(this.refId, this);
    }
  }

  /** Owning instance in the tree; cleared on disposal to break the chain for GC. */
  get parent(): IArrmatron | undefined {
    return this.__parent;
  }

  /** Manifest node id — stable across re-renders, hence the key of `__children`. */
  get uid(): string {
    return this.manifest.uid;
  }

  /** Stable per-instance id, used to namespace async keys passed to `platform.applyAsyncValue`. */
  get hashCode(): string {
    return hashCodeOf(this);
  }

  /** Name this instance is published under in `scope`, if the manifest declares one (`Ref=`). */
  get refId() {
    return this.manifest.refId;
  }

  /** Human-readable tag used as the log source. */
  get displayName(): string {
    return `🔹${this.manifest.tag}`;
  }

  /** Factory hook — subclasses return a platform-specific implementation instead of the base one. */
  createComponent(): IComponent {
    return new Component();
  }

  // --- State

  /**
   * Applies a state delta to the component and re-renders if anything actually changed.
   *
   * Handling per entry:
   * - a `Promise` value (or a promised delta) is deferred through `platform.applyAsyncValue`;
   *   an empty or `"..."` key spreads the resolved delta, any other key wraps it as `{ key: value }`
   * - keys starting with `"$"` are skipped as non-state
   * - remaining keys are diffed against `__fprints`; only changed ones reach the component
   *
   * Calls during the `settle()` init window are merged into the pending initial state instead.
   *
   * @param delta - Values to apply; ignored when empty or once the instance is done.
   * @param force - Re-render even when the diff is empty (used after init and for parents with children).
   */
  up(delta?: Delta | Promise<Delta> | null, force = false) {
    if (!delta || this.__isDone) {
      return;
    }
    if (this.#initialState) {
      // accumulate into initialState
      Object.assign(this.#initialState, delta);
      return;
    }
    if (delta instanceof Promise) {
      this.platform.applyAsyncValue(`${this.hashCode}:set`, delta, (val) => this.up(val));
      return;
    }

    const changes = new Map<string, unknown>();

    Object.entries(delta).forEach(([k, v]) => {
      if (v instanceof Promise) {
        const isSpreading = !k || k.startsWith("...");
        this.platform.applyAsyncValue<Delta>(`${this.hashCode}:set:${k}`, v, (val) => {
          this.up(isSpreading ? val : { [k]: val });
        });
        return;
      }

      if (!k || k[0] === "$") return;

      if (!(k in this.__fprints) || !isEquals(this.__fprints[k], v)) {
        this.__fprints[k] = v;
        changes.set(k, v);
        this.__propCache?.delete(k);
      }
    });

    if (changes.size || force) {
      // this.log("changes", changes);
      applyStateChangedToImpl(changes, this.$component);
      if (this.#isLocked) {
        this.#isLocked--;
        this.touch();
        this.#isLocked++;
      }
    }
  }

  /**
   * Reads a component value by property id, resolving the accessor once and reusing it afterwards.
   *
   * Resolution order, first match wins:
   * 1. a method on the component — returned bound to it
   * 2. `"This"` — the component itself
   * 3. `"R.<path>"` — a platform resource
   * 4. a `get<Name>()` getter (or the plain `<name>` field when the getter is not a function)
   * 5. `__getStateProperty(propId)` when the component defines it
   * 6. the plain field
   *
   * Dot-separated paths are traversed left to right, missing links yielding `null`. They are logged as
   * an error and are NOT cached — only flat keys land in `__propCache`, since only those can be
   * invalidated by `up()`.
   *
   * @param propId - Property id or dotted path.
   * @returns The resolved value, or `null` for an empty id or a missing link.
   */
  get(propId: string): unknown {
    if (!propId) return null;

    let pk: string;
    let path: string[];
    if (propId.indexOf(".") === -1) {
      // fast path: flat key, no split/cache needed
      pk = propId;
      path = EMPTY_PATH;
    } else {
      let splittedKeys = SPLITTED_KEYS.get(propId);
      if (!splittedKeys) {
        splittedKeys = propId.split(".");
        SPLITTED_KEYS.set(propId, splittedKeys);
      }
      [pk, ...path] = splittedKeys;
    }

    const cacheable = path.length === 0;

    if (cacheable) {
      if (this.__propCache?.has(propId)) {
        return this.__propCache.get(propId);
      }
    } else {
      this.log("ERROR: Nested key", propId);
    }

    const map = this.__propFnMap ?? (this.__propFnMap = new Map());
    if (map.has(propId)) {
      const val = map.get(propId)();
      if (cacheable) {
        const cache = this.__propCache ?? (this.__propCache = new Map());
        cache.set(propId, val);
      }
      return val;
    }

    let fn: Fn | null = null;
    const impl = this.$component;
    const instant = impl[propId];

    if (instant && typeof instant === "function") {
      const bound = instant.bind(impl);
      fn = () => bound;
    } else if (propId === "This") {
      fn = () => this.$component;
    } else {
      if (pk === "R") {
        const val = this.platform.getResource(path) ?? null;
        fn = () => val;
      } else if (`get${capitalize(pk)}` in impl) {
        const gettr = impl[`get${capitalize(pk)}`];
        const fn0 = typeof gettr === "function" ? () => gettr.call(impl) ?? null : () => impl[pk] ?? null;
        fn = !path.length ? fn0 : () => path.reduce((r, p) => r?.[p] ?? null, fn0());
      } else if (impl.__getStateProperty) {
        fn = () => impl.__getStateProperty?.(propId);
      } else {
        const fn0 = () => impl[pk] ?? null;
        fn = !path.length ? fn0 : () => path.reduce((r, p) => r?.[p] ?? null, fn0());
      }
    }

    map.set(propId, fn);

    const val = fn();

    if (cacheable) {
      const cache = this.__propCache ?? (this.__propCache = new Map());
      cache.set(propId, val);
    }

    return val;
  }

  /** Publishes a value visible only to this subtree under a `LOCAL_SCOPE_PREFIX` key. */
  putInLocalScope(propId: string, val: unknown) {
    (this.__localScope ?? (this.__localScope = new Map())).set(propId, val);
  }

  /** Reads either the local scope (prefixed keys) or the enclosing scope's component state. */
  getFromScope(propId: string): unknown {
    return propId.startsWith(LOCAL_SCOPE_PREFIX) ? this.__localScope?.get(propId) : this.scope.get(propId);
  }

  // --- Subscriptions.

  /** Invokes every listener; a throwing listener is logged and does not stop the rest. */
  notify() {
    this.__listeners?.forEach((fn) => {
      try {
        fn(this);
      } catch (ex) {
        this.logError(`Notification:`, ex);
      }
    });
  }

  /**
   * Subscribes to state changes of this instance.
   *
   * @returns Unsubscriber — pass it to {@link defer} to drop the listener on disposal.
   */
  addListener(handler: (src: Arrmatron) => void): Proc {
    this.__listeners ??= new Set();
    const listeners = this.__listeners;
    listeners.add(handler);
    return () => {
      listeners.delete(handler);
    };
  }

  /**
   * Listens to another instance for as long as this one lives.
   *
   * @param refId - Reference name resolved via {@link getByRef}, or the instance itself.
   * @throws When the reference cannot be resolved.
   */
  subscribeTo(refId: string | IArrmatron, fn: () => void) {
    const ref = typeof refId === "string" ? this.getByRef(refId) : refId;
    if (!ref) {
      throw new Error(`No such reference: ${refId}`);
    }
    this.defer(ref.addListener(fn));
  }

  // --- Right Arrow.

  /**
   * Dispatches an action to this or a referenced component — the runtime behind CML's `->` bindings.
   *
   * The trailing `)` picks the mode:
   * - `"ref.method()"` / `"method()"` — calls the method on the target component. A single argument is
   *   awaited through `platform.applyAsyncValue` before the call; two or more are passed as-is.
   * - `"ref.prop"` / `"prop"` — updates the target via `up({ prop: args[0] })`. Without a `ref.` part the
   *   target is this instance and the whole payload is spread over its state.
   *
   * Failures (unknown reference, missing method, throwing handler) are logged, never rethrown, so one
   * broken binding cannot abort the surrounding render.
   *
   * @param key - Action key; the part before `.` is a reference name resolved via {@link getByRef}.
   * @param args - Payload for the method call or property update.
   * @returns The method's return value in call mode, otherwise nothing.
   */
  emit(key: string, ...args: any[]) {
    if (this.__isDone) return;

    try {
      if (key.endsWith(")")) {
        let [refId, targetKey] = key.split("(")[0].split(".");

        if (!targetKey) {
          targetKey = refId;
          refId = "This";
        }

        const target = this.getByRef(refId);
        if (!target) {
          throw new Error(`No such reference: ${refId}`);
        }

        const impl = target.$component;

        const method = impl[targetKey];
        if (!(typeof method === "function")) {
          throw new Error(`Not a method: ${refId}.${targetKey}()`);
        }

        if (args.length > 1) {
          return method.apply(impl, args);
        }
        return this.platform.applyAsyncValue(`${this.hashCode}:emit:${key}`, args[0], (d) => method.call(impl, d));
      } else {
        const data = args[0] as Delta;
        let [refId, targetKey] = key.split(".");

        if (!targetKey) {
          targetKey = refId || "*";
          refId = "this";
        }

        const target = this.getByRef(refId);
        if (!target) {
          throw new Error(`No such reference: ${refId}`);
        }

        return target.up(targetKey === "*" ? data : { [targetKey]: data });
      }
    } catch (ex) {
      this.logError(`emit ${key}:`, ex);
    }
    return;
  }
  /**
   * Reconciles this instance against the manifest — the render step, run after every state change.
   *
   * 1. Drops `__propCache`, so computed values are re-read.
   * 2. Diffs `contentManifests` against `__children` by uid: gone ones are `done()`, surviving ones are
   *    reused, new ones are created, and each child is then `settle()`d.
   * 3. When done, runs the deferred cleanups and releases parent, ref, listeners and caches for GC;
   *    otherwise notifies listeners.
   * 4. Asks the platform to redraw — once, when the outermost nested call unwinds (`TOUCH_DEPTH`).
   */
  touch() {
    TOUCH_DEPTH++;
    try {
      this.__propCache?.clear();

      const nodes = !this.__isDone ? this.contentManifests : null;

      if (nodes?.size || this.__children?.size) {
        this.__children?.forEach((arrm) => {
          if (!nodes?.has(arrm.uid)) {
            arrm.done();
          }
        });

        if (nodes?.size) {
          const actualChildren = this.__children;
          this.__children = new Map();
          nodes.forEach((node: IManifestNode, uid: Uid) => {
            const existing = actualChildren?.get(uid);

            const arrm =
              existing && !existing?.__isDone
                ? existing
                : node.createArrmatron(this.platform, this, this.scopeForChildren);
            this.__children?.set(arrm.uid, arrm);
          });

          for (const arrm of this.__children.values()) {
            arrm.settle();
          }
        } else {
          this.__children = this.__children?.size === 0 ? this.__children : new Map();
        }
      }

      if (this.__isDone) {
        this.__defered?.forEach((f) => f(this));
        this.__defered = undefined;

        this.__parent = undefined;

        if (this.refId && this.scope.#refs) {
          delete this.scope.#refs[this.refId];
        }

        // cleanup to aid GC
        this.__listeners = undefined;
        this.__propFnMap = undefined;
        this.__propCache = undefined;
        this.__localScope = undefined;
      } else {
        this.notify();
      }
    } finally {
      TOUCH_DEPTH--;
      if (!TOUCH_DEPTH) {
        this.platform.redraw(this, this.root);
      }
    }
  }

  /** Disposes this instance and, through the following `touch()`, its whole subtree. */
  done() {
    this.__isDone = true;
    this.touch();
  }

  /**
   * Initializes or refreshes this instance — called by the parent's {@link touch} for every child.
   *
   * First call:
   * 1. Resolves initial props into `#initialState`, which makes concurrent `up()` calls accumulate there.
   * 2. Wires the manifest connectors: each `"sourceRef.sourceProp"` entry subscribes to the source and
   *    pushes its value through the applicator, plus one immediate push to seed the value.
   * 3. Flushes the accumulated initial state with `force`, then calls `$component.__init()`.
   *
   * Later calls just re-apply props resolved from the manifest, forcing a render when there are children
   * whose own props derive from this one.
   */
  private settle() {
    if (this.__isDone) {
      return;
    }

    if (!this.__isInited) {
      this.__isInited = true;

      this.#initialState = this.manifest.resolveInitialProps(this);

      if (this.manifest.connectors) {
        for (const [key, applicator] of this.manifest.connectors.entries()) {
          const [sourceRefId, sourcePropName] = key.split(".");

          const source = this.parent?.getByRef(sourceRefId) as Arrmatron;
          if (!source) {
            this.logError(`Connect: No such ref: ${sourceRefId}`);
            continue;
          }

          this.defer(
            source.addListener(() => {
              this.platform.applyAsyncValue(`${this.hashCode}:connect:${key}`, source.get(sourcePropName), (v) =>
                applicator(this, v)
              );
            })
          );

          // hot subscription
          this.platform.applyAsyncValue(`${this.hashCode}:connect:${key}`, source.get(sourcePropName), (v) =>
            applicator(this, v)
          );
        }
      }

      const initialState = this.#initialState;
      this.#initialState = null;
      this.up(initialState, true);

      this.$component.__init?.();
    } else {
      const delta = this.manifest.resolveProps(this);
      this.up(delta, !!this.children?.size);
    }
  }

  /** Registers a cleanup callback run once when this instance is disposed; non-functions are ignored. */
  defer(fn: (c: IArrmatron) => void) {
    if (fn && typeof fn === "function") {
      this.__defered ??= [];
      this.__defered.push(fn);
    }
  }

  // --- Content.

  /** Live children by uid, as of the last `touch()`. */
  get children(): Map<Uid, Arrmatron> | undefined {
    return this.__children;
  }

  /** Child manifests for the current state — the target `touch()` reconciles `__children` against. */
  get contentManifests() {
    return this.manifest.getSubNodes(this.platform);
  }

  /** Scope handed to children; overridden by subclasses that open a new reference scope. */
  get scopeForChildren() {
    return this.scope;
  }

  // --- Referencing.

  /**
   * Resolves a reference name, walking up the parent chain until a scope declares it.
   *
   * @param refId - Reference name; `"this"`/`"This"` resolve to this instance.
   */
  getByRef(refId: string): IArrmatron | undefined {
    if (!refId) return undefined;
    if (refId === "this" || refId === "This") {
      return this;
    }
    const local = this.#refs?.[refId];
    if (local) {
      return local;
    }
    return this.parent?.getByRef(refId);
  }

  /** Publishes an instance under `refId` in this scope; the entry is removed on disposal. */
  private addReference(refId: string, c: IArrmatron) {
    this.#refs ??= {};
    this.#refs[refId] = c;
  }

  // --- Routines -------------------------

  /** Logs through the platform, tagged with `displayName:uid`. Returns `val` so it can wrap expressions. */
  log(val: any, ...args: unknown[]) {
    this.platform.log({
      level: "log",
      source: `${this.displayName}:${this.uid}`,
      message: val,
      params: args,
    });
    return val;
  }

  /** Error counterpart of {@link log}; returns the error so it can wrap expressions. */
  logError(error: any, ...args: unknown[]) {
    this.platform.log({
      level: "error",
      source: `${this.displayName}:${this.uid}`,
      error,
      message: `${String(error.message || error)}`,
      params: args,
    });
    return error;
  }

  toString(): string {
    return stringify(this);
  }
}
