/**
 * Low-level function helpers used as expression-pipe building blocks.
 */

import type { Fn } from "../types";

// checks

/** Checks strict equality to `true`. */
export const isTrue = (x: unknown) => x === true;
/** Checks strict equality to `false`. */
export const isFalse = (x: unknown) => x === false;
/** Checks whether the value is not a number, with implicit coercion (global `isNaN`). */
// biome-ignore lint/suspicious/noGlobalIsNan: as designed
export const isNotANumber = (x: any) => isNaN(x);
/** Checks whether the value is null or undefined. */
export const isNullish = <T = unknown>(x: T): boolean => x == null;
/** Checks whether the value is undefined. */
export const isUndefined = <T = unknown>(x: T): boolean => typeof x === "undefined";

// logical

/** Returns `p` when `x` is truthy, `n` otherwise. */
export const ternaryIf = (x: unknown, p = "", n = "") => (x ? p : n);
/** Coerces the value to a boolean. */
export const truthy = (x: unknown) => !!x;
/** Logical negation. */
export const not = (x: unknown) => !x;
/** Returns `x` when truthy, `s` otherwise. */
export const or = (x: any, s: any) => x || s;
/** Returns `s` when `x` is truthy, `x` otherwise. */
export const and = (x: any, s: any) => x && s;
/** Returns `x` unless it is nullish, then `s`. */
export const coalesce = (x: any, s: any) => x ?? s;

// math

/** Returns `thenn` when `x == p` (loose equality), `elsee` otherwise. */
export const equals = (x: any, p: any, thenn: any = true, elsee: any = false) => (x == p ? thenn : elsee);
/** Returns `thenn` when `x != p` (loose inequality), `elsee` otherwise. */
export const notEquals = (x: any, p: any, thenn: any = true, elsee: any = false) => (x != p ? thenn : elsee);

/** Returns `thenn` when `x > p`, `elsee` otherwise. */
export const greater = (x: any, p: any, thenn: any = true, elsee: any = false) => (x > p ? thenn : elsee);
/** Returns `thenn` when `x < p`, `elsee` otherwise. */
export const less = (x: any, p: any, thenn: any = true, elsee: any = false) => (x < p ? thenn : elsee);
/** Checks whether `x` is within the inclusive range [a, b]. */
export const between = (x: any, a: any, b: any) => x >= a && x <= b;

/** Alias for `Math.min`. */
export const min = Math.min;
/** Alias for `Math.max`. */
export const max = Math.max;
/** Rounds the value to the nearest integer after numeric coercion. */
export const round = (x: any = 0) => Math.round(Number(x));
/** Adds `alt` (default 1) to the value after numeric coercion. */
export const increment = (x: any, alt = 1) => Number(x) + Number(alt);
/** Reduces the arguments with `+` (numeric addition or string concatenation). */
export const plus = (...args: any[]) => args.reduce((a, b) => a + b);
/** Adds two values after numeric coercion. */
export const sum = (x: any, alt: any) => +x + +alt;
/** Subtracts `alt` from `x` after numeric coercion. */
export const minus = (x: any, alt: any) => +x - +alt;
/** Multiplies two values after numeric coercion. */
export const multiply = (x: any, alt: any) => +x * +alt;
/** Divides `x` by `alt` after numeric coercion. */
export const divideBy = (x: any, alt: any) => +x / +alt;
/** Formats a number with up to 2 decimals, dropping a trailing ".00". */
export const numToFixed = (num: number): string => {
  return num.toFixed(2).replace(/\.0+$/, "");
};

// functions

/** Partially applies leading arguments to a function. */
export const fnBind = (fn: Fn, ...args: unknown[]) => fn?.bind(null, ...args);

/** Partially applies `x` as the first argument of `fn`. */
export const fnBindTo = (x: unknown, fn: Fn) => fn.bind(null, x);

/** Calls a function with the given arguments; returns undefined when `fn` is nullish. */
export const fnCall = (fn: Fn, ...args: unknown[]) => fn?.call(null, ...args);

/** Combines zero-argument functions into one returning an array of their results. */
export const fnConcat =
  (...args: Fn[]) =>
  () =>
    args.map((fn) => fn());

/** Composes unary functions right-to-left: `fnCompose(f, g)(x) === f(g(x))`. */
export function fnCompose(...ff: Array<(e: unknown) => unknown>) {
  return (x0: unknown) => ff.reduceRight((x: unknown, fn) => fn(x), x0);
}

/**
 * Throws when the value is falsy, otherwise returns it.
 *
 * @param error - Error message (wrapped in `ErrorType`) or an Error instance to throw as-is.
 */
export const assert = <T>(b: T, error: string | Error, ErrorType = Error): NonNullable<T> => {
  if (!b) {
    throw typeof error === "string" ? new ErrorType(error) : error;
  }
  return b;
};

/** Logs the value with an optional prefix (default "pipe") and returns it, for use inside pipes. */
export const log = (x: any, pre?: string) => {
  console.log(pre || "pipe", x);
  return x;
};

/**
 * Creates a debounced version of a function that runs `delay` ms after the last call.
 */
export function debounce(func: Fn, delay: number) {
  let timeoutId: ReturnType<typeof setTimeout>;
  return (...args: unknown[]) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => {
      func(...args);
    }, delay);
  };
}

/**
 * Returns a Promise that resolves after `lag` milliseconds (default 100).
 */
export function delay(lag = 100): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, Math.max(0, lag));
  });
}
