import type { Scalar } from "ultimus";

/** Frontmatter values: YAML scalars plus inline or block string lists. */
export type Frontmatter = Record<string, Scalar | null | string[]>;

export interface ParsedMarkdown {
  /** Parsed frontmatter; empty when the document carries none. */
  attrs: Frontmatter;
  /** The document with its frontmatter block removed. */
  body: string;
}

// A leading YAML frontmatter block: `---` fence, body, closing `---` fence.
const FRONTMATTER = /^﻿?---[ \t]*\r?\n([\s\S]*?)\r?\n?---[ \t]*(?:$|\r?\n(?:[ \t]*\r?\n)*)/;

// First line of the block must read as YAML — a `key:` pair or a comment.
// Guards against a document that opens with a thematic break or a setext heading.
const YAML_HEAD = /^[ \t]*(?:#|[A-Za-z_][\w.-]*[ \t]*:(?:[ \t]|$))/;

const KEY_VALUE = /^([A-Za-z_][\w.-]*)[ \t]*:[ \t]*(.*)$/;
const BLOCK_ITEM = /^-[ \t]+(.*)$/;
const QUOTED = /^(['"])([\s\S]*)\1$/;
const NUMBER = /^-?\d+(?:\.\d+)?$/;

/** Reads one YAML scalar: quoted string, null, boolean, number, or bare text. */
const scalar = (raw: string): Scalar | null => {
  const value = raw.trim();
  const quoted = QUOTED.exec(value);
  if (quoted) return quoted[2];
  if (value === "" || value === "~" || value === "null") return null;
  if (value === "true" || value === "false") return value === "true";
  return NUMBER.test(value) ? Number(value) : value;
};

/** Reads an inline list — `[math, "azon"]` — as strings. */
const inlineList = (value: string): string[] =>
  value
    .slice(1, -1)
    .split(",")
    .map((item) => String(scalar(item) ?? ""))
    .filter((item) => item !== "");

/**
 * Parses a flat YAML subset: `key: value` pairs, inline `[a, b]` lists and `- item`
 * block lists. Nested maps are out of scope — document frontmatter here is flat.
 */
const parseYaml = (yaml: string): Frontmatter => {
  const attrs: Frontmatter = {};
  let lastKey = "";
  for (const line of yaml.split(/\r?\n/)) {
    const text = line.trim();
    if (text === "" || text.startsWith("#")) continue;
    const item = BLOCK_ITEM.exec(text);
    if (item && lastKey) {
      const list = attrs[lastKey];
      attrs[lastKey] = [...(Array.isArray(list) ? list : []), String(scalar(item[1]) ?? "")];
      continue;
    }
    const pair = KEY_VALUE.exec(text);
    if (!pair) continue;
    const [, key, value] = pair;
    attrs[key] = value.startsWith("[") && value.endsWith("]") ? inlineList(value) : scalar(value);
    lastKey = key;
  }
  return attrs;
};

/**
 * Splits a leading YAML frontmatter block off a Markdown document. Frontmatter is
 * document metadata, not renderable content — left in the body it renders as a rule
 * plus stray text; parsed out, it becomes attributes of the document node.
 */
export const parseFrontmatter = (md: string): ParsedMarkdown => {
  const match = FRONTMATTER.exec(md);
  return match && YAML_HEAD.test(match[1])
    ? { attrs: parseYaml(match[1]), body: md.slice(match[0].length) }
    : { attrs: {}, body: md };
};
