import { assert, capitalize, type Delta, type Hash, type StringHash } from "ultimus";
import { WebClientService } from "@/core";
import type { IndexedDbService } from "./IndexedDbService";

const MAX_FILE_SIZE = 50 * 1024 * 1024; // 50MB

/**
 * DataApiService
 *
 */
export class DataApiService extends WebClientService {
  trigger: unknown;
  localDb?: IndexedDbService;
  name = "dataApi";
  remote?: any;

  error?: any;
  busy = false;

  isSignUpAllowed = false;

  get isLoaded() {
    return this.storage.get(`isLoaded`) ?? false;
  }

  set isLoaded(s) {
    this.storage.set(`isLoaded`, !!s);
  }

  get since() {
    return this.storage.get(`since`) ?? 0;
  }

  set since(s) {
    this.storage.set(`since`, s || 0);
  }

  invokeApi(body): Promise<any> {
    return assert(this.remote, "No remote service").invokeApi(body);
  }
  /**
   * Run validation on a subtree starting from given node.
   */
  async invokeAction({ action, toast = true, noSync = false, busyKey = `busy${capitalize(action)}`, ...params }) {
    const busy = 1 + (this[busyKey] ?? 0);
    this.up({ [busyKey]: busy, busy });
    try {
      const { toastMessage = toast, ...result } =
        (await this.invokeApi({
          action,
          ...params,
        })) ?? {};
      // Refresh data after validation
      if (!noSync) {
        await this.downstream();
      }
      const busy = -1 + (this[busyKey] ?? 0);
      this.up({ [busyKey]: busy, busy });
      if (toastMessage) {
        this.toast({
          level: "info",
          message: toastMessage === true ? `${capitalize(action)} completed` : toastMessage,
        });
      }
      return result;
    } catch (error: any) {
      this.toast({ level: "error", message: error.message || `Action ${action} failed` });
      const busy = -1 + (this[busyKey] ?? 0);
      this.up({ [busyKey]: busy, busy });
      throw error;
    }
  }
  downstream(opts?: any) {
    this.up({ busy: true, error: null });

    this.invokeApi({ action: "downstream", since: this.since, ...opts })
      .then(async (result = {}) => {
        const { data, bundle = data, since, next } = result;
        await this.localDb?.batchUpsert(bundle);

        this.since = since;

        this.log(`downstream ${this.refId} since`, since);

        if (next) {
          this.up({ isLoaded: true });
          return this.downstream(next);
        }

        this.up({ busy: false, isLoaded: true, isOutdated: false });
      })
      .catch((error) => {
        const message = String(error?.message || error || "unknown error");
        const code = Number(error?.code || -1);

        if (code === 403 || message.toLowerCase() === "unauthorized") {
          this.resetDb();
          this.signOut();
        }

        this.toast({ id: message, level: "error", message: `downstream: ${message}` });

        this.up({ busy: false, isLoaded: true, isOutdated: true, error: message });
      });
  }

  dbQuery(params: Delta) {
    return this.localDb?.query(params);
  }

  async loadObject({ callback, id, store }: Delta) {
    this.up({ isOutdated: true, busy: true, loadError: null });

    try {
      const itemRemote = await this.invokeApi({
        action: "getObject",
        id,
        store,
      });

      let item = await this.localDb?.getObject({ id, store });

      if (itemRemote) {
        item = { ...item, ...itemRemote };
        await this.localDb?.upsertObject({ ...item, store, ts: itemRemote.ts });
      }

      await callback?.({ item });

      this.up({ busy: false, isOutdated: false });

      return item;
    } catch (error: any) {
      const message = String(error?.message || error || "unknown error");
      const item = await this.localDb?.getObject({ id, store });
      await callback?.({ error, item });
      this.up({ busy: false, loadError: message });
    }
  }

  async upsertObject({ callback = null, store, ...params }: any, storeDef?: string) {
    this.up({
      isOutdated: true,
      busy: true,
      hasUploaded: false,
      isUploading: true,
      uploadError: null,
    });
    try {
      const item = await this.invokeApi({ action: "upsertObject", ...params, store: store || storeDef });

      await this.localDb?.upsertObject(item);

      this.log(`upsertObject ${item.store}`, item);

      await callback?.({ item });

      this.up({ busy: false, isUploading: false, isOutdated: false, hasUploaded: true });

      return item;
    } catch (error: any) {
      const message = String(error?.message || error || "unknown error");

      this.toast({ id: message, level: "error", message });

      await callback?.({ error });

      this.up({ busy: false, isUploading: false, uploadError: message });

      return null;
    }
  }

  async setField(event: Delta | string, defId?: string, defField?: string, val?: any) {
    if (typeof event === "string") {
      return this.setField({ store: event, id: defId, field: defField, value: val });
    }

    const { id = defId, field = defField, value: valueExpr = val, valueAdapter, store, callback } = event;
    const isCorrect = id && field && store && (valueExpr != null || valueAdapter);
    if (!isCorrect) {
      await callback?.({ error: "Not correct parameters" });
      return;
    }

    const item = await this.localDb?.getObject({ id, store });
    if (!item) {
      await callback?.({ error: `No item found: ${id}` });
      return;
    }

    const value = valueAdapter ? valueAdapter(valueExpr, item) : valueExpr;

    if (item[field] === value) {
      await callback?.({ item });
      return;
    }

    const delta = { id: String(id), [field]: value, store };

    await this.localDb?.upsertObject(delta);

    return this.upsertObject({
      ...delta,
      callback: (arg) => {
        if (arg.error) {
          if (item) {
            // revert local update
            this.localDb?.upsertObject({ id: String(id), [field]: item[field], store }).then(() => {
              callback?.(arg);
            });
          } else {
            callback?.(arg);
          }
        } else {
          callback?.(arg);
        }
      },
    });
  }

  incrementField({ store, id, field = "counter" }) {
    this.setField({
      store,
      id,
      field,
      valueAdapter: (_, prev) => 1 + (prev[field] || 0),
    });
  }

  toggleField({ store, id, field = "active" }) {
    this.setField({
      store,
      id,
      field,
      valueAdapter: (_, prev) => !prev[field],
    });
  }

  async setFieldForItems({ ids, field, value: valueExpr, store, callback, valueAdapter }: Delta) {
    const isCorrect = ids && field && store && valueExpr != null;
    if (!isCorrect) {
      await callback?.({ error: "Not correct parameters" });
      return;
    }

    const idsArray = typeof ids === "string" ? ids.split(",") : ids;
    const items = await Promise.all(idsArray.map((id: string) => this.localDb?.getObject({ id, store })));
    const delta: any[] = [];
    for (let i = 0; i < idsArray.length; i++) {
      const item = items[i];
      if (!item) continue;
      const value = valueAdapter ? valueAdapter(valueExpr, item) : valueExpr;
      if (item[field] === value) continue;

      delta.push({ id: String(idsArray[i]), [field]: value, store });
    }

    if (delta.length === 0) {
      await callback?.({ count: 0 });
      return;
    }

    return this.upsertBatch({ [store]: delta, callback });
  }

  async upsertBatch({ callback = null, ...data }: any) {
    this.up({ isOutdated: true, busy: true, isUploading: true, upstreamError: null });

    try {
      const result = await this.invokeApi({ action: "upsertBatch", data });

      await this.downstream();

      await callback?.(result);

      this.up({ busy: false, isUploading: false, isOutdated: false });
    } catch (error: any) {
      const message = String(error?.message || error || "unknown error");

      this.toast({ id: message, level: "error", message });

      await callback?.({ error });

      this.up({ busy: false, isUploading: false, upstreamError: message });
    }
  }

  deleteObject({ id, store }: Delta) {
    return id && store ? this.setField({ id, field: "deleted", value: true, store }) : null;
  }

  deleteObjects({ ids, store }: Delta) {
    return ids?.length && store ? this.upsertBatch({ [store]: ids.map((id) => ({ id, deleted: true })) }) : null;
  }

  resetDb(needConfirm?: boolean) {
    if (needConfirm && !window.confirm("Are you sure?")) {
      return;
    }

    this.since = 0;
    return this.localDb?.deleteDatabase();
  }

  // files
  uploadFile({ file, type = "application/pdf", maxSize = MAX_FILE_SIZE }: Delta) {
    assert(this.remote, "No remote service");
    if (!file) return null;

    // Validate file size
    assert(!maxSize || file.size <= maxSize, `File size must be less than ${Math.round(maxSize / 1024 / 1024)}MB`);

    // Validate file type
    assert(!type || file.type === type, `Only '${type}' files are allowed`);

    return this.remote.uploadFile?.({ file });
  }

  openFile(params: Delta) {
    return this.remote.openFile?.(params);
  }

  // auth

  loadUser() {
    return this.invokeApi({ action: "getUser" });
  }

  upsertUser(params: Delta) {
    return this.invokeApi({ action: "upsertUser", ...params });
  }

  signIn(params: StringHash) {
    return this.remote.signIn(params);
  }

  signUp(params: Hash) {
    return this.remote.signUp(params);
  }

  async signOut() {
    await this.remote.signOut();
    return this.localDb?.deleteDatabase();
  }

  get isAuthorized() {
    return this.remote?.isAuthorized;
  }
}
