/**
 * Safely parses a JSON string; failures are swallowed with a `console.error` log (by design).
 *
 * Returns `def` when input is missing, empty, the literal string `"undefined"`, or invalid JSON.
 *
 * @param def fallback value (defaults to `{}`)
 */
export function parseJson(text?: string | null, def: unknown = {}) {
  try {
    return text && text !== "undefined" ? JSON.parse(text) : def;
  } catch (err) {
    console.error(`Error parsing JSON: ${(err as Error).message}`);
    return def;
  }
}
