import { assert } from "ultimus";
import { loadGoogleIdentity, requestGoogleAccessToken } from "./gis";
import { lookupUser, refreshIdToken, signInAsEmulatorUser, signInWithGoogleToken } from "./identity";
import type { AuthProvider, RestEndpoints, SignInOptions } from "./types";

/** What both Firebase-backed providers need to be told beyond the endpoints. */
export interface FirebaseAuthOptions {
  /** OAuth 2.0 web client id. Required in production; the emulator never uses it. */
  googleClientId?: string;
  /** Origin the IdP exchange is attributed to — `window.location.origin` in a browser. */
  requestUri: string;
}

const CLIENT_ID_HINT =
  "config.googleClientId is required for Google sign-in — take it from GCP Console -> Credentials -> Web client";

/**
 * The half that is the same whichever way the user signs in: once a Firebase session exists, it is
 * refreshed and looked up through the same two endpoints.
 */
const firebaseSession = (endpoints: RestEndpoints) => ({
  refresh: (refreshToken: string) => refreshIdToken(endpoints, refreshToken),
  lookup: (idToken: string) => lookupUser(endpoints, idToken),
});

/** Production: the Google account chooser, exchanged for a Firebase session. */
export function googleAuthProvider(endpoints: RestEndpoints, options: FirebaseAuthOptions): AuthProvider {
  const { googleClientId, requestUri } = options;

  return {
    ...firebaseSession(endpoints),
    warmUp: () => (googleClientId ? loadGoogleIdentity() : Promise.resolve(null)),
    async signIn() {
      const accessToken = await requestGoogleAccessToken(assert(googleClientId, CLIENT_ID_HINT));
      return signInWithGoogleToken(endpoints, accessToken, requestUri);
    },
  };
}

/** Local dev and e2e: the Auth emulator, which needs no credentials and no popup. */
export function emulatorAuthProvider(endpoints: RestEndpoints, { requestUri }: FirebaseAuthOptions): AuthProvider {
  return {
    ...firebaseSession(endpoints),
    // `async` so a missing email rejects like every other provider failure, rather than throwing
    // synchronously out of the call.
    signIn: async (options?: SignInOptions) =>
      signInAsEmulatorUser(
        endpoints,
        { email: assert(options?.email, "Emulator sign-in needs an email — set devUserEmail") },
        requestUri
      ),
  };
}

/** Picks the provider the resolved endpoints imply. Override the service hook to use another IdP. */
export const firebaseAuthProvider = (endpoints: RestEndpoints, options: FirebaseAuthOptions): AuthProvider =>
  endpoints.isEmulator ? emulatorAuthProvider(endpoints, options) : googleAuthProvider(endpoints, options);
