import type { Delta, Fn, Hash, Uid } from "ultimus";
import { asyncValueCall } from "ultimus";
import { compileEmitterExpression } from "../expr/compileEmitterExpression";
import { Expression } from "../expr/Expression";
import { prepareConnectedProps } from "../expr/prepareConnectedProps";
import { resolveExpression } from "../expr/resolveExpression";
import type { IArrmatron, IManifestNode, IPlatform } from "../types";
import type { Arrmatron } from "./Arrmatron";

/** Folds one attribute's current value into the delta accumulated for a render pass. */
type PropertyResolver = (c: IArrmatron, acc: Delta) => Delta;

type PropertyGetter = (c: IArrmatron) => unknown;

let COUNTER = 1;

export const identityPipe = (_, e) => e;

/**
 * The compiled form of one CML element — a template blueprint and the factory for its Arrmatrons.
 *
 * Compilation happens once per element in the source template; the resulting node is then shared by
 * every live instance of it. That split is the point of the class: attribute parsing, expression
 * compilation and connector wiring are paid once here, while each {@link createArrmatron} instance
 * only re-runs the cheap resolvers.
 *
 * Attributes compile ({@link compileAttribute}) into one of three buckets:
 * - `initialState` — constants and one-off values, applied only at init
 * - `propertyResolvers` — expressions re-evaluated on every render pass
 * - `connectors` — subscriptions to another component, pushing values in as they change
 *
 * Subclasses supply {@link EntitronConstructor} to choose the Arrmatron flavour (plain, loop, condition…).
 */
export abstract class ManifestNode implements IManifestNode {
  /** Compiled child nodes; populated by the compiler, overridden by subclasses that compute content. */
  protected $content?: Map<Uid, IManifestNode> | undefined;
  /** Globally unique id, `N<seq>:<sourceId>` — the identity children are reconciled by. */
  uid: Uid;
  /** Reference name from `Ref=`, published into the scope by the Arrmatron. */
  refId?: string;
  /** Per-render resolvers, applied in declaration order onto a shared delta. */
  readonly propertyResolvers: PropertyResolver[] = [];
  /** Init-only values, evaluated once per instance before the first render. */
  private initialState: Hash<(c: IArrmatron) => any> = {};
  /** Cross-component subscriptions keyed `"<refId>.<prop>.<seq>"`; the seq keeps duplicates distinct. */
  connectors?: Map<string, (c: IArrmatron, x: unknown) => unknown>;
  /** Source element name, used for component lookup and logging. */
  tag: any;

  constructor(xid: Uid) {
    this.uid = `N${String(COUNTER++)}:${xid}`;
  }

  /** Arrmatron class instantiated for this node — the subclass hook selecting the runtime behaviour. */
  abstract get EntitronConstructor(): new (
    platform: IPlatform,
    node: typeof this,
    parent?: Arrmatron,
    scope?: Arrmatron
  ) => Arrmatron;

  /**
   * Instantiates this node — called by the parent Arrmatron's render pass for each new child.
   *
   * @param platform - Shared platform for resources, logging and component construction.
   * @param parent - Enclosing instance; omitted only for a tree root.
   * @param scope - Scope the new instance resolves references against; defaults to itself when omitted.
   */
  createArrmatron(platform: IPlatform, parent?: Arrmatron, scope?: Arrmatron): Arrmatron {
    return new this.EntitronConstructor(platform, this, parent, scope);
  }

  /**
   * Child nodes to render for the current state — the base returns the static compiled content,
   * subclasses derive it (a loop expands per item, a condition returns one branch or nothing).
   */
  getSubNodes(_platform: IPlatform): Map<Uid, IManifestNode> | undefined {
    return this.$content;
  }

  /**
   * Compiles an expression and wires it up according to what it references.
   *
   * `@ref.prop` references become connectors — the referenced value is parked in the instance's local
   * scope and the expression re-runs when it changes. Plain property references instead add a resolver
   * re-evaluated on every render pass. An expression can do both.
   *
   * @param exprValue - Raw attribute text.
   * @param applicator - Wraps the computed value into the delta to apply (usually `v => ({ key: v })`).
   */
  bindExpression(exprValue: string, applicator: (a: any) => { [k in string]: any }) {
    const { functor, connectedPropsNames, propNames } = Expression.from(exprValue);
    if (connectedPropsNames?.size) {
      for (const [prop, key] of connectedPropsNames.entries()) {
        this.addConnector(key, (c, val) => {
          c.putInLocalScope(prop, val);
          c.up(applicator(functor(c)));
        });
      }
    }

    if (propNames?.size) {
      this.propertyResolvers.push((c: IArrmatron, delta: Delta) => {
        Object.assign(delta, applicator(functor(c)));
        return delta;
      });
    }
  }

  /**
   * Wires an interpolated attribute (one containing `{...}`) to property `k`.
   *
   * Every `@ref.prop` inside is swapped for a local-scope placeholder and backed by a connector, so the
   * value refreshes on source changes as well as on each render pass.
   */
  addConnectedPropertyResolver(v: string, k: string) {
    const { expr, props } = prepareConnectedProps(v);
    props.forEach(([prop, key]) => {
      this.addConnector(key, (c, val) => {
        c.putInLocalScope(prop, val);
        return asyncValueCall(expr(c), (v: any) => {
          c.up({ [k]: v });
        });
      });
    });
    this.propertyResolvers.push((c: IArrmatron, delta: Delta) => {
      delta[k] = expr(c);
      return delta;
    });
  }

  /**
   * Same as {@link addConnectedPropertyResolver} but for `data-*` attributes, which are merged into the
   * single `data` object rather than set as top-level properties. Non-string values skip the connector
   * path and resolve directly.
   */
  addConnectedDataPropertyResolver(v: unknown, propKey: string) {
    if (typeof v !== "string") {
      this.addDataPropertyResolver(resolveExpression(v), propKey);
    } else {
      const { expr, props } = prepareConnectedProps(v);
      props.forEach(([prop, key]) => {
        this.addConnector(key, (c, val) => {
          c.putInLocalScope(prop, val);
          return asyncValueCall(expr(c), (delta: any) => {
            c.up({ data: { ...c.get("data"), [propKey]: delta } });
          });
        });
      });
      this.addDataPropertyResolver(expr, propKey);
    }
  }

  /** Adds a resolver writing one key into the accumulated `data` object, creating it on first use. */
  private addDataPropertyResolver(getter: PropertyGetter, propKey: string) {
    this.propertyResolvers.push((c: IArrmatron, delta: Delta) => {
      const val = getter(c);
      delta.data = Object.assign((delta.data as object) || {}, {
        [propKey]: val,
      });
      return delta;
    });
  }

  /**
   * Wires a `Props=` spread: the expression yields an object whose every entry becomes a property.
   *
   * Keys seen so far are remembered on the instance as `$$propKeys` and re-emitted as `null` before each
   * update, so a key dropped from the source clears instead of lingering at its last value.
   */
  addConnectedPropertiesResolver(v: string) {
    const { expr, props } = prepareConnectedProps(v);
    props.forEach(([prop, key]) => {
      this.addConnector(key, (c, val) => {
        c.putInLocalScope(prop, val);
        return asyncValueCall(expr(c), (value: any) => {
          const keys = c.$$propKeys ?? (c.$$propKeys = {});
          Object.keys(value ?? {}).forEach((key) => (keys[key] = null));
          c.up({ ...keys, ...value });
        });
      });
    });
    this.propertyResolvers.push((c: IArrmatron, delta: Delta) => {
      const value = expr(c);
      if (value && typeof value === "object") {
        const keys = (c as any).$$propKeys ?? ((c as any).$$propKeys = {});
        Object.keys(keys).forEach((key) => (delta[key] = null));
        Object.entries(value).forEach(([key, val]) => {
          keys[key] = null;
          delta[key] = val;
        });
      }
      return delta;
    });
  }

  /**
   * Registers a subscription to `"<refId>.<prop>"` (prop defaults to `This`).
   *
   * The stored key carries a sequence suffix, so several connectors may watch the same source property
   * without overwriting each other in the map.
   */
  addConnector(key: string, applicator: Fn) {
    const map = this.connectors ?? (this.connectors = new Map());
    const [refId, sourcePropName] = key.trim().split(".");
    const id = `${refId}.${sourcePropName || "This"}.${COUNTER++}`;

    map.set(id, applicator);
  }

  /** Builds the first delta for a new instance: the init-only values, then the regular resolvers on top. */
  resolveInitialProps(c: IArrmatron) {
    const initials = Object.entries(this.initialState).reduce((acc, [key, fn]) => {
      acc[key] = fn(c);
      return acc;
    }, {} as Hash);

    return this.resolveProps(c, initials);
  }

  /** Runs every resolver against the instance, folding the results into one delta for `up()`. */
  resolveProps(c: IArrmatron, delta = {}): Delta {
    return this.propertyResolvers.reduce((delta, resolver) => resolver(c, delta), delta);
  }

  /**
   * Classifies one source attribute and installs the machinery it needs. Dispatch order:
   *
   * - `data-*` (except `data-theme`) — merged into the `data` object
   * - `Ref` — records {@link refId}
   * - `Props` — object spread
   * - non-string, or `'quoted'` — a literal, evaluated once at init
   * - `@ref` — the referenced component itself; `@ref.prop` — a bound expression
   * - `->` — an event emitter compiled into a handler
   * - text containing `{...}` — an interpolated, re-resolved expression
   * - anything else — a plain string constant
   */
  compileAttribute(k: string, v: unknown) {
    if (k.startsWith("data-") && k !== "data-theme") {
      this.addConnectedDataPropertyResolver(v, k.slice(5));
    } else if (k === "Ref") {
      this.refId = String(v);
    } else if (k === "Props") {
      this.addConnectedPropertiesResolver(String(v));
    } else {
      if (typeof v !== "string") {
        this.initialState[k] = () => v;
      } else if (v[0] === "'" && v.at(-1) === "'") {
        const v0 = v.slice(1, -1);
        this.initialState[k] = () => v0;
      } else {
        if (!v.includes("{")) {
          if (v.startsWith("@")) {
            const [refId, prop] = v.slice(1).trim().split(".");
            if (!prop) {
              this.initialState[k] = (c) => c.getByRef(refId)?.$component;
            } else {
              this.bindExpression(v, (v) => ({ [k]: v }));
            }
          } else if (v.startsWith("->")) {
            this.initialState[k] = compileEmitterExpression(v.slice(2).trim(), this);
          } else {
            this.initialState[k] = () => v;
          }
        } else {
          this.addConnectedPropertyResolver(v, k);
        }
      }
    }
  }

  /** Compiles every attribute of the source element; a missing map is a no-op. */
  compileAttributes(attrs?: Hash) {
    if (attrs) {
      Object.entries(attrs).forEach((keyValue) => this.compileAttribute(...keyValue));
    }
  }
}
