import { strTrim } from "ultimus";
import { WebClientService } from "@/core";
import { errorText, loadMermaid, renderDiagram } from "./utils/mermaidRender";

/**
 * Renders one ```mermaid block into the `<pre>` its MDMermaid component owns.
 *
 * Every exit path reports itself: `done` clears the spinner, `error` shows the message under the diagram.
 * A blank box with neither is a bug, not a state.
 *
 * `done` is false-by-default on purpose: an `If` on a sibling element is evaluated before this service
 * is registered, so `@mermaidService.<flag>` reads `undefined` on the first pass. Only a negated
 * condition (`If="!@mermaidService.done"`) can therefore render anything before the first update.
 */
export class MarkdownMermaidService extends WebClientService {
  plain: string = "";
  declare elt: any;
  eltId: string = "";
  done: boolean = false;
  error: string = "";

  async __init() {
    const domElt = this.elt?.$dom;
    const source = strTrim(this.plain);

    if (!domElt) {
      this.up({ done: true, error: `No target element for diagram "${this.eltId}"` });
      return;
    }
    if (!source) {
      this.up({ done: true, error: "The diagram source is empty" });
      return;
    }

    try {
      const mermaid = await loadMermaid();
      const { svg, bindFunctions } = await renderDiagram(mermaid, source, this.eltId);
      domElt.innerHTML = svg;
      bindFunctions?.(domElt);
      this.up({ done: true, error: "" });
    } catch (err) {
      this.up({ done: true, error: errorText(err) });
    }
  }
}
