import type { Data, Hash } from "ultimus";
import * as libs from "ultimus";
import { mapEntries, mergeObject } from "ultimus";
import type { IArrmatron, IPlatform } from "../types";
import { Registry } from "./Registry";

/**
 * Basic platform implementation — the environment every component tree shares.
 *
 * On top of the {@link Registry} it adds the app-wide resource bag (strings, config, enums, functions),
 * logging, and async value resolution. It is deliberately headless: {@link redraw} does nothing, so this
 * class serves tests and non-visual runs, while a DOM platform subclasses it to paint.
 *
 * One instance exists per running app and is reachable from any component as `this.platform`.
 */
export class Platform extends Registry implements IPlatform {
  /** App-wide resource tree, read through `R.` property paths in templates. */
  readonly resources: Hash<any> = {};

  constructor(resources: any) {
    super();
    this.updateResources(resources);
  }

  /** Render hook, called once per settled update — a no-op here, overridden by visual platforms. */
  redraw(_: IArrmatron, _root: IArrmatron) {}

  /**
   * Merges a resource bundle into {@link resources}, deep-merging rather than replacing.
   *
   * Keys are interpreted, not just stored:
   * - a leading `$` marks a key as private and skips it
   * - `NativeElement` swaps the native element class
   * - `components` / `Components` registers component types and drops their cached templates
   * - a dotted key writes into a nested path, creating the intermediate objects
   */
  updateResources(delta: any) {
    mapEntries(delta, (key, value) => {
      if (key[0] === "$") return;
      if (key === "NativeElement") {
        this.NativeElement = value;
        return;
      }
      if (key === "components") {
        this.registerTypes(value);
        return;
      }

      const keys = key.split(".");
      if (keys.length > 1) {
        const last = keys.pop() ?? "-";
        const target = keys.reduce<Hash>((r, e) => r[e] ?? (r[e] = {}), this.resources);
        target[last] = mergeObject(target[last], value);
        return;
      }
      this.resources[key] = mergeObject(this.resources[key], value);
    });
  }

  /**
   * Reads a resource by dotted path or path segments; an empty id returns the whole tree.
   *
   * @returns The value, or a nullish result when any segment is missing — lookups never throw.
   */
  getResource(key: string | string[]): Data {
    const [id, ...deep] = typeof key === "string" ? key.split(".") : key;
    const { resources } = this;
    const target = id ? resources[id] : resources;
    if (!target || deep.length === 0) {
      return target;
    }
    if (deep.length === 1) {
      return target[deep[0]];
    }
    return deep.reduce((r, k) => (r ? r[k] : null), target);
  }

  /**
   * Resolves a function usable inside template expressions.
   *
   * The whole `ultimus` toolkit is exposed by name and takes precedence; app-supplied
   * `resources.functions` fill the rest — so an app helper cannot shadow a library one.
   */
  getFunction(id: string): (...args: any[]) => any {
    return ((libs as Hash)[id] || this.resources.functions?.[id]) as unknown as (...args: any[]) => any;
  }

  /**
   * Applies a value that may or may not be a promise, calling `fn` synchronously when it is not.
   *
   * The synchronous path matters: most values are already resolved, and routing them through a promise
   * would defer every state update by a microtask.
   *
   * `_key` identifies the logical slot being filled (`"<hash>:set:<prop>"` and the like) so that
   * overlapping updates to it can be de-duplicated. This base implementation ignores it and applies
   * every result, meaning a slow promise may land after a newer one; `WebPlatform` overrides the method
   * to drop such stale results.
   *
   * @param _key - Slot identifier, unused here — see the override for its purpose.
   * @param promiseOrValue - Value to apply, awaited only if it is a promise.
   * @param fn - Receives the resolved value.
   */
  applyAsyncValue<T = unknown>(_key: string, promiseOrValue: T | Promise<T>, fn: (val: T) => void) {
    if (promiseOrValue instanceof Promise) {
      return promiseOrValue.then((v) => fn(v));
    }
    return fn(promiseOrValue);
  }
}
