import type { Delta } from "ultimus";
import type { IArrmatron, IComponent } from "../types";
import { defineCalculatedProperty } from "../utils/defineCalculatedProperty";
import { ARRMATURA } from "./consts";

/**
 * Base component — the class app-level services and UI components extend.
 *
 * A component holds no machinery of its own: it is paired 1:1 with an {@link Arrmatron} that owns its
 * state, children and lifecycle, and every method here forwards to that owner through {@link $$}.
 * State arrives as plain fields written by `Arrmatron.up()`, so a component reads `this.someProp`
 * directly and must publish changes back via `this.up({...})` rather than assigning fields.
 *
 * Subclasses typically override {@link __init} and add methods that CML reaches through `->` bindings.
 */
export class Component implements IComponent {
  /** Optional instance label, used only to disambiguate `toString()` output. */
  name;

  /** The owning Arrmatron, installed as a hidden back-reference when it constructs this component. */
  get $$() {
    return this[ARRMATURA] as IArrmatron;
  }

  /** Uid of the manifest node behind this component. */
  get $uid() {
    return this.$$.uid;
  }

  /** Component of the enclosing node, or `undefined` at the root / after disposal. */
  get $parentComponent() {
    return this.$$.parent?.$component;
  }

  /** Name this component is published under (CML `Ref=`), if any. */
  get refId() {
    return this.$$.refId;
  }

  /** Shared platform — resources, logging, component registry, async resolution. */
  get platform() {
    return this.$$.platform;
  }

  /**
   * Lifecycle hook, called once after the initial props are applied and before the first render.
   *
   * This is the only mount-time hook — the framework has no separate DOM-mount event, so one-shot
   * setup (subscriptions, initial fetches, timers) belongs here. Pair anything disposable with
   * {@link defer}.
   */
  __init(): void {
    // implement your logic here
  }

  /** Reads a property through the owner's resolution rules (getters, `R.` resources, dotted paths). */
  get(key: string) {
    return this.$$.get(key);
  }

  /**
   * Applies a state delta and triggers a re-render — the only supported way to mutate state.
   *
   * Direct field assignment bypasses the diff in `Arrmatron.up()`, leaving `__fprints` stale and the
   * change invisible to the render pass, even for a single field.
   */
  up(d) {
    return this.$$.up(d);
  }

  /** Forces a re-render without a state change; needed after mutating an object in place. */
  touch() {
    return this.$$.touch();
  }

  /** Resolves another component by reference name, searching this scope then upwards. */
  getComponentByRef(refId: string) {
    return this.$$.getByRef(refId)?.$component;
  }

  /** Calls a method or updates a property on this or a referenced component; failures are logged. */
  emit(key: string, data: Delta = {}) {
    return this.$$.emit(key, data);
  }

  /** Re-renders this component whenever the referenced one changes; auto-unsubscribed on disposal. */
  subscribeTo(refId: string, fn: () => void) {
    return this.$$.subscribeTo(refId, fn);
  }

  /** Registers a cleanup callback run when this component is disposed. */
  defer(fn: () => void) {
    this.$$.defer(fn);
  }

  /**
   * Defines a lazily computed property that recomputes only when its dependencies change.
   *
   * Dependency values are read via {@link get} on each access and compared by hash, so `fn` re-runs
   * only on a real change. If any dependency resolves to a promise the property yields a promise too,
   * and results of superseded reads are discarded rather than resolving out of order.
   *
   * @param key - Property name to define on this instance.
   * @param fn - Computation, called with the resolved dependency values in order.
   * @param deps - Property ids to depend on; with none, `fn` runs once and the result is kept.
   */
  __defineCalculatedProperty(key, fn: (...args: any[]) => any, deps?: string[]) {
    defineCalculatedProperty(this, key, fn, deps);
  }

  /**
   * Bulk form of {@link __defineCalculatedProperty}, keyed by a `"name(dep1, dep2)"` signature.
   *
   * The parentheses are required — a bare `"name"` key has no dependency list to parse and throws.
   */
  __defineCalculatedProperties(bundle: Record<string, (...args: any[]) => any>) {
    Object.entries(bundle).forEach(([signature, fn]) => {
      const [key, depsString] = signature.split("(");
      const deps = depsString
        ?.slice(0, -1)
        .split(",")
        .map((s) => s.trim());

      this.__defineCalculatedProperty(key, fn, deps);
    });
  }

  /** Logs through the platform, tagged with this component's identity. Returns `val` for inline use. */
  log(val: unknown, ...args: unknown[]) {
    this.$$.log(val, ...args);

    return val;
  }

  /** Error counterpart of {@link log}; returns the error for inline use. */
  logError(error: unknown, ...args: unknown[]) {
    this.$$.logError(error, ...args);

    return error;
  }

  /** Debug label: the owner's identity plus {@link name} when set. */
  toString() {
    return `${this.$$.toString()}${this.name ? `(${this.name})` : ""}`;
  }
}
