import { OPS } from "./operations";
import type { ParserContext } from "./ParserContext";

export class ExpressionParserBase {
  input: string;
  private position: number = 0;
  length = 0;

  constructor(
    input: string,
    protected ctx: ParserContext
  ) {
    this.input = input.trim();
    this.length = this.input.length;
  }

  checkIf(testString: string): boolean {
    return this.input.startsWith(testString, this.position);
  }
  checkIfNum(): boolean {
    return /[0-9+-]/.test(this.input[this.position]);
  }
  checkExceeded() {
    if (this.position !== this.length) {
      this.throw("Unexpected end of expression");
    }
  }

  consumeIf(testString: string): boolean {
    if (!this.checkIf(testString)) return false;

    this.position += testString.length;
    return true;
  }

  throw(message: string): boolean {
    throw new Error(`${message} in '${this.input.slice(0, this.position)}<<<<${this.input.slice(this.position)}'`);
  }

  consume(testString: string): boolean {
    if (!this.consumeIf(testString)) {
      this.throw(`Expected expression '${testString}' at position ${this.position}`);
    }

    return true;
  }

  consumeWhitespace(): void {
    while (this.position < this.length && /\s/.test(this.input[this.position])) {
      this.position++;
    }
  }

  parseLeftRight(ops: Array<keyof typeof OPS>, leftKey, rightKey): any {
    const left = this[leftKey]();

    for (let index = 0; index < ops.length; index++) {
      const op = ops[index];
      this.consumeWhitespace();
      if (this.consumeIf(op)) {
        this.consumeWhitespace();
        const right = this[rightKey]();
        const fn = OPS[op];
        return { type: op, left, right, fn: (c, ev) => fn(left.fn(c, ev), right.fn(c, ev)) };
      }
    }

    return left;
  }

  parseString(): any {
    const quote = this.input[this.position];
    let value = "";
    this.position++;

    while (this.position < this.input.length && this.input[this.position] !== quote) {
      value += this.input[this.position];
      this.position++;
    }

    if (this.input[this.position] === quote) {
      this.position++;
    }

    return { type: "String", value, fn: () => value };
  }

  parseNumber(): any {
    let value = "";
    if (this.position < this.input.length && /[0-9.+-]/.test(this.input[this.position])) {
      value += this.input[this.position];
      this.position++;
    }

    while (this.position < this.input.length && /[0-9.]/.test(this.input[this.position])) {
      value += this.input[this.position];
      this.position++;
    }

    const num = parseFloat(value);

    return { type: "Number", value: num, fn: () => num };
  }

  parseIdentifier(): any {
    let name = "";
    while (this.position < this.input.length && /[a-zA-Z0-9_$-]/.test(this.input[this.position])) {
      name += this.input[this.position];
      this.position++;
    }
    if (name === "it" || name === "event") {
      return { type: "Event", name, fn: (_c, ev) => ev };
    }
    if (name.startsWith("R.")) {
      return { type: "Resource", name, fn: (c) => this.ctx.resolveIdentifier(c, name) };
    }
    this.ctx.propNames.add(name);
    return { type: "Identifier", name, fn: (c) => this.ctx.resolveIdentifier(c, name) };
  }
}
