import { arraySortBy } from "./arraySortBy";

type ListNode = {
  id: string | number;
  _next?: string | number | null;
  _first?: boolean;
  [key: string]: any;
};

/**
 * Orders nodes into a single linked-list chain: starts at the `_first` node (or lowest `position`),
 * follows `_next` ids, then appends unlinked nodes. Mutates nodes to repair `_first`/`_next` links;
 * the last node gets `_next: null`.
 */
export const arrayToOrderedList = (arr: ListNode[] = []): ListNode[] => {
  // Filter out falsy values
  const filtered = arraySortBy(arr.filter(Boolean), "position");
  if (!filtered.length) return [];

  const index: Record<string, ListNode> = {};
  const added = new Set<ListNode>();
  const result: ListNode[] = [];

  // Determine the head (explicit _first or default to first element)
  let head: ListNode = filtered[0];
  for (const node of filtered) {
    if (node._first) {
      head = node;
    }
    index[String(node.id)] = node;
  }

  head._first = true;

  // Traverse from head following _next links
  let current: ListNode | undefined = head;
  while (current && !added.has(current)) {
    result.push(current);
    added.add(current);
    const nextId = current._next;
    current = nextId != null ? index[String(nextId)] : undefined;
  }

  // Append remaining nodes not in the initial chain
  let prev: ListNode = result[result.length - 1] || head;
  for (const node of filtered) {
    if (!added.has(node)) {
      prev._next = node.id;
      result.push(node);
      added.add(node);
      prev = node;
    }
  }

  // Ensure the last node ends the chain
  if (result.length) {
    result[result.length - 1]._next = null;
  }

  return result;
};
