import { gettusFn } from "../object/gettus";
import { arraySortBy } from "./arraySortBy";

type Obj<T = unknown> = Record<string, T>;

type GroupOf<T> = {
  id: string;
  name: string;
  count: number;
  items: T[];
};

/**
 * `arrayGroupBy` as a sorted array of groups rather than a hash — the form templates iterate.
 *
 * @param sortBy - property to order the groups by (default "name"); passed through to `arraySortBy`
 * @returns an array of `{ id, name, count, items }`, or a Promise of one when given a Promise
 */
export const arrayGroupedBy = <T extends object = object>(
  list: T[] | Promise<T[]> | null | undefined,
  field: string | string[] | ((e: T) => unknown) = "type",
  sortBy?: string
) => {
  if (!list || !field) return list ?? [];
  if (list instanceof Promise) return list.then((r) => arrayGroupedBy(r, field));
  const obj = arrayGroupBy(list, field);
  return arraySortBy(Object.values(obj), sortBy);
};

/**
 * Groups list items by a field, returning a hash of `{ id, name, count, items }` groups keyed by group id.
 *
 * @param field - property name, dot-path/array path, or extractor function (default "type")
 * @param result - optional target object to merge the groups into
 * @example
 * arrayGroupBy([{ id: 1, type: "a" }, { id: 2, type: "b" }, { id: 3, type: "a" }])
 * // { a: { id: "a", name: "a", count: 2, items: [...] }, b: { ..., count: 1 } }
 */
export const arrayGroupBy = <T extends object = object>(
  list: T[] | null | undefined,
  field: string | string[] | ((e: T) => unknown) = "type",
  result: Obj<GroupOf<T>> = {}
) => {
  const groups = new Map<unknown, T[]>();

  const iter = (id: unknown = "", entry: T) => {
    const items = groups.get(id);
    if (items) {
      items.push(entry);
    } else {
      groups.set(id, [entry]);
    }
  };

  const get = gettusFn(field);

  list?.forEach?.((e: T) => iter(get(e), e));

  groups.forEach((items, id) => {
    result[id as string] = { id: id as string, name: id as string, count: items.length, items };
  });

  return result;
};
