export const fnFalse = () => false;
export const fnTrue = () => true;
export const fnNull = () => null;
export const fnAnd = (a, b) => a && b;
export const fnOr = (a, b) => a || b;
export const fnPlus = (a, b) => a + b;
export const fnUndefined = () => undefined;
export const fnNot = (a) => !a;
export const fnEqual = (a, b) => a === b;
export const fnNotEqual = (a, b) => a !== b;
export const fnLessThan = (a, b) => a < b;
export const fnLessThanOrEqual = (a, b) => a <= b;
export const fnGreaterThan = (a, b) => a > b;
export const fnGreaterThanOrEqual = (a, b) => a >= b;
export const fnMinus = (a, b) => a - b;
export const fnMultiply = (a, b) => a * b;
export const fnDivide = (a, b) => a / b;
export const fnModulo = (a, b) => a % b;
export const fnExponent = (a, b) => a ** b;
export const fnStrictEqual = (a, b) => a === b;
export const fnCoalesce = (a, b) => a ?? b;

export const dot = (x: any, k = "name", pattern?: string, def: any = null) =>
  x?.[pattern ? strEnhance(k, pattern, def) : k] ?? def;

export var strEnhance = (x, template, def) => {
  return !x ? "" : `${template || "*"}`.replace("*", x ?? def ?? "");
};

export const OPS = {
  "&&": fnAnd,
  AND: fnAnd,
  "||": fnOr,
  OR: fnOr,
  "!": fnNot,
  "==": fnEqual,
  "===": fnStrictEqual,
  "!=": fnNotEqual,
  "<": fnLessThan,
  LT: fnLessThan,
  ">": fnGreaterThan,
  GT: fnGreaterThan,
  GTE: fnGreaterThanOrEqual,
  "<=": fnLessThanOrEqual,
  ">=": fnGreaterThanOrEqual,
  "+": fnPlus,
  "-": fnMinus,
  "*": fnMultiply,
  "/": fnDivide,
  "%": fnModulo,
  "**": fnExponent,
  "??": fnCoalesce,
};
