import type { Delta, Hash, Op } from "ultimus";
import { parseJson } from "ultimus";
import type { PersistenceType } from "../types";
import { MemoryStore } from "./MemoryStore";

export class ClientStorage {
  cache: Hash = {};
  scache: Hash<string | null> = {};
  storage: Omit<MemoryStore, "prototype">;

  static clearAll() {
    window.localStorage.clear();
    window.sessionStorage.clear();
  }

  constructor(
    mode?: PersistenceType,
    readonly ns = ""
  ) {
    this.storage =
      mode === "local" ? window.localStorage : mode === "session" ? window.sessionStorage : new MemoryStore();
  }

  get prefix() {
    return this.ns ? `${this.ns}:` : "";
  }

  clear() {
    this.cache = {};
    return this.storage.clear();
  }

  get(key: string) {
    if (key in this.cache) return this.cache[key];
    this.scache[key] = this.storage.getItem(`${this.prefix}${key}`);
    const value = parseJson(this.scache[key], null);
    this.cache[key] = value;
    return value;
  }

  set(key: string, val: unknown) {
    if (this.cache[key] === val) return;

    const sval = JSON.stringify(val);
    if (this.scache[key] === sval) return;

    this.cache[key] = val;
    this.scache[key] = sval;

    if (val != null) {
      this.storage.setItem(`${this.prefix}${key}`, sval);
    } else {
      this.storage.removeItem(`${this.prefix}${key}`);
    }
  }

  assign(delta: Delta) {
    Object.entries(delta).forEach(([key, val = null]) => this.set(key, val));
  }

  transform(key: string, fn: Op) {
    return this.set(key, fn(this.get(key)));
  }
}
