import { Component } from "arrmatura";
import type { Hash } from "ultimus";
import { objectFreeze } from "ultimus";
import { FilterField } from "./FilterField";

export class ItemsFilterController extends Component {
  filterPredicat = (item: Hash) => {
    for (const fields of this.fields) {
      if (!fields.matched(item)) return false;
    }
    return true;
  };
  value: any;
  $fields: FilterField[] | null = null;
  constructor() {
    super();

    this.__defineCalculatedProperties({
      "$fields(meta)": (meta) => {
        return meta ? [...(meta as any[])].map((e) => new FilterField(this, { ...e, isSelected: false })) : null;
      },
      "actualData(data,fields)": (data) => {
        return data ? objectFreeze(data.filter(this.filterPredicat)) : null;
      },
    });
  }

  get fields() {
    return this.$fields || [];
  }

  get selectedFields() {
    return this.fields.filter((e) => e.isSelected);
  }

  get isEmpty() {
    return !this.fields.some((e) => !e.isEmpty);
  }

  get hasSelectedFields() {
    return !!this.selectedFields.length;
  }

  get navParams() {
    return this.fields.reduce((value, ff) => {
      const keys = Object.keys(ff.selections);
      value[`filter_${ff.id}`] = keys.length === 0 ? "" : keys.length === 1 ? keys[0] : ff.selections;
      return value;
    }, {});
  }

  set initialValue(value) {
    this.value = value ?? {};
    this.fields.forEach((ff) => {
      const selections = Object.keys(value?.[`filter_${ff.id}`] ?? {});
      ff.settleOption(selections);
      ff.setIsSelected(selections.length > 0);
    });
  }

  toggleField(id: string) {
    const field = this.fields.find((ff) => ff.id === id);
    field?.setIsSelected(!field.isSelected);
    this.touch();
  }

  settleFieldOptions(value) {
    this.value = value ?? {};
    this.fields.forEach((field) => {
      const optionId = value?.[`filter_${field.id}`];
      if (optionId) {
        field?.settleOption(optionId);
      } else {
        field?.setIsSelected(false);
      }
    });
    this.touch();
  }

  setFieldPattern({ value, fieldId }) {
    const field = this.fields.find((ff) => ff.id === fieldId);
    field?.setPattern(value);
    this.touch();
  }

  toggleFieldOption({ optionId, fieldId }) {
    const field = this.fields.find((ff) => ff.id === fieldId);
    field?.toggleOption(optionId);
    this.touch();
  }
}
