import hljs from "highlight.js";
import { capitalize, type XmlNode } from "ultimus";
import { escapeText } from "./escapeText";

// highlight.js internal tree node shape (_emitter is not part of the public API)
type HljsTreeNode = string | { scope?: string; children: HljsTreeNode[] };

let _uid = 0;
const uid = () => `c${++_uid}`;

const HLJS_CLASSES: Record<string, string> = {
  keyword: "text-primary font-semibold",
  built_in: "text-info",
  type: "text-green-800",
  literal: "text-secondary font-semibold",
  number: "text-green-800",
  regexp: "text-error",
  string: "text-success",
  subst: "text-base-content",
  symbol: "text-secondary",
  class_: "text-green-800 font-semibold",
  function_: "text-info font-semibold",
  title: "text-primary font-semibold",
  params: "text-base-content/80",
  comment: "opacity-50 italic",
  doctag: "opacity-60 italic",
  meta: "opacity-60",
  meta_keyword: "text-primary opacity-80",
  meta_string: "text-success opacity-80",
  section: "text-primary font-bold",
  tag: "text-error",
  name: "text-primary",
  built_in_name: "text-info",
  attr: "text-green-800",
  attribute: "text-green-800",
  variable: "text-base-content",
  template_variable: "text-info",
  link: "text-primary underline",
  selector_tag: "text-error",
  selector_id: "text-green-800",
  selector_class: "text-success",
  selector_attr: "text-info",
  selector_pseudo: "text-secondary",
  addition: "text-success bg-success/10",
  deletion: "text-error bg-error/10",
};

const toXmlNodes = (node: HljsTreeNode): XmlNode[] => {
  if (typeof node === "string") {
    if (!node) return [];
    return [{ tag: "span", id: uid(), text: escapeText(node) }];
  }

  const children = node.children.flatMap(toXmlNodes);

  if (!node.scope) return children;

  const [primary] = node.scope.split(".");
  const tag = `MDCodeElt.${capitalize(primary)}`;
  const cls = HLJS_CLASSES[primary];

  return [{ tag, id: uid(), attrs: { class: cls }, nodes: children }];
};

export function highlight(code: string, lang: string): XmlNode[] {
  _uid = 0;
  const language = hljs.getLanguage(lang) ? lang : "plaintext";
  const root = (hljs.highlight(code, { language })._emitter as any).rootNode as { children: HljsTreeNode[] };
  const nodes = root.children.flatMap(toXmlNodes);
  return nodes;
}
