import { LOCAL_SCOPE_PREFIX } from "../core/Arrmatron";
import type { IArrmatron } from "../types";
import { ExpressionParser } from "./ExpressionParser";

const PCACHE = new Map<string, Expression>();

let COUNTER = 1;

const identityFunc = (_, e?) => e;

const systemFunctions = {
  $RefProp: (c: IArrmatron) => (ref, prop) => c.getByRef(ref)?.get(prop),
};

export class Expression {
  static from(x: string): Expression {
    const cached = PCACHE.get(x);
    if (cached) {
      return cached;
    }

    const ctx = new Expression();

    const prepared = x.replaceAll(/@(\w+)\.(\w+)/g, (key) => {
      const prop = `${LOCAL_SCOPE_PREFIX}C${COUNTER++}`;
      ctx.connectedPropsNames.set(prop, key.slice(1));
      return prop;
    });

    try {
      const top = new ExpressionParser(prepared, ctx).parse();

      ctx.functor = top.fn;
    } catch (error) {
      console.error(`Expression: ${x}`, error);
      throw error;
    }

    PCACHE.set(x, ctx);

    return ctx;
  }

  functor = identityFunc;

  connectedPropsNames = new Map<string, string>();
  propNames = new Set<string>();

  resolveIdentifier(c: IArrmatron, key: string) {
    return c.getFromScope(key);
  }

  getFunction(c: IArrmatron, key: string): undefined | ((...args: any[]) => any) {
    if (key[0] === "$") {
      return systemFunctions[key](c);
    }
    return c.platform.getFunction(key);
  }
}
