import { str } from "../string";
import type { Fn } from "../types";

const RE_PLACEHOLDER = /\{([^}]+)\}/g;
const TOKEN = "{$$$}";

/**
 * Compiles a template with `{expr}` placeholders into a function that evaluates each expression
 * (via `placeholderFactory`) with the call arguments and joins the results into a string.
 * Null/undefined results render as "".
 * @param placeholderFactory produces an evaluator for each trimmed placeholder expression
 * @example createStringInterpolator("Hi {name}", (expr) => (p) => p[expr])({ name: "Bob" }) // "Hi Bob"
 */
export function createStringInterpolator(template: string, placeholderFactory: (expr: string) => Fn) {
  const fnx: Fn[] = [];

  const pattern = template.replace(RE_PLACEHOLDER, (_, expr: string) => {
    fnx.push(placeholderFactory(expr.trim()));
    return TOKEN;
  });

  if (!fnx.length) return () => pattern;

  const chunks = pattern.split(TOKEN);
  const tail = chunks.pop();
  return (...args: unknown[]) => chunks.map((prefix, index) => `${prefix}${str(fnx[index](...args))}`).join("") + tail;
}
