import type { EmulatorPorts, FirebaseConfig, RestEndpoints } from "./types";

const DEFAULT_REGION = "us-central1";
const DEFAULT_FUNCTION = "api";

/** Emulator defaults, matching the ports `firebase emulators:start` uses when none are configured. */
const DEFAULT_PORTS = { auth: 9099, functions: 5001, storage: 9199 } as const;

const LOCAL_HOSTS = ["localhost", "127.0.0.1"];

/** True when the page is served from a development host, so the emulator suite is the backend. */
export function isLocalHost(hostname: string): boolean {
  return LOCAL_HOSTS.includes(hostname);
}

/**
 * Resolves every base URL the client needs, for production or for the emulator suite.
 *
 * Pure by design: the caller passes the hostname, so the whole routing decision is testable
 * without a browser.
 *
 * The Auth emulator serves both Google APIs under their own hostnames as path prefixes, which is
 * why the emulator branch keeps `identitytoolkit.googleapis.com` and `securetoken.googleapis.com`
 * in the path.
 */
export function resolveEndpoints(
  config: FirebaseConfig,
  emulatorPorts: EmulatorPorts | undefined,
  hostname: string
): RestEndpoints {
  const { apiKey, projectId, storageBucket } = config;
  const region = config.functionsRegion || DEFAULT_REGION;
  const functionName = config.functionsName || DEFAULT_FUNCTION;
  const bucket = storageBucket || `${projectId}.firebasestorage.app`;

  if (!isLocalHost(hostname)) {
    return {
      identity: "https://identitytoolkit.googleapis.com/v1",
      secureToken: "https://securetoken.googleapis.com/v1",
      storage: "https://firebasestorage.googleapis.com/v0",
      api: `https://${region}-${projectId}.cloudfunctions.net/${functionName}`,
      bucket,
      apiKey,
      isEmulator: false,
    };
  }

  const {
    auth: { port: authPort = DEFAULT_PORTS.auth } = {},
    functions: { port: functionsPort = DEFAULT_PORTS.functions } = {},
    storage: { port: storagePort = DEFAULT_PORTS.storage } = {},
  } = emulatorPorts || {};

  return {
    identity: `http://${hostname}:${authPort}/identitytoolkit.googleapis.com/v1`,
    secureToken: `http://${hostname}:${authPort}/securetoken.googleapis.com/v1`,
    storage: `http://${hostname}:${storagePort}/v0`,
    api: `http://${hostname}:${functionsPort}/${projectId}/${region}/${functionName}`,
    bucket,
    apiKey,
    isEmulator: true,
  };
}
