export async function createObjectStore(
  db: IDBDatabase,
  storeId: string,
  keyPath = "id",
  autoIncrement = false,
  indicies: any[] = []
) {
  try {
    if (db.objectStoreNames.contains(storeId)) {
      return null;
    }

    const store = db.createObjectStore(storeId, {
      keyPath,
      autoIncrement,
    });

    indicies.forEach(({ id = "name", keyPath = id, unique = false, multiEntry = false } = {}) => {
      store?.createIndex(id, keyPath, { unique, multiEntry });
    });
    return store;
  } catch (error) {
    console.error("indexedDB createObjectStore error", error);
    return null;
  }
}
