import { createObjectStore } from "./createObjectStore";
import type { OpenOptions } from "./types";

export function openDatabase(options: OpenOptions): Promise<{ db; upgradedTo }> {
  return new Promise((onsuccess, onerror) => {
    let upgradedTo: number;

    const { name, version = 1, stores } = options;
    const rq = window.indexedDB.open(name, version);

    rq.onerror = onerror;

    rq.onsuccess = async (event: any) => {
      const db = event.target.result;

      onsuccess({ db, upgradedTo });
    };

    rq.onupgradeneeded = (event: any) => {
      const db = event.target.result;

      upgradedTo = db.version;

      Object.entries(stores || { items: {} }).forEach(
        ([storeId, { keyPath = "id", autoIncrement = false, indicies = [] }]) => {
          createObjectStore(db, storeId, keyPath, autoIncrement, indicies);
        }
      );
    };
  });
}
