import { WebClientService } from "@/core";

export class LocalStorage extends WebClientService {
  __getStateProperty(propName: string) {
    return this.localStorage.get(propName);
  }

  __stateChanged(changes: Map<string, any>) {
    changes.forEach((value, propName) => {
      this.localStorage.set(propName, value);
    });
  }
}
